            if isinstance(data, dict):
                # Merge into rec, but also preserve existing? The json operator extracts fields, so merge data into rec, overriding?
                # For from field case, we merge data fields into rec as well (as observed: json from js kept js field and added a)
                # So merge data into rec, but if data contains nested, keep as is
