def make_hashable(v):
    # Convert value to hashable: if already hashable, return, else use json string
    try:
        hash(v)
        return v
    except:
        # For unhashable like dict, list, use json dumps
        try:
            return json.dumps(v, sort_keys=True)
        except:
            return str(v)

