    def __init__(self, left,right): self.left=left; self.right=right
    def match(self, line): return self.left.match(line) or self.right.match(line)
    def __repr__(self): return f"({self.left} OR {self.right})"

# Filter tokenizer and parser
def tokenize_filter(s):
    tokens=[]
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if c.isspace():
            i+=1
            continue
        if c=='(':
            tokens.append(('LPAREN','('))
            i+=1
            continue
        if c==')':
            tokens.append(('RPAREN',')'))
            i+=1
            continue
        if c=='"' or c=="'":
            quote=c
            j=i+1
            buf=[]
            while j<n:
                if s[j]=='\\' and j+1<n:
                    # handle escaped quote?
                    # In filter quoted, backslash escapes?
                    # We saw "\"a \"b\" c\"" matched a "b" c, so backslash escapes quote
                    if s[j+1]==quote:
                        buf.append(quote)
                        j+=2
                        continue
                    else:
                        buf.append(s[j])
                        j+=1
                        continue
                if s[j]==quote:
                    break
                buf.append(s[j])
                j+=1
            if j>=n:
                raise ValueError(f"Unterminated quoted filter at {i}")
            pattern=''.join(buf)
            tokens.append(('QUOTED', pattern, quote))
            i=j+1
            continue
        # check for AND, OR, NOT as whole words, uppercase only
        # Look ahead for AND, OR, NOT
        # AND: 3 chars, must be bounded by space or paren or start/end?
        # According to tests, "and" lowercase is treated as term, not operator. So only uppercase AND, OR, NOT are operators.
        # Also need to ensure it's a separate word, not part of other term containing AND? E.g., "android" should NOT be split into AND. So we need to check word boundaries: AND must be surrounded by spaces or parens or start/end, and not part of larger alphanumeric?
        # For simplicity, we check if substring at i is "AND" and next char is space or '(' or ')' or end, and previous char is space or '(' or ')' or start, and previous char not alnum.
        # Similarly OR (2 chars), NOT (3 chars)
        remaining=s[i:]
        # NOT
        if remaining.startswith('NOT'):
            # check boundary
            after=remaining[3:3+1]
            # after should be space, '(', or end, or not alnum? For NOT to be operator, after must be space or '(' or end
            if len(remaining)==3 or remaining[3].isspace() or remaining[3]=='(' or remaining[3]==')':
                # also check preceding char is space or '(' or start – but we already skipped spaces, and '(' tokenized separately, so preceding should be okay. But to avoid "ANOT" etc, we should ensure NOT is not part of longer word: we are at word boundary because we skipped spaces and parens.
                tokens.append(('NOT','NOT'))
                i+=3
                continue
        if remaining.startswith('AND'):
            if len(remaining)==3 or remaining[3].isspace() or remaining[3]=='(' or remaining[3]==')':
                tokens.append(('AND','AND'))
                i+=3
                continue
        if remaining.startswith('OR'):
            if len(remaining)==2 or remaining[2].isspace() or remaining[2]=='(' or remaining[2]==')':
                tokens.append(('OR','OR'))
                i+=2
                continue
        # Otherwise, it's an unquoted term: read until space or '(' or ')'
        # Term is sequence of characters not containing space, '(', ')', '"', "'"
        j=i
        while j<n and not s[j].isspace() and s[j] not in ('(',')','"',"'"):
            j+=1
        term=s[i:j]
        if term:
            tokens.append(('TERM',term))
        i=j
    return tokens

def parse_filter(tokens):
    # Implements precedence: NOT highest, AND next (including implicit AND), OR lowest
    # implicit AND is space-separated terms, which our tokenizer already discards spaces, so consecutive factors are implicit AND.
    # So grammar: or_expr = and_expr (OR and_expr)*
    # and_expr = factor ( (AND)? factor)* where AND is explicit or implicit (i.e., just next factor)
    # But inside parentheses, implicit AND not allowed per original observations? We'll implement two modes: allow_implicit = True for outer, False for inside parens? For simplicity, allow implicit everywhere for now, but we can add strictness later.

    # Use index pointer
    pos=[0]

    def peek():
        if pos[0]<len(tokens):
            return tokens[pos[0]]
        return None

    def consume(expected_type=None):
        if pos[0]>=len(tokens):
            return None
        tok=tokens[pos[0]]
        if expected_type and tok[0]!=expected_type:
            return None
        pos[0]+=1
        return tok

    def parse_factor(allow_implicit=True):
        tok=peek()
        if not tok:
            return None
        if tok[0]=='NOT':
            consume('NOT')
            child=parse_factor(allow_implicit)
            if child is None:
                raise ValueError("Expected factor after NOT")
            return NotNode(child)
        if tok[0]=='LPAREN':
            consume('LPAREN')
            # inside parens, we parse filter_expr but we need to check that after '(' there's no space? Our tokenizer already stripped spaces, so "( foo)" would have tokens: '(' , 'TERM' 'foo' , ')' – but we want to reject "( foo)" because space after '(' not allowed per original. Since tokenizer strips spaces, "( foo)" and "(foo)" would tokenize the same: '(' , TERM foo, ')'. So we cannot enforce space rule via tokenizer. We need to enforce via original string? For simplicity, we ignore that strictness and allow spaces.
            # For inner, we disallow implicit AND? Let's try to enforce: inside parens, we only allow explicit AND/OR, not implicit. So we need to parse and_expr without implicit.
            node=parse_or(allow_implicit=False)  # inside parens no implicit?
            # expect RPAREN
            if peek() and peek()[0]=='RPAREN':
                consume('RPAREN')
                return node
            else:
                # missing ')'
                raise ValueError("Expected ')'")
        if tok[0]=='TERM':
            # check if term is "*"
            term=tok[1]
            consume('TERM')
            if term=='*':
                return TrueNode()
            # unquoted term
            # check if contains '*': wildcard
            is_wildcard='*' in term
            return TermNode(term, is_quoted=False, case_sensitive=False, is_wildcard=is_wildcard)
        if tok[0]=='QUOTED':
            pattern=tok[1]
            consume('QUOTED')
            # quoted term: if pattern is "*" it should be literal star, not match all
            if pattern=='*':
                # quoted "*" should match literal "*", not all
                return TermNode(pattern, is_quoted=True, case_sensitive=True, is_wildcard=False)
            return TermNode(pattern, is_quoted=True, case_sensitive=True, is_wildcard=False)
        # Unexpected
        return None

    def parse_and(allow_implicit=True):
        left=parse_factor(allow_implicit)
        if left is None:
            return None
        while True:
            tok=peek()
            if not tok:
                break
            if tok[0]=='AND':
                consume('AND')
                right=parse_factor(allow_implicit)
                if right is None:
                    raise ValueError("Expected factor after AND")
                left=AndNode(left,right)
            elif tok[0] in ('TERM','QUOTED','LPAREN','NOT'):
                # implicit AND if allowed
                if not allow_implicit:
                    break
                # implicit AND
                right=parse_factor(allow_implicit)
                if right is None:
                    break
                left=AndNode(left,right)
            else:
                break
        return left

    def parse_or(allow_implicit=True):
        left=parse_and(allow_implicit)
        if left is None:
            return None
        while True:
            tok=peek()
            if tok and tok[0]=='OR':
                consume('OR')
                right=parse_and(allow_implicit)
                if right is None:
                    raise ValueError("Expected factor after OR")
                left=OrNode(left,right)
            else:
                break
        return left

    # Outer level allows implicit AND
    result=parse_or(allow_implicit=True)
    if pos[0]!=len(tokens):
        # leftover tokens -> unhandled input error
        # We need to produce error similar to original: "error: unhandled input\n  |\n1 | <query>\n  |        ^^^^^^^^\n  |\n"
        leftover=' '.join([t[1] if len(t)>1 else t[0] for t in tokens[pos[0]:]])
        # For error message, we need original string and position
        # We'll raise an exception with details
        raise ValueError(f"Unhandled input: {leftover}")
    if result is None:
        # empty filter -> TrueNode (match all)
        return TrueNode()
    return result

def build_filter(query_part):
    # query_part is string before first '|'
    # If empty or whitespace only, return TrueNode
    if query_part is None or query_part.strip()=='':
        return TrueNode()
    try:
        toks=tokenize_filter(query_part)
    except Exception as e:
        raise ValueError(f"Failed to tokenize filter: {e}")
    if not toks:
        return TrueNode()
    try:
        node=parse_filter(toks)
        return node
    except Exception as e:
        # For unhandled input, we need to produce specific error format
        # We'll re-raise with context
        raise

