# Utility to split pipeline by '|' not inside quotes
def split_pipeline(query):
    # Returns list of parts (strings)
    parts=[]
    buf=[]
    in_double=False
    in_single=False
    escape=False
    for ch in query:
        if escape:
            buf.append(ch)
            escape=False
            continue
        if ch=='\\':
            # escape next char, but keep
            escape=True
            buf.append(ch)
            continue
        if ch=='"' and not in_single:
            in_double=not in_double
            buf.append(ch)
            continue
        if ch=="'" and not in_double:
            in_single=not in_single
            buf.append(ch)
            continue
        if ch=='|' and not in_double and not in_single:
            parts.append(''.join(buf))
            buf=[]
            continue
        buf.append(ch)
    parts.append(''.join(buf))
    return parts

