        if len(args)!=1: raise EvalError("isEmpty expects 1 arg")
        v=args[0]
        return v is None or (isinstance(v,str) and v=="")
    if lname=='isblank':
        if len(args)!=1: raise EvalError("isBlank expects 1 arg")
        v=args[0]
        return v is None or (isinstance(v,str) and v.strip()=="")
    if lname=='isnumeric':
        if len(args)!=1: raise EvalError("isNumeric expects 1 arg")
        v=args[0]
        if isinstance(v,(int,float)):
            return True
        if isinstance(v,str):
            try:
                float(v)
                return True
            except:
                return False
        return False
    if lname=='if':
        # Actually if is handled as IfExpr, but if called as function?
        if len(args)!=3:
            raise EvalError("if expects 3 args")
        cond, tval, fval=args
        return tval if bool(cond) else fval
    raise EvalError(f"Unknown function {name}")

def parse_date_string(s):
    # Try multiple formats
    s=s.strip()
    # Try isoformat with Z
    try:
        # Replace Z with +00:00
        if s.endswith('Z'):
            s2=s[:-1]+'+00:00'
            dt=datetime.datetime.fromisoformat(s2)
            return dt
        else:
            # Try fromisoformat
            dt=datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt=dt.replace(tzinfo=datetime.timezone.utc)
            return dt
    except:
        pass
    # Try other formats using datetime.strptime
    fmts=[
        "%Y-%m-%dT%H:%M:%S%z",
        "%Y-%m-%dT%H:%M:%S.%f%z",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d",
        "%Y/%m/%d",
        "%b %d %Y",
        "%b %d %Y %H:%M:%S",
        "%d %b %Y",
        "%d %b %Y %H:%M:%S",
        "%Y-%m-%d %H:%M:%S%z",
        "%Y-%m-%d %H:%M:%S.%f",
        "%Y-%m-%d %H:%M:%S.%f%z",
        "%a %b %d %H:%M:%S %Y",
        "%a %b %d %H:%M:%S %Z %Y",
        "%m/%d/%Y",
        "%d/%m/%Y",
    ]
    for fmt in fmts:
        try:
            dt=datetime.datetime.strptime(s, fmt)
            if dt.tzinfo is None:
                dt=dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except:
            continue
    # Try email date?
    # Fallback: try to parse with dateutil if available
    try:
        from dateutil import parser
        dt=parser.parse(s)
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except:
        pass
    return None

# Expression parser for where and field expr

# We'll implement a recursive descent expression parser handling:
# - literals: numbers, strings ("..."), booleans? true/false, null?
# - field references: identifier, possibly with . and [index] and ["field"] 
# - function calls: identifier '(' args ')'
# - unary: !, -
# - binary: *,/,+,-, comparison, and/or

# Tokenization for expression

def tokenize_expr(s):
    tokens=[]
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if c.isspace():
            i+=1
            continue
        if c in ('(',')',',','[',']','.'):
            tokens.append((c,c))
            i+=1
            continue
        if c in ('+','-','*','/'):
            # Could be part of number? Handled later
            # Also check for >=, <=, ==, !=, <>, &&, ||
            # Lookahead
            if c=='=' and i+1<n and s[i+1]=='=':
                tokens.append(('==','=='))
                i+=2
                continue
            if c=='!' and i+1<n and s[i+1]=='=':
                tokens.append(('!=','!='))
                i+=2
                continue
            if c=='<' and i+1<n and s[i+1]=='>':
                tokens.append(('!=','<>'))
                i+=2
                continue
            if c=='<' and i+1<n and s[i+1]=='=':
                tokens.append(('<=','<='))
                i+=2
                continue
            if c=='>' and i+1<n and s[i+1]=='=':
                tokens.append(('>=','>='))
                i+=2
                continue
            if c=='&' and i+1<n and s[i+1]=='&':
                tokens.append(('&&','&&'))
                i+=2
                continue
            if c=='|' and i+1<n and s[i+1]=='|':
                tokens.append(('||','||'))
                i+=2
                continue
            if c in ('<','>','!'):
                # single char comparison or not
                tokens.append((c,c))
                i+=1
                continue
            tokens.append((c,c))
            i+=1
            continue
        if c=='=' and i+1<n and s[i+1]=='=':
            tokens.append(('==','=='))
            i+=2
            continue
        if c=='!' and i+1<n and s[i+1]=='=':
            tokens.append(('!=','!='))
            i+=2
            continue
        if c=='<':
            if i+1<n and s[i+1]=='>':
                tokens.append(('!=','<>'))
                i+=2
                continue
            if i+1<n and s[i+1]=='=':
                tokens.append(('<=','<='))
                i+=2
                continue
            tokens.append(('<','<'))
            i+=1
            continue
        if c=='>':
            if i+1<n and s[i+1]=='=':
                tokens.append(('>=','>='))
                i+=2
                continue
            tokens.append(('>','>'))
            i+=1
            continue
        if c=='&' and i+1<n and s[i+1]=='&':
            tokens.append(('&&','&&'))
            i+=2
            continue
        if c=='|' and i+1<n and s[i+1]=='|':
            tokens.append(('||','||'))
            i+=2
            continue
        if c=='"' or c=="'":
            quote=c
            j=i+1
            buf=[]
            while j<n:
                if s[j]=='\\' and j+1<n:
                    # handle escaped quote and other escapes
                    if s[j+1]==quote or s[j+1]=='\\':
                        buf.append(s[j+1])
                        j+=2
                        continue
                    # For simplicity, handle \n, \t etc?
                    # We'll just keep backslash + char as decoded?
                    # Use python's unicode_escape?
                    # For now, handle common escapes
                    esc=s[j+1]
                    if esc=='n':
                        buf.append('\n')
                    elif esc=='t':
                        buf.append('\t')
                    elif esc=='r':
                        buf.append('\r')
                    else:
                        buf.append(esc)
                    j+=2
                    continue
                if s[j]==quote:
                    break
                buf.append(s[j])
                j+=1
            if j>=n:
                raise ValueError(f"Unterminated string at {i}")
            string=''.join(buf)
            tokens.append(('STRING', string, quote))
            i=j+1
            continue
        # number?
        if c.isdigit() or (c=='.' and i+1<n and s[i+1].isdigit()):
            j=i
            has_dot=False
            while j<n and (s[j].isdigit() or s[j]=='.' or s[j].lower()=='e' or s[j] in ('+','-')):
                # be careful with e+-
                # Simplify: parse number with regex
                # We'll gather until not part of number
                # Actually handle exponent: e[+-]?\d+
                # We'll just use regex matching from i
                break
            # Use regex to match number
            m=re.match(r'-?\d+(\.\d*)?([eE][+-]?\d+)?', s[i:])
            if m:
                num_str=m.group(0)
                # Try int then float
                try:
                    if '.' in num_str or 'e' in num_str.lower():
                        val=float(num_str)
                    else:
                        val=int(num_str)
                    tokens.append(('NUMBER', val, num_str))
                    i+=len(num_str)
                    continue
                except:
                    pass
        # identifier or keyword
        if c.isalpha() or c=='_' or c=='$':
            j=i
            while j<n and (s[j].isalnum() or s[j] in ('_','$')):
                j+=1
            ident=s[i:j]
            # check for keywords: and, or, true, false, null
            low=ident.lower()
            if low in ('and','or'):
                tokens.append((low, ident))
            elif low in ('true','false'):
                tokens.append(('BOOL', low=='true', ident))
            elif low=='null':
                tokens.append(('NULL', None, ident))
            else:
                tokens.append(('IDENT', ident))
            i=j
            continue
        # If we reach here, it's an unexpected char, like '?' etc – skip?
        # For field refs like ["a b"] – we need to handle brackets with quoted string inside?
        # Our tokenizer already handles [ and ] and quoted strings.
        # For ["a b"], tokens would be: '[', STRING 'a b', ']'
        # We'll handle that in parser.

        # For other, treat as single char
        tokens.append((c,c))
        i+=1
    return tokens

# Expression parser
def parse_expression(s):
    toks=tokenize_expr(s)
    pos=[0]

    def peek():
        if pos[0]<len(toks):
            return toks[pos[0]]
        return None

    def consume(expected=None):
        if pos[0]>=len(toks):
            return None
        tok=toks[pos[0]]
        if expected and tok[0]!=expected:
            return None
        pos[0]+=1
        return tok

    def parse_primary():
        tok=peek()
        if not tok:
            raise ValueError("Unexpected end of expression")
        if tok[0]=='(':
            consume('(')
            expr=parse_or()
            if not peek() or peek()[0]!=')':
                raise ValueError("Expected ')'")
            consume(')')
            return expr
        if tok[0]=='NUMBER':
            consume()
            return Literal(tok[1])
        if tok[0]=='STRING':
            consume()
            return Literal(tok[1])
        if tok[0]=='BOOL':
            consume()
            return Literal(tok[1])
        if tok[0]=='NULL':
            consume()
            return Literal(None)
        if tok[0]=='IDENT':
            # Could be function call, field ref, or field ref with path
            ident=tok[1]
            consume('IDENT')
            # Check if next is '(' -> function call
            if peek() and peek()[0]=='(':
                consume('(')
                args=[]
                if peek() and peek()[0]!=')':
                    while True:
                        args.append(parse_or())
                        if peek() and peek()[0]==',':
                            consume(',')
                        else:
                            break
                if not peek() or peek()[0]!=')':
                    raise ValueError("Expected ')' in function call")
                consume(')')
                # Special handling for 'if' which is keyword but also function? It's handled as function with 3 args
                if ident.lower()=='if':
                    if len(args)!=3:
                        raise ValueError("if expects 3 args")
                    return IfExpr(args[0], args[1], args[2])
                return FuncCall(ident, args)
            else:
                # Field reference, possibly with . and [index] and ["field"] etc
                # We have already consumed first ident, now parse chain
                path=[ident]
                while True:
                    nxt=peek()
                    if not nxt:
                        break
                    if nxt[0]=='.':
                        consume('.')
                        # expect IDENT or NUMBER or STRING? For .key, key is IDENT
                        # But also could be ["field"]? No, dot followed by ident
                        if peek() and peek()[0]=='IDENT':
                            path.append(peek()[1])
                            consume('IDENT')
                        else:
                            raise ValueError("Expected identifier after '.'")
                    elif nxt[0]=='[':
                        consume('[')
                        # Inside brackets, can be NUMBER or STRING or IDENT? For array index, number or negative number? For field escape ["field"], it's string
                        inner=peek()
                        if not inner:
                            raise ValueError("Expected ']'")
                        if inner[0]=='NUMBER':
                            # index
                            idx=int(inner[1])
                            path.append(idx)
                            consume('NUMBER')
                        elif inner[0]=='STRING':
                            # field name with spaces etc
                            # For ["a b"], the string is field name
                            path.append(inner[1])
                            consume('STRING')
                        elif inner[0]=='IDENT':
                            # Could be field name without quotes? Not typical
                            path.append(inner[1])
                            consume('IDENT')
                        else:
                            # Could be expression? For simplicity, handle string
                            raise ValueError(f"Unexpected token in brackets: {inner}")
                        if not peek() or peek()[0]!=']':
                            raise ValueError("Expected ']'")
                        consume(']')
                    else:
                        break
                return FieldRef(path)
        if tok[0]=='[':
            # This handles escaped field name at beginning: ["a b"] 
            # Parse as field ref starting with bracket
            consume('[')
            inner=peek()
            if not inner:
                raise ValueError("Expected field name in brackets")
            if inner[0]=='STRING':
                field_name=inner[1]
                consume('STRING')
                if not peek() or peek()[0]!=']':
                    raise ValueError("Expected ']'")
                consume(']')
                # Now possibly followed by . or [ etc
                path=[field_name]
                while True:
                    nxt=peek()
                    if not nxt:
                        break
                    if nxt[0]=='.':
                        consume('.')
                        if peek() and peek()[0]=='IDENT':
                            path.append(peek()[1])
                            consume('IDENT')
                        else:
                            raise ValueError("Expected identifier after '.'")
                    elif nxt[0]=='[':
                        consume('[')
                        inner2=peek()
                        if inner2[0]=='NUMBER':
                            idx=int(inner2[1])
                            path.append(idx)
                            consume('NUMBER')
                        elif inner2[0]=='STRING':
                            path.append(inner2[1])
                            consume('STRING')
                        else:
                            raise ValueError("Unexpected in brackets")
                        if not peek() or peek()[0]!=']':
                            raise ValueError("Expected ']'")
                        consume(']')
                    else:
                        break
                return FieldRef(path)
            else:
                raise ValueError("Expected string in brackets for field escape")

        raise ValueError(f"Unexpected token {tok}")

    def parse_unary():
        tok=peek()
        if tok and tok[0] in ('!','-'):
            # '!' is not, '-' is negation?
            # But '-' as unary only for numbers? We'll treat
            op=tok[0]
            consume()
            operand=parse_unary()
            return UnaryOp(op, operand)
        return parse_primary()

    def parse_mul():
        left=parse_unary()
        while True:
            tok=peek()
            if tok and tok[0] in ('*','/'):
                op=tok[0]
                consume()
                right=parse_unary()
                left=BinaryOp(op,left,right)
            else:
                break
        return left

    def parse_add():
        left=parse_mul()
        while True:
            tok=peek()
            if tok and tok[0] in ('+','-'):
                op=tok[0]
                consume()
                right=parse_mul()
                left=BinaryOp(op,left,right)
            else:
                break
        return left

    def parse_comparison():
        left=parse_add()
        while True:
            tok=peek()
            if tok and tok[0] in ('==','!=','<','>','<=','>='):
                op=tok[0]
                consume()
                right=parse_add()
                left=BinaryOp(op,left,right)
            else:
                break
        return left

    def parse_and():
        left=parse_comparison()
        while True:
            tok=peek()
            if tok and tok[0] in ('and','&&'):
                op=tok[0]
                consume()
                right=parse_comparison()
                left=BinaryOp(op,left,right)
            else:
                break
        return left

    def parse_or():
        left=parse_and()
        while True:
            tok=peek()
            if tok and tok[0] in ('or','||'):
                op=tok[0]
                consume()
                right=parse_and()
                left=BinaryOp(op,left,right)
            else:
                break
        return left

    result=parse_or()
    if pos[0]!=len(toks):
        leftover=toks[pos[0]:]
        raise ValueError(f"Unhandled tokens: {leftover}")
    return result

