def parse_logfmt(s):
    # Parse logfmt: key=value pairs, value can be quoted, numbers, booleans.
    # Implement simple parser
    # Returns dict or None if fails? According to original, if not valid logfmt, drop. But what is valid? We saw "a= b=2" gave {"b":2} (a dropped because empty value). So maybe always succeeds? Let's implement best-effort.
    # Use regex to find k=v
