    # Simplified: tokenize by spaces not inside quotes.
    tokens=[]
    buf=[]
    in_quotes=False
    quote_char=None
    escape=False
    for ch in s:
        if escape:
            buf.append(ch)
            escape=False
            continue
        if ch=='\\':
            escape=True
            buf.append(ch)
            continue
        if ch in ('"', "'") and not in_quotes:
            in_quotes=True
            quote_char=ch
            buf.append(ch)
        elif ch==quote_char and in_quotes:
            in_quotes=False
            quote_char=None
            buf.append(ch)
        elif ch.isspace() and not in_quotes:
            if buf:
                tokens.append(''.join(buf))
                buf=[]
        else:
            buf.append(ch)
    if buf:
        tokens.append(''.join(buf))
    result={}
    for tok in tokens:
        if '=' not in tok:
            # If token without '=', maybe skip?
            continue
        k,v=tok.split('=',1)
        if not k:
            continue
        # Strip quotes from v
        v=v.strip()
        if len(v)>=2 and ((v[0]=='"' and v[-1]=='"') or (v[0]=="'" and v[-1]=="'")):
            # Unquote, handling escapes?
            inner=v[1:-1]
            # Unescape \" etc?
            # For simplicity, replace \" with "
            inner=inner.replace('\\"', '"').replace("\\'", "'").replace('\\\\','\\')
            # Try to parse as number/bool?
            result[k]=parse_logfmt_value(inner, is_quoted=True)
        else:
            if v=='':
                # empty value -> skip? We saw "a= b=2" gave only b, so a with empty value skipped
                continue
            result[k]=parse_logfmt_value(v, is_quoted=False)
    # If no key=value pairs found, return None to indicate drop?
    if not result:
        # Check if line is empty? If empty, maybe return None?
        # For simplicity, if no pairs, return None (drop)
        if s.strip()=='':
            return None
        # If line has content but no valid pairs, maybe return None
        # But "a= b=2" had one valid pair, returned that.
        # If line is "not logfmt", no pairs, should drop.
        return None if not result else result
    return result

def parse_logfmt_value(v, is_quoted):
    # Try to parse as bool, number, else string
    low=v.lower()
    if not is_quoted:
        if low=='true':
            return True
        if low=='false':
            return False
        # try int
        try:
            if '.' not in v and 'e' not in low:
                return int(v)
            else:
                return float(v)
        except:
