def convert_value(v):
    # Try to convert string to int, float, bool, etc.
    if not isinstance(v, str):
        return v
    s=v.strip()
    if s=='':
        return s
    low=s.lower()
    if low=='true':
        return True
    if low=='false':
        return False
    # Try int
    try:
        # Check if it's integer (no dot, no e)
        if '.' not in s and 'e' not in low and 'E' not in s:
            return int(s)
    except:
        pass
    try:
        return float(s)
    except:
        pass
    return v

