class FieldsOp(Operator):
    def __init__(self, mode, fields):
        # mode: '+' , '-' , 'only', 'except' etc
        # '+' or 'only' means keep only listed fields
        # '-' or 'except' means drop listed fields
        self.mode=mode
        self.fields=fields

    def process_record(self, rec, raw):
        # fields is list of field names (could be escaped ["field"])
        # mode determines keep or drop
        if self.mode in ('+','only'):
            new_rec={}
            for f in self.fields:
                if f in rec:
                    new_rec[f]=rec[f]
            return new_rec
        else: # '-' or 'except'
            new_rec=rec.copy()
            for f in self.fields:
                if f in new_rec:
                    del new_rec[f]
            return new_rec

    def process(self, records_with_raw):
        out=[]
        for rec, raw in records_with_raw:
            new_rec=self.process_record(rec, raw)
            out.append((new_rec, raw))
        return out

