# --- Expression parsing (simplified but functional) ---

# Reuse earlier tokenize_expr and parse_expression but with improvements

def tokenize_expr(s):
    tokens=[]
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if c.isspace():
            i+=1
            continue
        if c in ('(',')',',','[',']','.'):
            tokens.append((c,c))
            i+=1
            continue
        # Handle operators >=, <=, ==, !=, <>
        if s[i:i+2]=='==':
            tokens.append(('==','=='))
            i+=2
            continue
        if s[i:i+2]=='!=':
            tokens.append(('!=','!='))
            i+=2
            continue
        if s[i:i+2]=='<>':
            tokens.append(('!=','<>'))
            i+=2
            continue
        if s[i:i+2]=='>=':
            tokens.append(('>=','>='))
            i+=2
            continue
        if s[i:i+2]=='<=':
            tokens.append(('<=','<='))
            i+=2
            continue
        if s[i:i+2]=='&&':
            tokens.append(('&&','&&'))
            i+=2
            continue
        if s[i:i+2]=='||':
            tokens.append(('||','||'))
            i+=2
            continue
        if c in ('<','>','+','-','*','/','!'):
            tokens.append((c,c))
            i+=1
            continue
        if c=='"' or c=="'":
            quote=c
            j=i+1
            buf=[]
            while j<n:
                if s[j]=='\\' and j+1<n:
                    # handle escape
                    nxt=s[j+1]
                    if nxt==quote:
                        buf.append(quote)
                        j+=2
                        continue
                    elif nxt=='\\':
                        buf.append('\\')
                        j+=2
                        continue
                    elif nxt=='n':
                        buf.append('\n')
                        j+=2
                        continue
                    elif nxt=='t':
                        buf.append('\t')
                        j+=2
                        continue
                    elif nxt=='r':
                        buf.append('\r')
                        j+=2
                        continue
                    else:
                        buf.append(nxt)
                        j+=2
                        continue
                if s[j]==quote:
                    break
                buf.append(s[j])
                j+=1
            if j>=n:
                raise ValueError("Unterminated string")
            tokens.append(('STRING',''.join(buf)))
            i=j+1
            continue
        if c.isdigit() or (c=='.' and i+1<n and s[i+1].isdigit()):
            # number
            m=re.match(r'-?\d+(\.\d*)?([eE][+-]?\d+)?', s[i:])
            if m:
                num_str=m.group(0)
                try:
                    if '.' in num_str or 'e' in num_str.lower() or 'E' in num_str:
                        val=float(num_str)
                    else:
                        val=int(num_str)
                except:
                    val=float(num_str)
                tokens.append(('NUMBER', val))
                i+=len(num_str)
                continue
        if c.isalpha() or c=='_' or c=='$':
            j=i
            while j<n and (s[j].isalnum() or s[j] in ('_','$')):
                j+=1
            ident=s[i:j]
            low=ident.lower()
            if low in ('and','or'):
                tokens.append((low, ident))
            elif low=='true':
                tokens.append(('BOOL', True))
            elif low=='false':
                tokens.append(('BOOL', False))
            elif low=='null':
                tokens.append(('NULL', None))
            else:
                tokens.append(('IDENT', ident))
            i=j
            continue
        # For ["field"] syntax, we have [ and ] and string already handled
        # For other chars, skip
        i+=1
    return tokens

class Literal:
    def __init__(self, value): self.value=value
    def eval(self, rec): return self.value
    def __repr__(self): return f"Lit({self.value!r})"

class FieldRef:
    def __init__(self, path, raw_str=None):
        self.path=path
        self.raw=raw_str or '.'.join([str(p) for p in path])
    def eval(self, rec):
        cur=rec
        for part in self.path:
            if isinstance(part, int):
                if isinstance(cur, list):
                    idx=part
                    if idx<0:
                        idx=len(cur)+idx
                    if 0<=idx<len(cur):
                        cur=cur[idx]
                    else:
                        raise RuntimeError(f"No value for key \"{self.raw}\"")
                else:
                    raise RuntimeError(f"Expected array, found {type(cur).__name__}")
            else:
                if isinstance(cur, dict):
                    if part in cur:
                        cur=cur[part]
                    else:
                        raise RuntimeError(f"No value for key \"{part}\"")
                else:
                    raise RuntimeError(f"No value for key \"{part}\"")
        return cur
    def __repr__(self): return f"Field({self.path})"

class BinaryOp:
    def __init__(self, op, left,right): self.op=op; self.left=left; self.right=right
    def eval(self, rec):
        # For short-circuit and/or
        if self.op in ('and','&&'):
            lv=self.left.eval(rec)
            if not bool(lv):
                return False
            rv=self.right.eval(rec)
            return bool(rv)
        if self.op in ('or','||'):
            lv=self.left.eval(rec)
            if bool(lv):
                return True
            rv=self.right.eval(rec)
            return bool(rv)
        l=self.left.eval(rec)
        r=self.right.eval(rec)
        if self.op=='+': return eval_binary('+',l,r)
        if self.op=='-': return eval_binary('-',l,r)
        if self.op=='*': return eval_binary('*',l,r)
        if self.op=='/': return eval_binary('/',l,r)
        if self.op in ('==','!=','<>','<','>','<=','>='):
            if self.op=='<>': op='!='
            else: op=self.op
            return eval_comparison(op,l,r)
        raise RuntimeError(f"Unknown op {self.op}")

class UnaryOp:
    def __init__(self, op, operand): self.op=op; self.operand=operand
    def eval(self, rec):
        v=self.operand.eval(rec)
        if self.op=='!': return not bool(v)
        if self.op=='-':
            if isinstance(v,(int,float)):
                return -v
            raise RuntimeError(f"Expected numeric operands")
        raise RuntimeError(f"Unknown unary {self.op}")

class FuncCall:
    def __init__(self, name, args): self.name=name; self.args=args
    def eval(self, rec):
        evaled=[a.eval(rec) for a in self.args]
        return eval_function(self.name, evaled)
    def __repr__(self): return f"{self.name}({self.args})"

class IfExpr:
    def __init__(self, cond,true_expr,false_expr): self.cond=cond; self.true_expr=true_expr; self.false_expr=false_expr
    def eval(self, rec):
        c=self.cond.eval(rec)
        return self.true_expr.eval(rec) if bool(c) else self.false_expr.eval(rec)

def to_number(v):
    if isinstance(v,bool):
        return int(v)
    if isinstance(v,(int,float)):
        return v
    if isinstance(v,str):
        try:
            if '.' in v or 'e' in v.lower() or 'E' in v:
                return float(v)
            return int(v)
        except:
            raise RuntimeError(f"Expected number, found {v}")
    if v is None:
        raise RuntimeError(f"Expected number, found None")
    raise RuntimeError(f"Expected number, found {v}")

def eval_binary(op,l,r):
    # handle datetime and timedelta
    if isinstance(l, datetime.datetime) and isinstance(r, datetime.datetime):
        if op=='-':
            return l - r
        raise RuntimeError(f"Cannot {op} datetimes")
    if isinstance(l, datetime.datetime) and isinstance(r, datetime.timedelta):
        if op=='+': return l+r
        if op=='-': return l-r
        raise RuntimeError(f"Cannot {op} datetime and duration")
    if isinstance(l, datetime.timedelta) and isinstance(r, datetime.timedelta):
        if op=='+': return l+r
        if op=='-': return l-r
        raise RuntimeError(f"Cannot {op} durations")
    # numeric
    try:
        ln=l if isinstance(l,(int,float)) else to_number(l)
        rn=r if isinstance(r,(int,float)) else to_number(r)
    except RuntimeError as e:
        raise RuntimeError(f"Expected numeric operands, found {l} {op} {r}")
    if op=='+': return ln+rn
    if op=='-': return ln-rn
    if op=='*': return ln*rn
    if op=='/':
        if rn==0:
            raise RuntimeError("Division by zero")
        return ln/rn
    raise RuntimeError(f"Unknown binary {op}")

def eval_comparison(op,l,r):
    if l is None and r is None:
        return op=='==' 
    if l is None or r is None:
        if op=='==': return False
        if op=='!=': return True
        return False
    # numeric string handling for equality
    if op=='==':
        if isinstance(l,(int,float)) and isinstance(r,str):
            try:
                rn=to_number(r)
                return l==rn
            except:
                return l==r
        if isinstance(r,(int,float)) and isinstance(l,str):
            try:
                ln=to_number(l)
                return ln==r
            except:
                return l==r
        return l==r
    if op=='!=':
        if isinstance(l,(int,float)) and isinstance(r,str):
            try:
                rn=to_number(r)
                return l!=rn
            except:
                return l!=r
        if isinstance(r,(int,float)) and isinstance(l,str):
            try:
                ln=to_number(l)
                return ln!=r
            except:
                return l!=r
        return l!=r
    try:
        if op=='<': return l<r
        if op=='>': return l>r
        if op=='<=': return l<=r
        if op=='>=': return l>=r
    except:
        raise RuntimeError(f"Cannot compare {l} and {r}")

def eval_function(name, args):
    lname=name.lower()
    if lname in ('abs','acos','asin','atan','cbrt','ceil','cos','cosh','exp','expm1','floor','log','log10','log1p','round','sin','sinh','sqrt','tan','tanh','todegrees','toradians'):
        if len(args)!=1:
            raise RuntimeError(f"{name} expects 1 arg")
        v=to_number(args[0])
        if lname=='abs': return abs(v)
        if lname=='acos': return math.acos(v)
        if lname=='asin': return math.asin(v)
        if lname=='atan': return math.atan(v)
        if lname=='cbrt': return v**(1/3) if v>=0 else -((-v)**(1/3))
        if lname=='ceil': return math.ceil(v)
        if lname=='cos': return math.cos(v)
        if lname=='cosh': return math.cosh(v)
        if lname=='exp': return math.exp(v)
        if lname=='expm1': return math.expm1(v)
        if lname=='floor': return math.floor(v)
        if lname=='log': return math.log(v)
        if lname=='log10': return math.log10(v)
        if lname=='log1p': return math.log1p(v)
        if lname=='round': return round(v)
        if lname=='sin': return math.sin(v)
        if lname=='sinh': return math.sinh(v)
        if lname=='sqrt': return math.sqrt(v)
        if lname=='tan': return math.tan(v)
        if lname=='tanh': return math.tanh(v)
        if lname=='todegrees': return math.degrees(v)
        if lname=='toradians': return math.radians(v)
    if lname=='atan2':
        if len(args)!=2: raise RuntimeError("atan2 expects 2 args")
        return math.atan2(to_number(args[0]), to_number(args[1]))
    if lname=='hypot':
        if len(args)!=2: raise RuntimeError("hypot expects 2 args")
        return math.hypot(to_number(args[0]), to_number(args[1]))
    if lname=='concat':
        return ''.join([str(a) if a is not None else '' for a in args])
    if lname=='contains':
        if len(args)!=2: raise RuntimeError("contains expects 2 args")
        hay, needle=args
        if hay is None or needle is None:
            return False
        return str(needle) in str(hay)
    if lname=='length':
        if len(args)!=1: raise RuntimeError("length expects 1 arg")
        a=args[0]
        if a is None: return 0
        if isinstance(a,(list,dict)): return len(a)
        return len(str(a))
    if lname=='now':
        if len(args)!=0: raise RuntimeError("now expects 0 args")
        return datetime.datetime.now(datetime.timezone.utc)
    if lname=='num':
        if len(args)!=1: raise RuntimeError("num expects 1 arg")
        return to_number(args[0])
    if lname=='parsedate':
        if len(args)!=1: raise RuntimeError("parseDate expects 1 arg")
        s=str(args[0])
        dt=parse_date_string(s)
        if dt is None:
            raise RuntimeError(f"Failed to parse date {s}")
        return dt
    if lname=='parsehex':
        if len(args)!=1: raise RuntimeError("parseHex expects 1 arg")
        s=str(args[0]).strip()
        if s.lower().startswith('0x'):
            s=s[2:]
        try:
            return int(s,16)
        except:
            raise RuntimeError(f"invalid hex string -- {args[0]}")
    if lname=='substring':
        if len(args)<2 or len(args)>3: raise RuntimeError("substring expects 2 or 3 args")
        s=str(args[0]) if args[0] is not None else ""
        start=int(to_number(args[1]))
        if len(args)==3:
            end=int(to_number(args[2]))
            return s[start:end]
        else:
            return s[start:]
    if lname=='tolowercase':
        if len(args)!=1: raise RuntimeError("toLowerCase expects 1 arg")
        return str(args[0]).lower() if args[0] is not None else ""
    if lname=='touppercase':
        if len(args)!=1: raise RuntimeError("toUpperCase expects 1 arg")
        return str(args[0]).upper() if args[0] is not None else ""
    if lname=='isnull':
        if len(args)!=1: raise RuntimeError("isNull expects 1 arg")
        return args[0] is None
    if lname=='isempty':
        if len(args)!=1: raise RuntimeError("isEmpty expects 1 arg")
        v=args[0]
        return v is None or (isinstance(v,str) and v=="")
    if lname=='isblank':
        if len(args)!=1: raise RuntimeError("isBlank expects 1 arg")
        v=args[0]
        return v is None or (isinstance(v,str) and v.strip()=="")
    if lname=='isnumeric':
        if len(args)!=1: raise RuntimeError("isNumeric expects 1 arg")
        v=args[0]
        if isinstance(v,(int,float)): return True
        if isinstance(v,str):
            try:
                float(v)
                return True
            except:
                return False
        return False
    raise RuntimeError(f"Unknown function {name}")

def parse_date_string(s):
    s=s.strip()
    # Replace Z
    try:
        if s.endswith('Z'):
            s2=s[:-1]+'+00:00'
            dt=datetime.datetime.fromisoformat(s2)
            return dt
        dt=datetime.datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except:
        pass
    fmts=[
        "%Y-%m-%dT%H:%M:%S%z",
        "%Y-%m-%dT%H:%M:%S.%f%z",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d",
        "%Y/%m/%d",
        "%b %d %Y",
        "%b %d %Y %H:%M:%S",
        "%d %b %Y",
        "%Y-%m-%d %H:%M:%S%z",
        "%Y-%m-%d %H:%M:%S.%f",
        "%m/%d/%Y",
        "%d/%m/%Y",
    ]
    for fmt in fmts:
        try:
            dt=datetime.datetime.strptime(s, fmt)
            if dt.tzinfo is None:
                dt=dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except:
            continue
    try:
        from dateutil import parser
        dt=parser.parse(s)
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except:
        pass
    return None

def parse_expression(s):
    toks=tokenize_expr(s)
    pos=[0]
    def peek():
        return toks[pos[0]] if pos[0]<len(toks) else None
    def consume(expected=None):
        if pos[0]>=len(toks):
            return None
        tok=toks[pos[0]]
        if expected and tok[0]!=expected:
            return None
        pos[0]+=1
        return tok

    def parse_primary():
        tok=peek()
        if not tok:
            raise ValueError("Unexpected end")
        if tok[0]=='(':
            consume('(')
            expr=parse_or()
            if not peek() or peek()[0]!=')':
                raise ValueError("Expected ')'")
            consume(')')
            return expr
        if tok[0]=='NUMBER':
            consume()
            return Literal(tok[1])
        if tok[0]=='STRING':
            consume()
            return Literal(tok[1])
        if tok[0]=='BOOL':
            consume()
            return Literal(tok[1])
        if tok[0]=='NULL':
            consume()
            return Literal(None)
        if tok[0]=='IDENT':
            ident=tok[1]
            consume('IDENT')
            if peek() and peek()[0]=='(':
                consume('(')
                args=[]
                if peek() and peek()[0]!=')':
                    while True:
                        args.append(parse_or())
                        if peek() and peek()[0]==',':
                            consume(',')
                        else:
                            break
                if not peek() or peek()[0]!=')':
                    raise ValueError("Expected ')'")
                consume(')')
                if ident.lower()=='if':
                    if len(args)!=3:
                        raise ValueError("if expects 3 args")
                    return IfExpr(args[0],args[1],args[2])
                return FuncCall(ident,args)
            else:
                path=[ident]
                raw=ident
                while True:
                    nxt=peek()
                    if not nxt:
                        break
                    if nxt[0]=='.':
                        consume('.')
                        if peek() and peek()[0]=='IDENT':
                            path.append(peek()[1])
                            raw+='.'+peek()[1]
                            consume('IDENT')
                        else:
                            raise ValueError("Expected ident after '.'")
                    elif nxt[0]=='[':
                        consume('[')
                        inner=peek()
                        if not inner:
                            raise ValueError("Expected ']'")
                        if inner[0]=='NUMBER':
                            idx=int(inner[1])
                            path.append(idx)
                            raw+=f"[{idx}]"
                            consume('NUMBER')
                        elif inner[0]=='STRING':
                            field_name=inner[1]
                            path.append(field_name)
                            raw+=f'["{field_name}"]'
                            consume('STRING')
                        elif inner[0]=='IDENT':
                            path.append(inner[1])
                            raw+=f'[{inner[1]}]'
                            consume('IDENT')
                        else:
                            raise ValueError(f"Unexpected in []: {inner}")
                        if not peek() or peek()[0]!=']':
                            raise ValueError("Expected ']'")
                        consume(']')
                    else:
                        break
                return FieldRef(path, raw)
        if tok[0]=='[':
            consume('[')
            inner=peek()
            if not inner or inner[0]!='STRING':
                raise ValueError("Expected string in [\"\"]")
            field_name=inner[1]
            consume('STRING')
            if not peek() or peek()[0]!=']':
                raise ValueError("Expected ']'")
            consume(']')
            path=[field_name]
            raw=f'["{field_name}"]'
            while True:
                nxt=peek()
                if not nxt:
                    break
                if nxt[0]=='.':
                    consume('.')
                    if peek() and peek()[0]=='IDENT':
                        path.append(peek()[1])
                        raw+='.'+peek()[1]
                        consume('IDENT')
                    else:
                        raise ValueError("Expected ident after '.'")
                elif nxt[0]=='[':
                    consume('[')
                    inner2=peek()
                    if inner2[0]=='NUMBER':
                        idx=int(inner2[1])
                        path.append(idx)
                        raw+=f"[{idx}]"
                        consume('NUMBER')
                    elif inner2[0]=='STRING':
                        path.append(inner2[1])
                        raw+=f'["{inner2[1]}"]'
                        consume('STRING')
                    else:
                        raise ValueError("Unexpected")
                    if not peek() or peek()[0]!=']':
                        raise ValueError("Expected ']'")
                    consume(']')
                else:
                    break
            return FieldRef(path, raw)
        raise ValueError(f"Unexpected token {tok}")

    def parse_unary():
        tok=peek()
        if tok and tok[0] in ('!','-'):
            op=tok[0]
            consume()
            operand=parse_unary()
            return UnaryOp(op,operand)
        return parse_primary()

    def parse_mul():
        left=parse_unary()
        while True:
            tok=peek()
            if tok and tok[0] in ('*','/'):
                op=tok[0]
                consume()
                right=parse_unary()
