def split_pipeline(query):
    parts=[]
    buf=[]
    in_double=False
    in_single=False
    escape=False
    for ch in query:
        if escape:
            buf.append(ch)
            escape=False
            continue
        if ch=='\\':
            escape=True
            buf.append(ch)
            continue
        if ch=='"' and not in_single:
            in_double=not in_double
            buf.append(ch)
            continue
        if ch=="'" and not in_double:
            in_single=not in_single
            buf.append(ch)
            continue
        if ch=='|' and not in_double and not in_single:
            parts.append(''.join(buf))
            buf=[]
            continue
        buf.append(ch)
    parts.append(''.join(buf))
    return parts

def split_by_commas_outside_parens(s):
    parts=[]
    buf=[]
    depth=0
    in_double=False
    in_single=False
    escape=False
    for ch in s:
        if escape:
            buf.append(ch)
            escape=False
            continue
        if ch=='\\':
            escape=True
            buf.append(ch)
            continue
        if ch=='"' and not in_single:
            in_double=not in_double
            buf.append(ch)
            continue
        if ch=="'" and not in_double:
            in_single=not in_single
            buf.append(ch)
            continue
        if not in_double and not in_single:
            if ch=='(':
                depth+=1
            elif ch==')':
                depth-=1
            elif ch==',' and depth==0:
                parts.append(''.join(buf))
                buf=[]
                continue
        buf.append(ch)
    parts.append(''.join(buf))
    return parts

def parse_logfmt(s):
    tokens=[]
    buf=[]
    in_quotes=False
    quote_char=None
    escape=False
    for ch in s:
        if escape:
            buf.append(ch)
            escape=False
            continue
        if ch=='\\':
            escape=True
            buf.append(ch)
            continue
        if ch in ('"',"'") and not in_quotes:
            in_quotes=True
            quote_char=ch
            buf.append(ch)
        elif ch==quote_char and in_quotes:
            in_quotes=False
            quote_char=None
            buf.append(ch)
        elif ch.isspace() and not in_quotes:
            if buf:
                tokens.append(''.join(buf))
                buf=[]
        else:
            buf.append(ch)
    if buf:
        tokens.append(''.join(buf))
    result={}
    for tok in tokens:
        if '=' not in tok:
            continue
        k,v=tok.split('=',1)
        if not k:
            continue
        v=v.strip()
        if len(v)>=2 and ((v[0]=='"' and v[-1]=='"') or (v[0]=="'" and v[-1]=="'")):
            inner=v[1:-1]
            inner=inner.replace('\\"', '"').replace("\\'", "'").replace('\\\\','\\')
            result[k]=parse_logfmt_value(inner, True)
        else:
            if v=='':
                continue
            result[k]=parse_logfmt_value(v, False)
    if not result:
        return None
    return result

def parse_logfmt_value(v, is_quoted):
    low=v.lower()
    if not is_quoted:
        if low=='true':
            return True
        if low=='false':
            return False
        try:
            if '.' not in v and 'e' not in low:
                return int(v)
            else:
                return float(v)
        except:
            pass
    return v

def convert_value(v):
    if not isinstance(v,str):
        return v
    s=v.strip()
    if s=='':
        return s
    low=s.lower()
    if low=='true':
        return True
    if low=='false':
        return False
    try:
        if '.' not in s and 'e' not in low:
            return int(s)
    except:
        pass
    try:
        return float(s)
    except:
        pass
    return v

# Operator classes

class JsonOp:
    def __init__(self, from_field=None):
        self.from_field=from_field
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.from_field:
                    val=self.from_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.from_field.raw}\"")
                    if isinstance(val, (dict,list)):
                        data=val if isinstance(val, dict) else None
                        if isinstance(val, str):
                            data=json.loads(val)
                    else:
                        data=json.loads(str(val))
                else:
                    data=json.loads(raw)
                if isinstance(data, dict):
                    new_rec=rec.copy()
                    new_rec.update(data)
                    out.append((new_rec, raw))
                else:
                    # drop if not object
                    print(f"error: Expected JSON, found {raw}", file=sys.stderr)
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
            except Exception:
                print(f"error: Expected JSON, found {raw}", file=sys.stderr)
        return out

class LogfmtOp:
    def __init__(self, from_field=None):
        self.from_field=from_field
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.from_field:
                    val=self.from_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.from_field.raw}\"")
                    line=str(val)
                else:
                    line=raw
                data=parse_logfmt(line)
                if data is None:
                    # drop? Original drops if not valid logfmt? But error?
                    # For consistency, drop without error? Let's drop
                    continue
                new_rec=rec.copy()
                new_rec.update(data)
                out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
        return out

class SplitOp:
    def __init__(self, input_field=None, separator=',', as_field=None):
        self.input_field=input_field
        self.separator=separator
        self.as_field=as_field
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.input_field:
                    val=self.input_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.input_field.raw}\"")
                    s=str(val)
                else:
                    s=raw
                parts=s.split(self.separator)
                if self.as_field:
                    new_rec=rec.copy()
                    new_rec[self.as_field]=parts
                    out.append((new_rec, raw))
                else:
                    if self.input_field:
                        new_rec=rec.copy()
                        # override
                        if len(self.input_field.path)==1:
                            key=self.input_field.path[0]
                            new_rec[key]=parts
                        else:
                            new_rec[self.input_field.raw]=parts
                        out.append((new_rec, raw))
                    else:
                        new_rec=rec.copy()
                        new_rec['_split']=parts
                        out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
        return out

class ParseOp:
    def __init__(self, pattern, as_fields, from_field=None, nodrop=False, noconvert=False):
        self.pattern=pattern
        self.as_fields=as_fields
        self.from_field=from_field
        self.nodrop=nodrop
        self.noconvert=noconvert
        star_count=self.pattern.count('*')
        if star_count!=len(self.as_fields):
            print(f"Error: Wrong number of patterns for parse. Pattern has {star_count} but {len(self.as_fields)} were extracted", file=sys.stderr)
            sys.exit(1)
        # build regex
        segs=self.pattern.split('*')
        regex='^'
        for idx, seg in enumerate(segs):
            if seg!='':
                # convert whitespace to \s+
                sub=''
                j=0
                while j<len(seg):
                    if seg[j].isspace():
                        while j<len(seg) and seg[j].isspace():
                            j+=1
                        sub+=r'\s+'
                    else:
                        k=j
                        while k<len(seg) and not seg[k].isspace():
                            k+=1
                        literal=seg[j:k]
                        sub+=re.escape(literal)
                        j=k
                regex+=sub
            if idx < len(segs)-1:
                regex+=r'(.*)'
        regex+='$'
        self.regex=re.compile(regex, re.DOTALL)

    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.from_field:
                    val=self.from_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.from_field.raw}\"")
                    line=str(val)
                else:
                    line=raw
                m=self.regex.match(line)
                if not m:
                    if self.nodrop:
                        new_rec=rec.copy()
                        for f in self.as_fields:
                            new_rec[f]=None
                        out.append((new_rec, raw))
                    continue
                groups=m.groups()
                new_rec=rec.copy()
                for field_name, value in zip(self.as_fields, groups):
                    if self.noconvert:
                        new_rec[field_name]=value
                    else:
                        new_rec[field_name]=convert_value(value)
                out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
            except SystemExit:
                raise
            except Exception as e:
                print(f"error: {e}", file=sys.stderr)
        return out

class ParseRegexOp:
    def __init__(self, pattern, from_field=None, nodrop=False):
        self.pattern=pattern
        self.from_field=from_field
        self.nodrop=nodrop
        try:
            self.compiled=re.compile(pattern)
            total=self.compiled.groups
            named=len(self.compiled.groupindex)
            if total!=named:
                print(f"Error: Only named captures are supported", file=sys.stderr)
                sys.exit(1)
        except re.error as e:
            print(f"Error: Invalid regex {pattern}: {e}", file=sys.stderr)
            sys.exit(1)
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.from_field:
                    val=self.from_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.from_field.raw}\"")
                    line=str(val)
                else:
                    line=raw
                m=self.compiled.search(line)
                if not m:
                    if self.nodrop:
                        new_rec=rec.copy()
                        for name in self.compiled.groupindex.keys():
                            new_rec[name]=None
                        out.append((new_rec, raw))
                    continue
                new_rec=rec.copy()
                for name, value in m.groupdict().items():
                    if value is None:
                        new_rec[name]=None
                    else:
                        new_rec[name]=convert_value(value)
                out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
            except SystemExit:
                raise
        return out

class FieldsOp:
    def __init__(self, mode, fields):
        self.mode=mode
        self.fields=fields
    def process(self, records):
        out=[]
        for rec, raw in records:
            if self.mode in ('+','only'):
                new_rec={k:rec[k] for k in self.fields if k in rec}
                out.append((new_rec, raw))
            else:
                new_rec=rec.copy()
                for f in self.fields:
                    new_rec.pop(f, None)
                out.append((new_rec, raw))
        return out

