class SortOp:
    def __init__(self, by_exprs): # list of (expr, asc)
        self.by_exprs=by_exprs
    def process(self, records):
        def compare(a,b):
            rec_a=a[0]
            rec_b=b[0]
            for expr, asc in self.by_exprs:
                try:
                    va=expr.eval(rec_a)
                except:
                    va=None
                try:
                    vb=expr.eval(rec_b)
                except:
                    vb=None
                if va is None and vb is None:
                    cmp_res=0
                elif va is None:
                    cmp_res=-1
                elif vb is None:
                    cmp_res=1
                else:
                    try:
                        if va<vb: cmp_res=-1
                        elif va>vb: cmp_res=1
                        else: cmp_res=0
                    except:
                        sa=str(va); sb=str(vb)
                        if sa<sb: cmp_res=-1
                        elif sa>sb: cmp_res=1
                        else: cmp_res=0
                if cmp_res!=0:
                    if not asc:
                        cmp_res=-cmp_res
                    return cmp_res
            return 0
        return sorted(records, key=cmp_to_key(compare))

