def parse_operator_string(op_str):
    s=op_str.strip()
    if not s:
        raise ValueError("Empty operator")

    # sort
    if s.lower().startswith('sort'):
        rest=s[4:].strip()
        if not rest.lower().startswith('by'):
            raise ValueError("sort needs by")
        rest=rest[2:].strip()
        parts=split_by_commas_outside_parens(rest)
        by_exprs=[]
        for part in parts:
            part=part.strip()
            if not part:
                continue
            low=part.lower()
            asc=True
            if low.endswith(' desc'):
                asc=False
                expr_str=part[:-5].strip()
            elif low.endswith(' asc'):
                asc=True
                expr_str=part[:-4].strip()
            else:
                # check last word asc/desc
                words=part.rsplit(None,1)
                if len(words)==2 and words[1].lower() in ('asc','desc'):
                    asc=words[1].lower()=='asc'
                    expr_str=words[0]
                else:
                    expr_str=part
            expr=parse_expression(expr_str)
            by_exprs.append((expr, asc))
        return SortOp(by_exprs)

    if s.lower().startswith('limit'):
        rest=s[5:].strip()
        n=int(rest)
        return LimitOp(n)

    if s.lower().startswith('timeslice'):
        m=re.match(r'timeslice\s*\(\s*(.+)\s*\)\s+(\S+)(?:\s+as\s+(\S+))?', s, re.IGNORECASE)
        if not m:
            raise ValueError(f"Invalid timeslice {s}")
        expr_str=m.group(1)
        duration_str=m.group(2)
        as_field=m.group(3)
        expr=parse_expression(expr_str)
        return TimesliceOp(expr, duration_str, as_field)

    if s.lower().startswith('total'):
        m=re.match(r'total\s*\(\s*(.+)\s*\)(?:\s+as\s+(\S+))?', s, re.IGNORECASE)
        if not m:
            raise ValueError(f"Invalid total {s}")
        expr_str=m.group(1)
        as_field=m.group(2)
        # Check for 'by' – total does not support by
        if re.search(r'\bby\b', s, re.IGNORECASE):
            # Check if by is after as or in args? For total(v) by a, it should error with specific message
            # Original error: "error: unrecognized option, only the 'as' option is available"
