            print(f"error: unrecognized option, only the 'as' option is available", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"1 | {s}", file=sys.stderr)
            # Find position of 'by'
            idx=s.lower().find('by')
            print(f"  | {' '*idx}{'^'*len('by')}", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"Error: Failed to parse query", file=sys.stderr)
            sys.exit(1)
        expr=parse_expression(expr_str)
        return TotalOp(expr, as_field)

    if s.lower().startswith('fields'):
        rest=s[6:].strip()
        mode='-'
        if rest.startswith('+'):
            mode='+'
            rest=rest[1:].strip()
        elif rest.startswith('-'):
            mode='-'
            rest=rest[1:].strip()
        else:
            low=rest.lower()
            if low.startswith('only'):
