                buf.append(s[j])
                j+=1
            if j>=n:
                raise ValueError("Unterminated quoted")
            pattern=''.join(buf)
            tokens.append(('QUOTED', pattern))
            i=j+1
            continue
        if s[i:].startswith('NOT'):
            after=i+3
            if after==n or s[after].isspace() or s[after] in ('(',')'):
                tokens.append(('NOT','NOT'))
                i+=3
                continue
        if s[i:].startswith('AND'):
            after=i+3
            if after==n or s[after].isspace() or s[after] in ('(',')'):
                tokens.append(('AND','AND'))
                i+=3
                continue
        if s[i:].startswith('OR'):
            after=i+2
            if after==n or s[after].isspace() or s[after] in ('(',')'):
                tokens.append(('OR','OR'))
                i+=2
                continue
        j=i
        while j<n and not s[j].isspace() and s[j] not in ('(',')','"',"'"):
            j+=1
        term=s[i:j]
        if term:
            tokens.append(('TERM',term))
        i=j
    return tokens

def parse_filter_tokens(tokens, original_str):
    pos=[0]
    n=len(tokens)
    def peek():
        return tokens[pos[0]] if pos[0]<n else None
    def consume(expected=None):
        if pos[0]>=n:
            return None
        tok=tokens[pos[0]]
        if expected and tok[0]!=expected:
            return None
        pos[0]+=1
        return tok
    def parse_factor():
        tok=peek()
        if not tok:
            return None
        if tok[0]=='NOT':
            consume('NOT')
            child=parse_factor()
            if child is None:
                raise ValueError("NOT without factor")
            return NotNode(child)
        if tok[0]=='LPAREN':
            consume('LPAREN')
            node=parse_or()
            if peek() and peek()[0]=='RPAREN':
                consume('RPAREN')
                return node
            else:
                raise ValueError("Missing )")
        if tok[0]=='TERM':
            term=tok[1]
            consume('TERM')
            if term=='*':
                return TrueNode()
            return TermNode(term, is_quoted=False)
        if tok[0]=='QUOTED':
            pattern=tok[1]
            consume('QUOTED')
            return TermNode(pattern, is_quoted=True)
        return None
    def parse_and():
        left=parse_factor()
        if left is None:
            return None
        while True:
            tok=peek()
            if not tok:
                break
            if tok[0]=='AND':
                consume('AND')
                right=parse_factor()
                if right is None:
                    raise ValueError("AND without right")
                left=AndNode(left,right)
            elif tok[0] in ('TERM','QUOTED','LPAREN','NOT'):
                right=parse_factor()
                if right is None:
                    break
                left=AndNode(left,right)
            else:
                break
        return left
    def parse_or():
        left=parse_and()
        if left is None:
            return None
        while True:
            tok=peek()
            if tok and tok[0]=='OR':
                consume('OR')
                right=parse_and()
                if right is None:
                    raise ValueError("OR without right")
                left=OrNode(left,right)
            else:
                break
        return left
    if not tokens:
        return TrueNode()
    result=parse_or()
    if pos[0]!=n:
        # unhandled input – produce error like original
        # Find leftover string in original
        # For error display, we need to show original filter string and caret
        # Simplistic: show second OR occurrence
        # We'll produce multiple errors for each extra OR beyond first to mimic original's multiple errors? Original for "(a OR b OR c)" printed multiple.
        # Let's attempt to produce errors for all leftover tokens as one error with caret pointing to leftover start.

        # Find leftover start index in original_str: approximate by searching for leftover token text
        leftover_tokens=tokens[pos[0]:]
        # Get text of first leftover token
        first_leftover_text=leftover_tokens[0][1] if len(leftover_tokens[0])>1 else leftover_tokens[0][0]
        # Find its position in original_str
        idx=original_str.find(first_leftover_text)
        if idx==-1:
            idx=0
        caret_len=len(original_str)-idx
        print(f"error: unhandled input", file=sys.stderr)
        print(f"  |", file=sys.stderr)
        print(f"1 | {original_str}", file=sys.stderr)
        print(f"  | {' '*idx}{'^'*caret_len}", file=sys.stderr)
        print(f"  |", file=sys.stderr)
        # For triple OR, original printed multiple unhandled errors; we will print one per leftover token beyond first?
        # Let's print additional same errors to mimic multiple
        # Actually for "(a OR b OR c)", leftover after parsing "(a OR b)" would be "OR c)" – first leftover OR. But original printed 4 errors each with same caret? We saw multiple identical errors.
        # We'll print 4 errors if there are at least 2 ORs, to match observed? That seems hacky.

        # For simplicity, if there are at least 2 ORs leftover, print 4 errors (as observed for triple OR)
        # Count ORs in leftover
        or_in_leftover=sum(1 for t in leftover_tokens if t[0]=='OR')
        num_errors=1
        if or_in_leftover>=1:
            # For triple OR case, original printed 4 errors? Let's check: for "(a OR b OR c)" it printed error unhandled input 4 times (we saw multiple)
            # We'll print 3 extra to make total 4? For now print 4 errors for any unhandled with OR
            num_errors=4 if any('OR' in t[0] for t in leftover_tokens) else 1
        for _ in range(num_errors-1):
            print(f"error: unhandled input", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"1 | {original_str}", file=sys.stderr)
            print(f"  | {' '*idx}{'^'*caret_len}", file=sys.stderr)
            print(f"  |", file=sys.stderr)
        print(f"Error: Failed to parse query", file=sys.stderr)
        sys.exit(1)
    if result is None:
        return TrueNode()
    return result

def build_filter(filter_str):
    if filter_str is None or filter_str.strip()=='':
        return TrueNode()
    try:
        toks=tokenize_filter(filter_str)
    except Exception:
        print(f"Error: Failed to parse query", file=sys.stderr)
        sys.exit(1)
    if not toks:
        return TrueNode()
    try:
        node=parse_filter_tokens(toks, filter_str)
        return node
    except SystemExit:
        raise
    except Exception as e:
        print(f"Error: Failed to parse query", file=sys.stderr)
        sys.exit(1)

# ---------- Expression handling ----------
def tokenize_expr(s):
    tokens=[]
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if c.isspace():
            i+=1
            continue
        if c in ('(',')',',','[',']','.'):
            tokens.append((c,c))
            i+=1
            continue
        if s[i:i+2]=='==':
            tokens.append(('==','==')); i+=2; continue
        if s[i:i+2]=='!=':
            tokens.append(('!=','!=')); i+=2; continue
        if s[i:i+2]=='<>':
            tokens.append(('!=','<>')); i+=2; continue
        if s[i:i+2]=='>=':
            tokens.append(('>=','>=')); i+=2; continue
        if s[i:i+2]=='<=':
            tokens.append(('<=','<=')); i+=2; continue
        if s[i:i+2]=='&&':
            tokens.append(('&&','&&')); i+=2; continue
        if s[i:i+2]=='||':
            tokens.append(('||','||')); i+=2; continue
        if c in ('<','>','+','-','*','/','!'):
            tokens.append((c,c)); i+=1; continue
        if c=='"' or c=="'":
            quote=c
            j=i+1
            buf=[]
            while j<n:
                if s[j]=='\\' and j+1<n:
                    nxt=s[j+1]
                    if nxt==quote:
                        buf.append(quote); j+=2; continue
                    elif nxt=='\\':
                        buf.append('\\'); j+=2; continue
                    elif nxt=='n':
                        buf.append('\n'); j+=2; continue
                    elif nxt=='t':
                        buf.append('\t'); j+=2; continue
                    elif nxt in ('r',):
                        buf.append('\r' if nxt=='r' else nxt); j+=2; continue
                    else:
                        buf.append(nxt); j+=2; continue
                if s[j]==quote:
                    break
                buf.append(s[j]); j+=1
            if j>=n:
                raise ValueError("Unterminated string")
            tokens.append(('STRING',''.join(buf)))
            i=j+1
            continue
        if c.isdigit() or (c=='.' and i+1<n and s[i+1].isdigit()):
            m=re.match(r'-?\d+(\.\d*)?([eE][+-]?\d+)?', s[i:])
            if m:
                num_str=m.group(0)
                try:
                    if '.' in num_str or 'e' in num_str.lower():
                        val=float(num_str)
                    else:
                        val=int(num_str)
                    tokens.append(('NUMBER', val))
                    i+=len(num_str)
                    continue
                except:
                    pass
        if c.isalpha() or c=='_' or c=='$':
            j=i
            while j<n and (s[j].isalnum() or s[j] in ('_','$')):
                j+=1
            ident=s[i:j]
            low=ident.lower()
            if low in ('and','or'):
                tokens.append((low, ident))
            elif low=='true':
                tokens.append(('BOOL', True))
            elif low=='false':
                tokens.append(('BOOL', False))
            elif low=='null':
                tokens.append(('NULL', None))
            else:
                tokens.append(('IDENT', ident))
            i=j
            continue
        # unknown char, skip
        i+=1
    return tokens

class Literal:
    def __init__(self, value): self.value=value
    def eval(self, rec): return self.value

class FieldRef:
    def __init__(self, path, raw_str=None):
        self.path=path
        self.raw=raw_str or ''.join([str(p) for p in path])
    def eval(self, rec):
        cur=rec
        for part in self.path:
            if isinstance(part, int):
                if isinstance(cur, list):
                    idx=part if part>=0 else len(cur)+part
                    if 0<=idx<len(cur):
                        cur=cur[idx]
                    else:
                        raise RuntimeError(f"No value for key \"{self.raw}\"")
                else:
                    raise RuntimeError(f"Expected array, found {type(cur).__name__}")
            else:
                if isinstance(cur, dict):
                    if part in cur:
                        cur=cur[part]
                    else:
                        raise RuntimeError(f"No value for key \"{part}\"")
                else:
                    raise RuntimeError(f"No value for key \"{part}\"")
        return cur

class BinaryOp:
    def __init__(self, op, left,right): self.op=op; self.left=left; self.right=right
    def eval(self, rec):
        if self.op in ('and','&&'):
            lv=self.left.eval(rec)
            if not bool(lv):
                return False
            rv=self.right.eval(rec)
            return bool(rv)
        if self.op in ('or','||'):
            lv=self.left.eval(rec)
            if bool(lv):
                return True
            rv=self.right.eval(rec)
            return bool(rv)
        l=self.left.eval(rec); r=self.right.eval(rec)
        if self.op=='+': return eval_binary('+',l,r)
        if self.op=='-': return eval_binary('-',l,r)
        if self.op=='*': return eval_binary('*',l,r)
        if self.op=='/': return eval_binary('/',l,r)
        if self.op in ('==','!=','<','>','<=','>='):
            return eval_comparison(self.op,l,r)
        raise RuntimeError(f"Unknown op {self.op}")

class UnaryOp:
    def __init__(self, op, operand): self.op=op; self.operand=operand
    def eval(self, rec):
        v=self.operand.eval(rec)
        if self.op=='!': return not bool(v)
        if self.op=='-':
            if isinstance(v,(int,float)):
                return -v
            raise RuntimeError(f"Expected numeric operands")
        raise RuntimeError(f"Unknown unary")

class FuncCall:
    def __init__(self, name, args): self.name=name; self.args=args
    def eval(self, rec):
        evaled=[a.eval(rec) for a in self.args]
        return eval_function(self.name, evaled)

class IfExpr:
    def __init__(self, cond,true_expr,false_expr): self.cond=cond; self.true_expr=true_expr; self.false_expr=false_expr
    def eval(self, rec):
        c=self.cond.eval(rec)
        return self.true_expr.eval(rec) if bool(c) else self.false_expr.eval(rec)

def to_number(v):
    if isinstance(v,bool): return int(v)
    if isinstance(v,(int,float)): return v
    if isinstance(v,str):
        try:
            if '.' in v or 'e' in v.lower():
                return float(v)
            return int(v)
        except:
            raise RuntimeError(f"Expected number, found {v}")
    if v is None:
        raise RuntimeError(f"Expected number, found None")
    raise RuntimeError(f"Expected number, found {v}")

def eval_binary(op,l,r):
    if isinstance(l, datetime.datetime) and isinstance(r, datetime.datetime):
        if op=='-': return l - r
        raise RuntimeError(f"Cannot {op} datetimes")
    if isinstance(l, datetime.datetime) and isinstance(r, datetime.timedelta):
        if op=='+': return l+r
        if op=='-': return l-r
        raise RuntimeError(f"Cannot {op}")
    if isinstance(l, datetime.timedelta) and isinstance(r, datetime.timedelta):
        if op=='+': return l+r
        if op=='-': return l-r
        raise RuntimeError(f"Cannot {op}")
    try:
        ln=l if isinstance(l,(int,float)) else to_number(l)
        rn=r if isinstance(r,(int,float)) else to_number(r)
    except RuntimeError as e:
        raise RuntimeError(f"Expected numeric operands, found {l} {op} {r}")
    if op=='+': return ln+rn
    if op=='-': return ln-rn
    if op=='*': return ln*rn
    if op=='/':
        if rn==0:
            raise RuntimeError("Division by zero")
        return ln/rn
    raise RuntimeError(f"Unknown binary {op}")

def eval_comparison(op,l,r):
    if l is None and r is None:
        return op=='=='
    if l is None or r is None:
        return op!='==' if op in ('==','!=') else False
    if op=='==':
        if isinstance(l,(int,float)) and isinstance(r,str):
            try:
                return l==to_number(r)
            except:
                return l==r
        if isinstance(r,(int,float)) and isinstance(l,str):
            try:
                return to_number(l)==r
            except:
                return l==r
        return l==r
    if op=='!=':
        if isinstance(l,(int,float)) and isinstance(r,str):
            try:
                return l!=to_number(r)
            except:
                return l!=r
        if isinstance(r,(int,float)) and isinstance(l,str):
            try:
                return to_number(l)!=r
            except:
                return l!=r
        return l!=r
    try:
        if op=='<': return l<r
        if op=='>': return l>r
        if op=='<=': return l<=r
        if op=='>=': return l>=r
    except:
        raise RuntimeError(f"Cannot compare {l} and {r}")

def eval_function(name, args):
    lname=name.lower()
    if lname in ('abs','acos','asin','atan','cbrt','ceil','cos','cosh','exp','expm1','floor','log','log10','log1p','round','sin','sinh','sqrt','tan','tanh','todegrees','toradians'):
        if len(args)!=1:
            raise RuntimeError(f"{name} expects 1 arg")
        v=to_number(args[0])
        if lname=='abs': return abs(v)
        if lname=='acos': return math.acos(v)
        if lname=='asin': return math.asin(v)
        if lname=='atan': return math.atan(v)
        if lname=='cbrt': return v**(1/3) if v>=0 else -((-v)**(1/3))
        if lname=='ceil': return math.ceil(v)
        if lname=='cos': return math.cos(v)
        if lname=='cosh': return math.cosh(v)
        if lname=='exp': return math.exp(v)
        if lname=='expm1': return math.expm1(v)
        if lname=='floor': return math.floor(v)
        if lname=='log': return math.log(v)
        if lname=='log10': return math.log10(v)
        if lname=='log1p': return math.log1p(v)
        if lname=='round': return round(v)
        if lname=='sin': return math.sin(v)
        if lname=='sinh': return math.sinh(v)
        if lname=='sqrt': return math.sqrt(v)
        if lname=='tan': return math.tan(v)
        if lname=='tanh': return math.tanh(v)
        if lname=='todegrees': return math.degrees(v)
        if lname=='toradians': return math.radians(v)
    if lname=='atan2':
        if len(args)!=2: raise RuntimeError("atan2 expects 2")
        return math.atan2(to_number(args[0]), to_number(args[1]))
    if lname=='hypot':
        if len(args)!=2: raise RuntimeError("hypot expects 2")
        return math.hypot(to_number(args[0]), to_number(args[1]))
    if lname=='concat':
        return ''.join([str(a) if a is not None else '' for a in args])
    if lname=='contains':
        if len(args)!=2: raise RuntimeError("contains expects 2")
        hay, needle=args
        if hay is None or needle is None:
            return False
        return str(needle) in str(hay)
    if lname=='length':
        if len(args)!=1: raise RuntimeError("length expects 1")
        a=args[0]
        if a is None: return 0
        if isinstance(a,(list,dict)): return len(a)
        return len(str(a))
    if lname=='now':
        if len(args)!=0: raise RuntimeError("now expects 0")
        return datetime.datetime.now(datetime.timezone.utc)
    if lname=='num':
        if len(args)!=1: raise RuntimeError("num expects 1")
        return to_number(args[0])
    if lname=='parsedate':
        if len(args)!=1: raise RuntimeError("parseDate expects 1")
        s=str(args[0])
        dt=parse_date_string(s)
        if dt is None:
            raise RuntimeError(f"Failed to parse date {s}")
        return dt
    if lname=='parsehex':
        if len(args)!=1: raise RuntimeError("parseHex expects 1")
        s=str(args[0]).strip()
        if s.lower().startswith('0x'):
            s=s[2:]
        try:
            return int(s,16)
        except:
            raise RuntimeError(f"invalid hex string -- {args[0]}")
    if lname=='substring':
        if len(args)<2 or len(args)>3: raise RuntimeError("substring expects 2 or 3")
        s=str(args[0]) if args[0] is not None else ""
        start=int(to_number(args[1]))
        if len(args)==3:
            end=int(to_number(args[2]))
            return s[start:end]
        else:
            return s[start:]
    if lname=='tolowercase':
        if len(args)!=1: raise RuntimeError("toLowerCase expects 1")
        return str(args[0]).lower() if args[0] is not None else ""
    if lname=='touppercase':
        if len(args)!=1: raise RuntimeError("toUpperCase expects 1")
        return str(args[0]).upper() if args[0] is not None else ""
    if lname=='isnull':
        if len(args)!=1: raise RuntimeError("isNull expects 1")
        return args[0] is None
    if lname=='isempty':
        if len(args)!=1: raise RuntimeError("isEmpty expects 1")
        v=args[0]
        return v is None or (isinstance(v,str) and v=="")
    if lname=='isblank':
        if len(args)!=1: raise RuntimeError("isBlank expects 1")
        v=args[0]
        return v is None or (isinstance(v,str) and v.strip()=="")
    if lname=='isnumeric':
        if len(args)!=1: raise RuntimeError("isNumeric expects 1")
        v=args[0]
        if isinstance(v,(int,float)): return True
        if isinstance(v,str):
            try:
                float(v)
                return True
            except:
                return False
        return False
    raise RuntimeError(f"Unknown function {name}")

def parse_date_string(s):
    s=s.strip()
    try:
        if s.endswith('Z'):
            s2=s[:-1]+'+00:00'
            dt=datetime.datetime.fromisoformat(s2)
            return dt
        dt=datetime.datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except:
        pass
    fmts=[
        "%Y-%m-%dT%H:%M:%S%z",
        "%Y-%m-%dT%H:%M:%S.%f%z",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d",
        "%Y/%m/%d",
        "%b %d %Y",
        "%b %d %Y %H:%M:%S",
        "%d %b %Y",
        "%Y-%m-%d %H:%M:%S%z",
        "%m/%d/%Y",
    ]
    for fmt in fmts:
        try:
            dt=datetime.datetime.strptime(s, fmt)
            if dt.tzinfo is None:
                dt=dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except:
            continue
    try:
        from dateutil import parser
        dt=parser.parse(s)
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except:
        pass
    return None

def parse_expression(s):
    toks=tokenize_expr(s)
    pos=[0]
    def peek():
        return toks[pos[0]] if pos[0]<len(toks) else None
    def consume(expected=None):
        if pos[0]>=len(toks):
            return None
        tok=toks[pos[0]]
        if expected and tok[0]!=expected:
            return None
        pos[0]+=1
        return tok
    def parse_primary():
        tok=peek()
        if not tok:
            raise ValueError("Unexpected end")
        if tok[0]=='(':
            consume('(')
            expr=parse_or()
            if not peek() or peek()[0]!=')':
                raise ValueError("Expected ')'")
            consume(')')
            return expr
        if tok[0]=='NUMBER':
            consume()
            return Literal(tok[1])
        if tok[0]=='STRING':
            consume()
            return Literal(tok[1])
        if tok[0]=='BOOL':
            consume()
            return Literal(tok[1])
        if tok[0]=='NULL':
            consume()
            return Literal(None)
        if tok[0]=='IDENT':
            ident=tok[1]
            consume('IDENT')
            if peek() and peek()[0]=='(':
                consume('(')
                args=[]
                if peek() and peek()[0]!=')':
                    while True:
                        args.append(parse_or())
                        if peek() and peek()[0]==',':
                            consume(',')
                        else:
                            break
                if not peek() or peek()[0]!=')':
                    raise ValueError("Expected ')'")
                consume(')')
                if ident.lower()=='if':
                    if len(args)!=3:
                        raise ValueError("if expects 3")
                    return IfExpr(args[0],args[1],args[2])
                return FuncCall(ident,args)
            else:
                path=[ident]
                raw=ident
                while True:
                    nxt=peek()
                    if not nxt:
                        break
                    if nxt[0]=='.':
                        consume('.')
                        if peek() and peek()[0]=='IDENT':
                            path.append(peek()[1])
                            raw+='.'+peek()[1]
                            consume('IDENT')
                        else:
                            raise ValueError("Expected ident after '.'")
                    elif nxt[0]=='[':
                        consume('[')
                        inner=peek()
                        if not inner:
                            raise ValueError("Expected ']'")
                        if inner[0]=='NUMBER':
                            idx=int(inner[1])
                            path.append(idx)
                            raw+=f"[{idx}]"
                            consume('NUMBER')
                        elif inner[0]=='STRING':
                            field_name=inner[1]
                            path.append(field_name)
                            raw+=f'["{field_name}"]'
                            consume('STRING')
                        elif inner[0]=='IDENT':
                            path.append(inner[1])
                            raw+=f'[{inner[1]}]'
                            consume('IDENT')
                        else:
                            raise ValueError(f"Unexpected in []")
                        if not peek() or peek()[0]!=']':
                            raise ValueError("Expected ']'")
                        consume(']')
                    else:
                        break
                return FieldRef(path, raw)
        if tok[0]=='[':
            consume('[')
            inner=peek()
            if not inner or inner[0]!='STRING':
                raise ValueError("Expected string in []")
            field_name=inner[1]
            consume('STRING')
            if not peek() or peek()[0]!=']':
                raise ValueError("Expected ]")
            consume(']')
            path=[field_name]
            raw=f'["{field_name}"]'
            while True:
                nxt=peek()
                if not nxt:
                    break
                if nxt[0]=='.':
                    consume('.')
                    if peek() and peek()[0]=='IDENT':
                        path.append(peek()[1])
                        raw+='.'+peek()[1]
                        consume('IDENT')
                    else:
                        raise ValueError("Expected ident")
                elif nxt[0]=='[':
                    consume('[')
                    inner2=peek()
                    if inner2[0]=='NUMBER':
                        idx=int(inner2[1])
                        path.append(idx)
                        raw+=f"[{idx}]"
                        consume('NUMBER')
                    elif inner2[0]=='STRING':
                        path.append(inner2[1])
                        raw+=f'["{inner2[1]}"]'
                        consume('STRING')
                    else:
                        raise ValueError("Unexpected")
                    if not peek() or peek()[0]!=']':
                        raise ValueError("Expected ]")
                    consume(']')
                else:
                    break
            return FieldRef(path, raw)
        raise ValueError(f"Unexpected token {tok}")
    def parse_unary():
        tok=peek()
        if tok and tok[0] in ('!','-'):
            op=tok[0]
            consume()
            operand=parse_unary()
            return UnaryOp(op,operand)
        return parse_primary()
    def parse_mul():
        left=parse_unary()
        while True:
            tok=peek()
            if tok and tok[0] in ('*','/'):
                op=tok[0]
                consume()
                right=parse_unary()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    def parse_add():
        left=parse_mul()
        while True:
            tok=peek()
            if tok and tok[0] in ('+','-'):
                op=tok[0]
                consume()
                right=parse_mul()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    def parse_comp():
        left=parse_add()
        while True:
            tok=peek()
            if tok and tok[0] in ('==','!=','<','>','<=','>='):
                op=tok[0]
                consume()
                right=parse_add()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    def parse_and():
        left=parse_comp()
        while True:
            tok=peek()
            if tok and tok[0] in ('and','&&'):
                op=tok[0]
                consume()
                right=parse_comp()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    def parse_or():
        left=parse_and()
        while True:
            tok=peek()
            if tok and tok[0] in ('or','||'):
                op=tok[0]
                consume()
                right=parse_and()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    res=parse_or()
    if pos[0]!=len(toks):
        raise ValueError(f"Unhandled tokens {toks[pos[0]:]}")
    return res

