def split_pipeline(query):
    parts=[]
    buf=[]
    in_double=False
    in_single=False
    escape=False
    for ch in query:
        if escape:
            buf.append(ch)
            escape=False
            continue
        if ch=='\\':
            escape=True
            buf.append(ch)
            continue
        if ch=='"' and not in_single:
            in_double=not in_double
            buf.append(ch)
            continue
        if ch=="'" and not in_double:
            in_single=not in_single
            buf.append(ch)
            continue
        if ch=='|' and not in_double and not in_single:
            parts.append(''.join(buf))
            buf=[]
            continue
        buf.append(ch)
    parts.append(''.join(buf))
    return parts

def split_by_commas_outside_parens(s):
    parts=[]
    buf=[]
    depth=0
    in_double=False
    in_single=False
    escape=False
    for ch in s:
        if escape:
            buf.append(ch)
            escape=False
            continue
        if ch=='\\':
            escape=True
            buf.append(ch)
            continue
        if ch=='"' and not in_single:
            in_double=not in_double
            buf.append(ch)
            continue
        if ch=="'" and not in_double:
            in_single=not in_single
            buf.append(ch)
            continue
        if not in_double and not in_single:
            if ch=='(':
                depth+=1
            elif ch==')':
                depth-=1
            elif ch==',' and depth==0:
                parts.append(''.join(buf))
                buf=[]
                continue
        buf.append(ch)
    parts.append(''.join(buf))
    return parts

def parse_logfmt(s):
    tokens=[]
    buf=[]
    in_quotes=False
    quote_char=None
    escape=False
    for ch in s:
        if escape:
            buf.append(ch)
            escape=False
            continue
        if ch=='\\':
            escape=True
            buf.append(ch)
            continue
        if ch in ('"',"'") and not in_quotes:
            in_quotes=True
            quote_char=ch
            buf.append(ch)
        elif ch==quote_char and in_quotes:
            in_quotes=False
            quote_char=None
            buf.append(ch)
        elif ch.isspace() and not in_quotes:
            if buf:
                tokens.append(''.join(buf))
                buf=[]
        else:
            buf.append(ch)
    if buf:
        tokens.append(''.join(buf))
    result={}
    for tok in tokens:
        if '=' not in tok:
            continue
        k,v=tok.split('=',1)
        if not k:
            continue
        v=v.strip()
        if len(v)>=2 and ((v[0]=='"' and v[-1]=='"') or (v[0]=="'" and v[-1]=="'")):
            inner=v[1:-1]
            inner=inner.replace('\\"', '"').replace("\\'", "'").replace('\\\\','\\')
            result[k]=parse_logfmt_value(inner, True)
        else:
            if v=='':
                continue
            result[k]=parse_logfmt_value(v, False)
    if not result:
        return None
    return result

def parse_logfmt_value(v, is_quoted):
    low=v.lower()
    if not is_quoted:
        if low=='true':
            return True
        if low=='false':
            return False
        try:
            if '.' not in v and 'e' not in low:
                return int(v)
            else:
                return float(v)
        except:
            pass
    return v

def convert_value(v):
    if not isinstance(v,str):
        return v
    s=v.strip()
    if s=='':
        return s
    low=s.lower()
    if low=='true':
        return True
    if low=='false':
        return False
    try:
        if '.' not in s and 'e' not in low:
            return int(s)
    except:
        pass
    try:
        return float(s)
    except:
        pass
    return v

