class JsonOp:
    def __init__(self, from_field=None):
        self.from_field=from_field
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.from_field:
                    val=self.from_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.from_field.raw}\"")
                    if isinstance(val, (dict,list)):
                        data=val if isinstance(val, dict) else None
                        if isinstance(val, str):
                            data=json.loads(val)
                    else:
                        data=json.loads(str(val))
                else:
                    data=json.loads(raw)
                if isinstance(data, dict):
                    new_rec=rec.copy()
                    new_rec.update(data)
                    out.append((new_rec, raw))
                else:
                    # drop if not object
                    print(f"error: Expected JSON, found {raw}", file=sys.stderr)
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
            except Exception:
                print(f"error: Expected JSON, found {raw}", file=sys.stderr)
        return out

