def parse_aliases(alias_dir, no_alias):
    aliases={}
    if no_alias:
        return aliases
    # alias_dir can be None, means search .agrind-aliases in current and parent dirs
    # If alias_dir specified, use that dir only
    # Else search upward

    def load_dir(d):
        if not os.path.isdir(d):
            return
        for f in glob.glob(os.path.join(d, '*.toml')):
            try:
                # Simple TOML parsing: keyword = "..." and template = "..." (multiline)
                content=open(f).read()
                # Parse keyword
                m_kw=re.search(r'keyword\s*=\s*"([^"]+)"', content)
                m_tpl=re.search(r'template\s*=\s*"""(.*?)"""', content, re.DOTALL)
                if not m_tpl:
                    m_tpl=re.search(r"template\s*=\s*'''(.*?)'''", content, re.DOTALL)
                if not m_tpl:
                    m_tpl=re.search(r'template\s*=\s*"([^"]+)"', content)
                if not m_tpl:
                    m_tpl=re.search(r"template\s*=\s*'([^']+)'", content)
                if m_kw and m_tpl:
                    kw=m_kw.group(1)
                    tpl=m_tpl.group(1).strip()
                    # Validate template: try to parse it as query? If invalid, print warning to stderr
                    # For validation, we can try to parse operators, but for simplicity, if tpl contains invalid operator keyword, we print warning
                    # Original warning: error: Expected an operator\n  |\n1 | invalid operator\n ...
                    # So when alias file contains invalid template, warning displayed.

                    # We will attempt to parse template pipeline: if fails, print warning
                    try:
                        # Try to parse operators (without filter?) – template is expected to be pipeline like 'parse "..." as ...'
                        # We can try to parse it as operator string(s) – split by | and parse each
                        # If any fails, it's invalid alias
                        parts=split_pipeline(tpl)
                        # Each part should be valid operator
                        for part in parts:
                            part=part.strip()
                            if not part:
                                continue
                            # Try to parse operator, if fails, invalid
                            parse_operator_string(part, tpl)
                        aliases[kw]=tpl
                    except SystemExit:
                        # parse_operator_string called sys.exit for invalid, but we need to catch and produce warning, not exit
                        # For alias validation, we should not exit, just print warning and skip alias
                        # So we need to handle SystemExit differently – we already printed error to stderr in parse_operator_string before exit
                        # For alias, we want to keep warning but not exit, and not add alias
                        # The error already printed to stderr, so we just skip
                        continue
                    except Exception as e:
                        # Invalid alias
                        # Print warning
                        print(f"error: Expected an operator", file=sys.stderr)
                        print(f"  |", file=sys.stderr)
                        print(f"1 | {tpl}", file=sys.stderr)
                        # Find caret at first word?
                        first_word=tpl.split()[0] if tpl.split() else ""
                        idx=tpl.find(first_word)
                        print(f"  | {' '*idx}{'^'*len(first_word)}", file=sys.stderr)
                        print(f"  |", file=sys.stderr)
                        print(f"  = help: {first_word} is not a valid operator", file=sys.stderr)
                        continue
            except Exception as e:
                # ignore file read errors?
                continue

    if alias_dir:
        load_dir(alias_dir)
    else:
        # Search current and parent dirs for .agrind-aliases
        cur=os.getcwd()
        while True:
            d=os.path.join(cur, '.agrind-aliases')
            if os.path.isdir(d):
                # Load all files
                for f in glob.glob(os.path.join(d, '*.toml')):
                    try:
                        content=open(f).read()
                        m_kw=re.search(r'keyword\s*=\s*"([^"]+)"', content)
