                            m_tpl=re.search(r"template\s*=\s*'([^']+)'", content)
                        if m_kw and m_tpl:
                            kw=m_kw.group(1)
                            tpl=m_tpl.group(1).strip()
                            try:
                                parts=split_pipeline(tpl)
                                for part in parts:
                                    part=part.strip()
                                    if not part:
                                        continue
