                                continue
                    except:
                        continue
            parent=os.path.dirname(cur)
            if parent==cur:
                break
            cur=parent

    return aliases

def expand_aliases(query, aliases):
    # Your operators are parsed, then expanded into resulting pipeline. When invalid aliases are present, warning displayed.
    # So we need to parse pipeline, and for each operator that matches alias keyword, replace it with template
    # Alias expansion: operator is exactly keyword? Or keyword appears as operator? Example "* | apache | count by status" – apache is alias keyword that expands to parse "..." as ...

    # So split pipeline, and for each operator part, if it matches alias keyword (case-sensitive?), expand.

    # Also need to handle alias that expands to multiple operators? Template may contain pipeline? Example template = """parse "..." as ...""" – it's single operator, but could contain multiple? Probably single.

    # For simplicity, if operator string stripped equals alias keyword, replace with template. Also if operator string starts with alias keyword + spaces? For example, alias keyword "myalias" – query "* | myalias" – operator is "myalias" exactly.

    # If alias template itself contains aliases, should we recursively expand? Possibly.

    parts=split_pipeline(query)
    expanded=[]
    for part in parts:
        stripped=part.strip()
        # Check if stripped is alias keyword
        if stripped in aliases:
            # Expand: template may itself contain pipeline separators?
            # The template is supposed to be expanded into pipeline, so we split template by '|' and add each
            tpl=aliases[stripped]
            tpl_parts=split_pipeline(tpl)
            for tp in tpl_parts:
                expanded.append(tp)
        else:
            # Also check if stripped starts with alias keyword followed by space? For safety, split stripped into first word
            first_word=stripped.split(None,1)[0] if stripped else ""
            if first_word in aliases:
                # Replace first word with template, keep rest?
                # The alias is pre-built pipeline to simplify common tasks, so likely whole operator is alias, not with extra args
                # But we will handle: replace first word with template, and append rest as separate? Actually template is full operator, so if operator is "myalias extra", we should expand myalias to its template plus keep extra? Unclear.
                # For simplicity, if first word is alias, expand it and if there is rest, treat rest as part of last expanded operator? We'll just replace first word.
                tpl=aliases[first_word]
                # If stripped has extra beyond first word, append extra to tpl?
                rest=stripped[len(first_word):].strip()
                if rest:
                    # Append rest to last template part?
                    tpl_parts=split_pipeline(tpl)
                    # Add rest to last part?
                    tpl_parts[-1]=tpl_parts[-1]+' '+rest
                    expanded.extend(tpl_parts)
                else:
                    tpl_parts=split_pipeline(tpl)
                    expanded.extend(tpl_parts)
            else:
                expanded.append(part)

    # Reconstruct query as ' | '.join(expanded)
    return ' | '.join(expanded)

