class TrueNode:
    def match(self, line): return True

class TermNode:
    def __init__(self, pattern, is_quoted):
        self.pattern=pattern
        self.is_quoted=is_quoted
        self.is_star=pattern=="*"
        if not is_quoted:
            parts=pattern.split('*')
            escaped=[re.escape(p) for p in parts]
            regex_str='.*'.join(escaped)
