    def match(self, line):
        if self.is_star:
            return True
        if self.is_quoted:
            return self.substr in line
        else:
            return self.regex.search(line) is not None

class NotNode:
    def __init__(self, child): self.child=child
    def match(self, line): return not self.child.match(line)

class AndNode:
    def __init__(self, left,right): self.left=left; self.right=right
    def match(self, line): return self.left.match(line) and self.right.match(line)

class OrNode:
    def __init__(self, left,right): self.left=left; self.right=right
    def match(self, line): return self.left.match(line) or self.right.match(line)

def tokenize_filter(s):
    tokens=[]
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if c.isspace():
            i+=1
            continue
        if c=='(':
            tokens.append(('LPAREN','(')); i+=1; continue
        if c==')':
            tokens.append(('RPAREN',')')); i+=1; continue
        if c=='"' or c=="'":
