            j=i+1
            buf=[]
            while j<n:
                if s[j]=='\\' and j+1<n:
                    if s[j+1]==quote:
                        buf.append(quote); j+=2; continue
                    else:
                        buf.append(s[j+1]); j+=2; continue
                if s[j]==quote:
                    break
                buf.append(s[j]); j+=1
            if j>=n:
                raise ValueError("Unterminated")
            tokens.append(('QUOTED',''.join(buf)))
            i=j+1
            continue
        if s[i:].startswith('NOT'):
            after=i+3
            if after==n or s[after].isspace() or s[after] in ('(',')'):
                tokens.append(('NOT','NOT')); i+=3; continue
        if s[i:].startswith('AND'):
