                tokens.append(('OR','OR')); i+=2; continue
        j=i
        while j<n and not s[j].isspace() and s[j] not in ('(',')','"',"'"):
            j+=1
        term=s[i:j]
        if term:
            tokens.append(('TERM',term))
        i=j
    return tokens

def parse_filter_tokens(tokens, original_str):
    pos=[0]
