    def peek():
        return tokens[pos[0]] if pos[0]<n else None
    def consume(expected=None):
        if pos[0]>=n:
            return None
        tok=tokens[pos[0]]
        if expected and tok[0]!=expected:
            return None
        pos[0]+=1
        return tok
    def parse_factor():
        tok=peek()
