            except:
                return l!=r
        if isinstance(r,(int,float)) and isinstance(l,str):
            try:
                return to_number(l)!=r
            except:
                return l!=r
        return l!=r
    try:
        if op=='<': return l<r
        if op=='>': return l>r
        if op=='<=': return l<=r
        if op=='>=': return l>=r
    except:
        raise RuntimeError(f"Cannot compare {l} and {r}")

def eval_function(name, args):
    lname=name.lower()
    if lname in ('abs','acos','asin','atan','cbrt','ceil','cos','cosh','exp','expm1','floor','log','log10','log1p','round','sin','sinh','sqrt','tan','tanh','todegrees','toradians'):
        if len(args)!=1:
            raise RuntimeError(f"{name} expects 1")
        v=to_number(args[0])
        if lname=='abs': return abs(v)
        if lname=='acos': return math.acos(v)
        if lname=='asin': return math.asin(v)
        if lname=='atan': return math.atan(v)
        if lname=='cbrt': return v**(1/3) if v>=0 else -((-v)**(1/3))
        if lname=='ceil': return math.ceil(v)
        if lname=='cos': return math.cos(v)
        if lname=='cosh': return math.cosh(v)
        if lname=='exp': return math.exp(v)
        if lname=='expm1': return math.expm1(v)
        if lname=='floor': return math.floor(v)
        if lname=='log': return math.log(v)
        if lname=='log10': return math.log10(v)
        if lname=='log1p': return math.log1p(v)
        if lname=='round': return round(v)
        if lname=='sin': return math.sin(v)
        if lname=='sinh': return math.sinh(v)
        if lname=='sqrt': return math.sqrt(v)
        if lname=='tan': return math.tan(v)
        if lname=='tanh': return math.tanh(v)
        if lname=='todegrees': return math.degrees(v)
        if lname=='toradians': return math.radians(v)
    if lname=='atan2':
        if len(args)!=2: raise RuntimeError("atan2 expects 2")
        return math.atan2(to_number(args[0]), to_number(args[1]))
    if lname=='hypot':
        if len(args)!=2: raise RuntimeError("hypot expects 2")
        return math.hypot(to_number(args[0]), to_number(args[1]))
    if lname=='concat':
        return ''.join([str(a) if a is not None else '' for a in args])
    if lname=='contains':
        if len(args)!=2: raise RuntimeError("contains expects 2")
        hay, needle=args
        if hay is None or needle is None:
            return False
        return str(needle) in str(hay)
    if lname=='length':
        if len(args)!=1: raise RuntimeError("length expects 1")
        a=args[0]
        if a is None: return 0
        if isinstance(a,(list,dict)): return len(a)
        return len(str(a))
    if lname=='now':
        if len(args)!=0: raise RuntimeError("now expects 0")
        return datetime.datetime.now(datetime.timezone.utc)
    if lname=='num':
        if len(args)!=1: raise RuntimeError("num expects 1")
        return to_number(args[0])
    if lname=='parsedate':
        if len(args)!=1: raise RuntimeError("parseDate expects 1")
        s=str(args[0])
        dt=parse_date_string(s)
        if dt is None:
            raise RuntimeError(f"Failed to parse date {s}")
        return dt
    if lname=='parsehex':
        if len(args)!=1: raise RuntimeError("parseHex expects 1")
        s=str(args[0]).strip()
        if s.lower().startswith('0x'):
            s=s[2:]
        try:
            return int(s,16)
        except:
            raise RuntimeError(f"invalid hex string -- {args[0]}")
    if lname=='substring':
        if len(args)<2 or len(args)>3: raise RuntimeError("substring expects 2 or 3")
        s=str(args[0]) if args[0] is not None else ""
        start=int(to_number(args[1]))
        if len(args)==3:
            end=int(to_number(args[2]))
            return s[start:end]
        else:
            return s[start:]
    if lname=='tolowercase':
        if len(args)!=1: raise RuntimeError("toLowerCase expects 1")
        return str(args[0]).lower() if args[0] is not None else ""
    if lname=='touppercase':
        if len(args)!=1: raise RuntimeError("toUpperCase expects 1")
        return str(args[0]).upper() if args[0] is not None else ""
    if lname=='isnull':
        if len(args)!=1: raise RuntimeError("isNull expects 1")
        return args[0] is None
    if lname=='isempty':
        if len(args)!=1: raise RuntimeError("isEmpty expects 1")
        v=args[0]
        return v is None or (isinstance(v,str) and v=="")
    if lname=='isblank':
        if len(args)!=1: raise RuntimeError("isBlank expects 1")
        v=args[0]
        return v is None or (isinstance(v,str) and v.strip()=="")
    if lname=='isnumeric':
        if len(args)!=1: raise RuntimeError("isNumeric expects 1")
        v=args[0]
        if isinstance(v,(int,float)): return True
        if isinstance(v,str):
            try:
                float(v)
                return True
            except:
                return False
        return False
    raise RuntimeError(f"Unknown function {name}")

def parse_date_string(s):
    s=s.strip()
    try:
        if s.endswith('Z'):
            s2=s[:-1]+'+00:00'
            dt=datetime.datetime.fromisoformat(s2)
            return dt
        dt=datetime.datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except:
        pass
    fmts=["%Y-%m-%dT%H:%M:%S%z","%Y-%m-%dT%H:%M:%S.%f%z","%Y-%m-%dT%H:%M:%S","%Y-%m-%d %H:%M:%S","%Y-%m-%d","%Y/%m/%d","%b %d %Y","%d %b %Y","%m/%d/%Y"]
    for fmt in fmts:
        try:
            dt=datetime.datetime.strptime(s, fmt)
            if dt.tzinfo is None:
                dt=dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except:
            continue
    try:
        from dateutil import parser
        dt=parser.parse(s)
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except:
        pass
    return None

def parse_expression(s):
    toks=tokenize_expr(s)
    pos=[0]
    def peek():
        return toks[pos[0]] if pos[0]<len(toks) else None
    def consume(expected=None):
        if pos[0]>=len(toks):
            return None
        tok=toks[pos[0]]
        if expected and tok[0]!=expected:
            return None
        pos[0]+=1
        return tok
    def parse_primary():
        tok=peek()
        if not tok:
            raise ValueError("Unexpected end")
        if tok[0]=='(':
            consume('(')
            expr=parse_or()
            if not peek() or peek()[0]!=')':
                raise ValueError("Expected ')'")
            consume(')')
            return expr
        if tok[0]=='NUMBER':
            consume(); return Literal(tok[1])
        if tok[0]=='STRING':
            consume(); return Literal(tok[1])
        if tok[0]=='BOOL':
            consume(); return Literal(tok[1])
        if tok[0]=='NULL':
            consume(); return Literal(None)
        if tok[0]=='IDENT':
            ident=tok[1]
            consume('IDENT')
            if peek() and peek()[0]=='(':
                consume('(')
                args=[]
                if peek() and peek()[0]!=')':
                    while True:
                        args.append(parse_or())
                        if peek() and peek()[0]==',':
                            consume(',')
                        else:
                            break
                if not peek() or peek()[0]!=')':
                    raise ValueError("Expected ')'")
                consume(')')
                if ident.lower()=='if':
                    if len(args)!=3:
                        raise ValueError("if expects 3")
                    return IfExpr(args[0],args[1],args[2])
                return FuncCall(ident,args)
            else:
                path=[ident]
                raw=ident
                while True:
                    nxt=peek()
                    if not nxt:
                        break
                    if nxt[0]=='.':
                        consume('.')
                        if peek() and peek()[0]=='IDENT':
                            path.append(peek()[1])
                            raw+='.'+peek()[1]
                            consume('IDENT')
                        else:
                            raise ValueError("Expected ident after '.'")
                    elif nxt[0]=='[':
                        consume('[')
                        inner=peek()
                        if not inner:
                            raise ValueError("Expected ']'")
                        if inner[0]=='NUMBER':
                            idx=int(inner[1])
                            path.append(idx)
                            raw+=f"[{idx}]"
                            consume('NUMBER')
                        elif inner[0]=='STRING':
                            field_name=inner[1]
                            path.append(field_name)
                            raw+=f'["{field_name}"]'
                            consume('STRING')
                        elif inner[0]=='IDENT':
                            path.append(inner[1])
                            raw+=f'[{inner[1]}]'
                            consume('IDENT')
                        else:
                            raise ValueError("Unexpected")
                        if not peek() or peek()[0]!=']':
                            raise ValueError("Expected ']'")
                        consume(']')
                    else:
                        break
                return FieldRef(path, raw)
        if tok[0]=='[':
            consume('[')
            inner=peek()
            if not inner or inner[0]!='STRING':
                raise ValueError("Expected string in []")
            field_name=inner[1]
            consume('STRING')
            if not peek() or peek()[0]!=']':
                raise ValueError("Expected ]")
            consume(']')
            path=[field_name]
            raw=f'["{field_name}"]'
            while True:
                nxt=peek()
                if not nxt:
                    break
                if nxt[0]=='.':
                    consume('.')
                    if peek() and peek()[0]=='IDENT':
                        path.append(peek()[1])
                        raw+='.'+peek()[1]
                        consume('IDENT')
                    else:
                        raise ValueError("Expected ident")
                elif nxt[0]=='[':
                    consume('[')
                    inner2=peek()
                    if inner2[0]=='NUMBER':
                        idx=int(inner2[1])
                        path.append(idx)
                        raw+=f"[{idx}]"
                        consume('NUMBER')
                    elif inner2[0]=='STRING':
                        path.append(inner2[1])
                        raw+=f'["{inner2[1]}"]'
                        consume('STRING')
                    else:
                        raise ValueError("Unexpected")
                    if not peek() or peek()[0]!=']':
                        raise ValueError("Expected ]")
                    consume(']')
                else:
                    break
            return FieldRef(path, raw)
        raise ValueError(f"Unexpected {tok}")
    def parse_unary():
        tok=peek()
        if tok and tok[0] in ('!','-'):
            op=tok[0]
            consume()
            operand=parse_unary()
            return UnaryOp(op,operand)
        return parse_primary()
    def parse_mul():
        left=parse_unary()
        while True:
            tok=peek()
            if tok and tok[0] in ('*','/'):
                op=tok[0]; consume()
                right=parse_unary()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    def parse_add():
        left=parse_mul()
        while True:
            tok=peek()
            if tok and tok[0] in ('+','-'):
                op=tok[0]; consume()
                right=parse_mul()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    def parse_comp():
        left=parse_add()
        while True:
            tok=peek()
            if tok and tok[0] in ('==','!=','<','>','<=','>='):
                op=tok[0]; consume()
                right=parse_add()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    def parse_and():
        left=parse_comp()
        while True:
            tok=peek()
            if tok and tok[0] in ('and','&&'):
                op=tok[0]; consume()
                right=parse_comp()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    def parse_or():
        left=parse_and()
        while True:
            tok=peek()
            if tok and tok[0] in ('or','||'):
                op=tok[0]; consume()
                right=parse_and()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    res=parse_or()
    if pos[0]!=len(toks):
        raise ValueError(f"Unhandled {toks[pos[0]:]}")
    return res

# ---------- Operator parsing helpers ----------
def split_pipeline(query):
    parts=[]
    buf=[]
    in_double=False
    in_single=False
    escape=False
    for ch in query:
        if escape:
            buf.append(ch); escape=False; continue
        if ch=='\\':
            escape=True; buf.append(ch); continue
        if ch=='"' and not in_single:
            in_double=not in_double; buf.append(ch); continue
        if ch=="'" and not in_double:
            in_single=not in_single; buf.append(ch); continue
        if ch=='|' and not in_double and not in_single:
            parts.append(''.join(buf)); buf=[]; continue
        buf.append(ch)
    parts.append(''.join(buf))
    return parts

def split_by_commas_outside_parens(s):
    parts=[]
    buf=[]
    depth=0
    in_double=False
    in_single=False
    escape=False
    for ch in s:
        if escape:
            buf.append(ch); escape=False; continue
        if ch=='\\':
            escape=True; buf.append(ch); continue
        if ch=='"' and not in_single:
            in_double=not in_double; buf.append(ch); continue
        if ch=="'" and not in_double:
            in_single=not in_single; buf.append(ch); continue
        if not in_double and not in_single:
            if ch=='(':
                depth+=1
            elif ch==')':
                depth-=1
            elif ch==',' and depth==0:
                parts.append(''.join(buf)); buf=[]; continue
        buf.append(ch)
    parts.append(''.join(buf))
    return parts

def parse_logfmt(s):
    tokens=[]
    buf=[]
    in_quotes=False
    quote_char=None
    escape=False
    for ch in s:
        if escape:
            buf.append(ch); escape=False; continue
        if ch=='\\':
            escape=True; buf.append(ch); continue
        if ch in ('"',"'") and not in_quotes:
            in_quotes=True; quote_char=ch; buf.append(ch)
        elif ch==quote_char and in_quotes:
            in_quotes=False; quote_char=None; buf.append(ch)
        elif ch.isspace() and not in_quotes:
            if buf:
                tokens.append(''.join(buf)); buf=[]
        else:
            buf.append(ch)
    if buf:
        tokens.append(''.join(buf))
    result={}
    for tok in tokens:
        if '=' not in tok:
            continue
        k,v=tok.split('=',1)
        if not k:
            continue
        v=v.strip()
        if len(v)>=2 and ((v[0]=='"' and v[-1]=='"') or (v[0]=="'" and v[-1]=="'")):
            inner=v[1:-1].replace('\\"', '"').replace("\\'", "'").replace('\\\\','\\')
            result[k]=parse_logfmt_value(inner, True)
        else:
            if v=='':
                continue
            result[k]=parse_logfmt_value(v, False)
    if not result:
        return None
    return result

def parse_logfmt_value(v, is_quoted):
    low=v.lower()
    if not is_quoted:
        if low=='true': return True
        if low=='false': return False
        try:
            if '.' not in v and 'e' not in low:
                return int(v)
            else:
                return float(v)
        except:
            pass
    return v

def convert_value(v):
    if not isinstance(v,str):
        return v
    s=v.strip()
    if s=='':
        return s
    low=s.lower()
    if low=='true': return True
    if low=='false': return False
    try:
        if '.' not in s and 'e' not in low:
            return int(s)
    except:
        pass
    try:
        return float(s)
    except:
        pass
    return v

# Operator classes

class JsonOp:
    def __init__(self, from_field=None): self.from_field=from_field
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.from_field:
                    val=self.from_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.from_field.raw}\"")
                    if isinstance(val, (dict,list)):
                        data=val if isinstance(val, dict) else None
                        if isinstance(val, str):
                            data=json.loads(val)
                    else:
                        data=json.loads(str(val))
                else:
                    data=json.loads(raw)
                if isinstance(data, dict):
                    new_rec=rec.copy()
                    new_rec.update(data)
                    out.append((new_rec, raw))
                else:
                    print(f"error: Expected JSON, found {raw}", file=sys.stderr)
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
            except Exception:
                print(f"error: Expected JSON, found {raw}", file=sys.stderr)
        return out

class LogfmtOp:
    def __init__(self, from_field=None): self.from_field=from_field
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.from_field:
                    val=self.from_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.from_field.raw}\"")
                    line=str(val)
                else:
                    line=raw
                data=parse_logfmt(line)
                if data is None:
                    continue
                new_rec=rec.copy()
                new_rec.update(data)
                out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
        return out

class SplitOp:
    def __init__(self, input_field=None, separator=',', as_field=None):
        self.input_field=input_field
        self.separator=separator
        self.as_field=as_field
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.input_field:
                    val=self.input_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.input_field.raw}\"")
                    s=str(val)
                else:
                    s=raw
                parts=s.split(self.separator)
                if self.as_field:
                    new_rec=rec.copy()
                    new_rec[self.as_field]=parts
                    out.append((new_rec, raw))
                else:
                    if self.input_field:
                        new_rec=rec.copy()
                        if len(self.input_field.path)==1:
                            key=self.input_field.path[0]
                            new_rec[key]=parts
                        else:
                            new_rec[self.input_field.raw]=parts
                        out.append((new_rec, raw))
                    else:
                        new_rec=rec.copy()
                        new_rec['_split']=parts
                        out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
        return out

class ParseOp:
    def __init__(self, pattern, as_fields, from_field=None, nodrop=False, noconvert=False):
        self.pattern=pattern
        self.as_fields=as_fields
        self.from_field=from_field
        self.nodrop=nodrop
        self.noconvert=noconvert
        star_count=self.pattern.count('*')
        if star_count!=len(self.as_fields):
            print(f"Error: Wrong number of patterns for parse. Pattern has {star_count} but {len(self.as_fields)} were extracted", file=sys.stderr)
            sys.exit(1)
        segs=self.pattern.split('*')
        regex='^'
        for idx, seg in enumerate(segs):
            if seg!='':
                sub=''
                j=0
                while j<len(seg):
                    if seg[j].isspace():
                        while j<len(seg) and seg[j].isspace():
                            j+=1
                        sub+=r'\s+'
                    else:
                        k=j
                        while k<len(seg) and not seg[k].isspace():
                            k+=1
                        literal=seg[j:k]
                        sub+=re.escape(literal)
                        j=k
                regex+=sub
            if idx < len(segs)-1:
                regex+=r'(.*)'
        regex+='$'
        self.regex=re.compile(regex, re.DOTALL)
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.from_field:
                    val=self.from_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.from_field.raw}\"")
                    line=str(val)
                else:
                    line=raw
                m=self.regex.match(line)
                if not m:
                    if self.nodrop:
                        new_rec=rec.copy()
                        for f in self.as_fields:
                            new_rec[f]=None
                        out.append((new_rec, raw))
                    continue
                groups=m.groups()
                new_rec=rec.copy()
                for field_name, value in zip(self.as_fields, groups):
                    if self.noconvert:
                        new_rec[field_name]=value
                    else:
                        new_rec[field_name]=convert_value(value)
                out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
            except SystemExit:
                raise
        return out

class ParseRegexOp:
    def __init__(self, pattern, from_field=None, nodrop=False):
        self.pattern=pattern
        self.from_field=from_field
        self.nodrop=nodrop
        try:
            self.compiled=re.compile(pattern)
            total=self.compiled.groups
            named=len(self.compiled.groupindex)
            if total!=named:
                print(f"Error: Only named captures are supported", file=sys.stderr)
                sys.exit(1)
        except re.error as e:
            print(f"Error: Invalid regex {pattern}: {e}", file=sys.stderr)
            sys.exit(1)
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.from_field:
                    val=self.from_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.from_field.raw}\"")
                    line=str(val)
                else:
                    line=raw
                m=self.compiled.search(line)
                if not m:
                    if self.nodrop:
                        new_rec=rec.copy()
                        for name in self.compiled.groupindex.keys():
                            new_rec[name]=None
                        out.append((new_rec, raw))
                    continue
                new_rec=rec.copy()
                for name, value in m.groupdict().items():
                    if value is None:
                        new_rec[name]=None
                    else:
                        new_rec[name]=convert_value(value)
                out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
            except SystemExit:
                raise
        return out

class FieldsOp:
    def __init__(self, mode, fields):
        self.mode=mode
        self.fields=fields
    def process(self, records):
        out=[]
        for rec, raw in records:
            if self.mode in ('+','only'):
                new_rec={k:rec[k] for k in self.fields if k in rec}
                out.append((new_rec, raw))
            else:
                new_rec=rec.copy()
                for f in self.fields:
                    new_rec.pop(f, None)
                out.append((new_rec, raw))
        return out

class WhereOp:
    def __init__(self, expr): self.expr=expr
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if bool(self.expr.eval(rec)):
                    out.append((rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
            except Exception as e:
                print(f"error: {e}", file=sys.stderr)
        return out

class FieldExprOp:
    def __init__(self, expr, as_field): self.expr=expr; self.as_field=as_field
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                val=self.expr.eval(rec)
                new_rec=rec.copy()
                new_rec[self.as_field]=val
                out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
        return out

class LimitOp:
    def __init__(self, n): self.n=n
    def process(self, records):
        if self.n>=0:
            return records[:self.n]
        else:
            return records[self.n:]

class TimesliceOp:
    def __init__(self, expr, duration_str, as_field='_timeslice'):
        self.expr=expr
        self.duration_str=duration_str
        self.as_field=as_field
        m=re.match(r'^(\d+(?:\.\d+)?)(ns|us|ms|s|m|h|d|w)$', duration_str)
        if not m:
            raise ValueError(f"Invalid duration {duration_str}")
        amount=float(m.group(1))
        unit=m.group(2)
        if unit=='ns':
            self.delta=datetime.timedelta(microseconds=amount/1000)
        elif unit=='us':
            self.delta=datetime.timedelta(microseconds=amount)
        elif unit=='ms':
            self.delta=datetime.timedelta(milliseconds=amount)
        elif unit=='s':
            self.delta=datetime.timedelta(seconds=amount)
        elif unit=='m':
            self.delta=datetime.timedelta(minutes=amount)
        elif unit=='h':
            self.delta=datetime.timedelta(hours=amount)
        elif unit=='d':
            self.delta=datetime.timedelta(days=amount)
        elif unit=='w':
            self.delta=datetime.timedelta(weeks=amount)
        else:
            raise ValueError("Unknown unit")
    def process(self, records):
        out=[]
        epoch=datetime.datetime(1970,1,1, tzinfo=datetime.timezone.utc)
        for rec, raw in records:
            try:
                ts=self.expr.eval(rec)
                if not isinstance(ts, datetime.datetime):
                    raise RuntimeError(f"Expected datetime, found {ts}")
                if ts.tzinfo is None:
                    ts=ts.replace(tzinfo=datetime.timezone.utc)
                delta_seconds=self.delta.total_seconds()
                if delta_seconds==0:
                    floored=ts
                else:
                    ts_seconds=(ts-epoch).total_seconds()
                    floored_seconds=math.floor(ts_seconds/delta_seconds)*delta_seconds
                    floored=epoch+datetime.timedelta(seconds=floored_seconds)
                new_rec=rec.copy()
                new_rec[self.as_field]=floored
                out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
        return out

class AggFunc:
    def __init__(self, func_name, arg_expr, as_field=None):
        self.func_name=func_name
        self.arg_expr=arg_expr
        self.as_field=as_field

def make_hashable(v):
    try:
        hash(v)
        return v
    except:
        try:
            return json.dumps(v, sort_keys=True)
        except:
            return str(v)

class AggregateOp:
    def __init__(self, agg_funcs, by_fields, by_fields_raw):
        self.agg_funcs=agg_funcs
        self.by_fields=by_fields
        self.by_fields_raw=by_fields_raw
    def process(self, records):
        groups=defaultdict(list)
        group_example={}
        for rec, raw in records:
            key_vals=[]
            for by_expr in self.by_fields:
                try:
                    v=by_expr.eval(rec)
                except:
                    v=None
                key_vals.append(v)
            hash_key=tuple(make_hashable(v) for v in key_vals)
            groups[hash_key].append(rec)
            if hash_key not in group_example:
                group_example[hash_key]=key_vals
        result=[]
        for hash_key, recs in groups.items():
            agg_result={}
            for idx, raw_name in enumerate(self.by_fields_raw):
                agg_result[raw_name]=group_example[hash_key][idx]
            for agg in self.agg_funcs:
                func_name=agg.func_name.lower()
                as_field=agg.as_field
                if not as_field:
                    if func_name=='count':
                        as_field='_count'
                    elif func_name=='sum':
                        as_field='_sum'
                    elif func_name in ('avg','average'):
                        as_field='_average'
                    elif func_name=='min':
                        as_field='_min'
                    elif func_name=='max':
                        as_field='_max'
                    elif func_name.startswith('p'):
                        as_field=func_name
                    elif func_name=='count_distinct':
                        as_field='_countDistinct'
                    elif func_name=='total':
                        as_field='_total'
                    else:
                        as_field=func_name
                if func_name=='count':
                    if agg.arg_expr is None:
                        cnt=len(recs)
                    else:
                        cnt=0
                        for r in recs:
                            try:
                                if bool(agg.arg_expr.eval(r)):
                                    cnt+=1
                            except:
                                pass
                    agg_result[as_field]=cnt
                elif func_name=='sum':
                    total=0
                    for r in recs:
                        try:
                            total+=to_number(agg.arg_expr.eval(r))
                        except:
                            pass
                    agg_result[as_field]=total
                elif func_name in ('avg','average'):
                    total=0
                    cnt=0
                    for r in recs:
                        try:
                            total+=to_number(agg.arg_expr.eval(r))
                            cnt+=1
                        except:
                            pass
                    agg_result[as_field]=(total/cnt) if cnt else None
                elif func_name=='min':
                    min_val=None
                    for r in recs:
                        try:
                            num=to_number(agg.arg_expr.eval(r))
                            if min_val is None or num<min_val:
                                min_val=num
                        except:
                            pass
                    agg_result[as_field]=min_val
                elif func_name=='max':
                    max_val=None
                    for r in recs:
                        try:
                            num=to_number(agg.arg_expr.eval(r))
                            if max_val is None or num>max_val:
                                max_val=num
                        except:
                            pass
                    agg_result[as_field]=max_val
                elif func_name.startswith('p'):
                    m=re.match(r'p(\d+)', func_name)
                    if not m:
                        raise RuntimeError(f"Invalid percentile {func_name}")
                    perc=int(m.group(1))
                    vals=[]
                    for r in recs:
                        try:
                            vals.append(to_number(agg.arg_expr.eval(r)))
                        except:
                            pass
                    if not vals:
                        agg_result[as_field]=None
                    else:
                        vals.sort()
                        k=math.ceil((perc/100)*len(vals))
                        idx=max(0, min(k-1, len(vals)-1))
                        agg_result[as_field]=vals[idx]
                elif func_name=='count_distinct':
                    distinct=set()
                    for r in recs:
                        try:
                            distinct.add(make_hashable(agg.arg_expr.eval(r)))
                        except:
                            pass
                    agg_result[as_field]=len(distinct)
                else:
                    raise RuntimeError(f"Unknown agg {func_name}")
            result.append((agg_result,''))
        return result

class TotalOp:
    def __init__(self, arg_expr, as_field):
        self.arg_expr=arg_expr
        self.as_field=as_field or '_total'
    def process(self, records):
        out=[]
        total=0
        for rec, raw in records:
            try:
                total+=to_number(self.arg_expr.eval(rec))
                new_rec=rec.copy()
                new_rec[self.as_field]=total
                out.append((new_rec, raw))
            except:
                new_rec=rec.copy()
                new_rec[self.as_field]=total
                out.append((new_rec, raw))
        return out

class SortOp:
    def __init__(self, by_exprs):
        self.by_exprs=by_exprs
    def process(self, records):
        def compare(a,b):
            rec_a=a[0]; rec_b=b[0]
            for expr, asc in self.by_exprs:
                try:
                    va=expr.eval(rec_a)
                except:
                    va=None
                try:
                    vb=expr.eval(rec_b)
                except:
                    vb=None
                if va is None and vb is None:
                    cmp_res=0
                elif va is None:
                    cmp_res=-1
                elif vb is None:
                    cmp_res=1
                else:
                    try:
                        if va<vb: cmp_res=-1
                        elif va>vb: cmp_res=1
                        else: cmp_res=0
                    except:
                        sa=str(va); sb=str(vb)
                        if sa<sb: cmp_res=-1
                        elif sa>sb: cmp_res=1
                        else: cmp_res=0
                if cmp_res!=0:
                    if not asc:
                        cmp_res=-cmp_res
                    return cmp_res
            return 0
        return sorted(records, key=cmp_to_key(compare))

def parse_operator_string(op_str, full_query_for_error=None):
    s=op_str.strip()
    if not s:
        print(f"error: expecting an expression", file=sys.stderr)
        print(f"  |", file=sys.stderr)
        print(f"1 | {full_query_for_error or op_str}", file=sys.stderr)
        print(f"  | {' '*(len(full_query_for_error or op_str))}^", file=sys.stderr)
        print(f"  |", file=sys.stderr)
        print(f"Error: Failed to parse query", file=sys.stderr)
        sys.exit(1)

    if s.lower().startswith('sort'):
        rest=s[4:].strip()
        if not rest.lower().startswith('by'):
            raise ValueError("sort needs by")
        rest=rest[2:].strip()
        parts=split_by_commas_outside_parens(rest)
        by_exprs=[]
        for part in parts:
            part=part.strip()
            if not part:
                continue
            low=part.lower()
            asc=True
            if low.endswith(' desc'):
                asc=False
                expr_str=part[:-5].strip()
            elif low.endswith(' asc'):
                asc=True
                expr_str=part[:-4].strip()
            else:
                words=part.rsplit(None,1)
                if len(words)==2 and words[1].lower() in ('asc','desc'):
                    asc=words[1].lower()=='asc'
                    expr_str=words[0]
                else:
                    expr_str=part
            expr=parse_expression(expr_str)
            by_exprs.append((expr, asc))
        return SortOp(by_exprs)

    if s.lower().startswith('limit'):
        rest=s[5:].strip()
        return LimitOp(int(rest))

    if s.lower().startswith('timeslice'):
        m=re.match(r'timeslice\s*\(\s*(.+)\s*\)\s+(\S+)(?:\s+as\s+(\S+))?', s, re.IGNORECASE)
        if not m:
            raise ValueError("Invalid timeslice")
        expr=parse_expression(m.group(1))
        return TimesliceOp(expr, m.group(2), m.group(3) or '_timeslice')

    if s.lower().startswith('total'):
        m=re.match(r'total\s*\(\s*(.+)\s*\)(?:\s+as\s+(\S+))?', s, re.IGNORECASE)
        if not m:
            raise ValueError("Invalid total")
        if re.search(r'\bby\b', s, re.IGNORECASE):
            print(f"error: unrecognized option, only the 'as' option is available", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"1 | {full_query_for_error or s}", file=sys.stderr)
            idx=(full_query_for_error or s).lower().find('by')
            if idx==-1:
                idx=s.lower().find('by')
            print(f"  | {' '*idx}{'^'*2}", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"Error: Failed to parse query", file=sys.stderr)
            sys.exit(1)
        expr=parse_expression(m.group(1))
        return TotalOp(expr, m.group(2))

    if s.lower().startswith('fields'):
        rest=s[6:].strip()
        mode='-'
        if rest.startswith('+'):
            mode='+'; rest=rest[1:].strip()
        elif rest.startswith('-'):
            mode='-'; rest=rest[1:].strip()
        else:
            low=rest.lower()
            if low.startswith('only'):
                mode='+'; rest=rest[4:].strip()
            elif low.startswith('except'):
                mode='-'; rest=rest[6:].strip()
        parts=split_by_commas_outside_parens(rest)
        fields=[]
        for part in parts:
            part=part.strip()
            if not part:
                continue
            m=re.match(r'\["([^"]+)"\]', part)
            if m:
                fields.append(m.group(1))
            else:
                m2=re.match(r"\['([^']+)'\]", part)
                if m2:
                    fields.append(m2.group(1))
                else:
                    fields.append(part)
        return FieldsOp(mode, fields)

    if re.match(r'^json(\s+from\s+.+)?$', s, re.IGNORECASE):
        m=re.match(r'^json(?:\s+from\s+(.+))?$', s, re.IGNORECASE)
        from_field=None
        if m and m.group(1):
            from_field=parse_expression(m.group(1).strip())
        return JsonOp(from_field)

    if re.match(r'^logfmt(\s+from\s+.+)?$', s, re.IGNORECASE):
        m=re.match(r'^logfmt(?:\s+from\s+(.+))?$', s, re.IGNORECASE)
        from_field=None
        if m and m.group(1):
            from_field=parse_expression(m.group(1).strip())
        return LogfmtOp(from_field)

    if s.lower().startswith('split'):
        rest=s[5:].strip()
        input_field=None
        separator=','
        as_field=None
        if rest.startswith('('):
            end=rest.find(')')
            if end==-1:
                raise ValueError("Missing )")
            input_str=rest[1:end].strip()
            if input_str:
                input_field=parse_expression(input_str)
            rest=rest[end+1:].strip()
        m_as=re.search(r'\s+as\s+(\S+)\s*$', rest, re.IGNORECASE)
        if m_as:
            as_field=m_as.group(1).strip()
            rest=rest[:m_as.start()].strip()
        m_on=re.search(r'\s+on\s+(.+)\s*$', rest, re.IGNORECASE)
        if m_on:
            sep_str=m_on.group(1).strip()
            if (sep_str.startswith('"') and sep_str.endswith('"')) or (sep_str.startswith("'") and sep_str.endswith("'")):
                separator=sep_str[1:-1]
            else:
                if len(sep_str)>=2 and sep_str[0] in ('"',"'") and sep_str[-1]==sep_str[0]:
                    separator=sep_str[1:-1]
                else:
                    separator=sep_str
            rest=rest[:m_on.start()].strip()
        return SplitOp(input_field, separator, as_field)

    if re.match(r'^parse\s+regex\s+', s, re.IGNORECASE):
        rest=s[len('parse regex'):].strip()
        if rest[0] in ('"',"'"):
            quote=rest[0]
            j=1
            while j<len(rest):
                if rest[j]=='\\' and j+1<len(rest):
                    j+=2
                    continue
                if rest[j]==quote:
                    break
                j+=1
            if j>=len(rest):
                raise ValueError("Unterminated regex")
            pattern=rest[1:j]
            rest=rest[j+1:].strip()
        else:
            parts=rest.split(None,1)
            pattern=parts[0]
            rest=parts[1] if len(parts)>1 else ''
        from_field=None
        nodrop=False
        if 'nodrop' in rest.lower():
            nodrop=True
            rest=re.sub(r'\bnodrop\b','',rest,flags=re.IGNORECASE).strip()
        m_from=re.search(r'from\s+(\S+)', rest, re.IGNORECASE)
        if m_from:
            from_field=parse_expression(m_from.group(1))
        return ParseRegexOp(pattern, from_field, nodrop)

    if re.match(r'^parse\s+', s, re.IGNORECASE):
        rest=s[5:].strip()
        if rest[0] not in ('"',"'"):
            raise ValueError("Expected quoted pattern")
        quote=rest[0]
        j=1
        while j<len(rest):
            if rest[j]=='\\' and j+1<len(rest):
                j+=2
                continue
            if rest[j]==quote:
                break
            j+=1
        if j>=len(rest):
            raise ValueError("Unterminated pattern")
        pattern=rest[1:j]
        rest=rest[j+1:].strip()
        from_field=None
        as_fields=[]
        nodrop=False
        noconvert=False
        m_as=re.search(r'\bas\b', rest, re.IGNORECASE)
        if not m_as:
            raise ValueError("Missing as")
        from_part=rest[:m_as.start()].strip()
        as_part=rest[m_as.end():].strip()
        if from_part:
            m=re.match(r'from\s+(.+)$', from_part, re.IGNORECASE)
            if m:
                from_field=parse_expression(m.group(1).strip())
        temp=as_part
        if re.search(r'\bnoconvert\b', temp, re.IGNORECASE):
            noconvert=True
            temp=re.sub(r'\bnoconvert\b','',temp,flags=re.IGNORECASE).strip()
        if re.search(r'\bnodrop\b', temp, re.IGNORECASE):
            nodrop=True
            temp=re.sub(r'\bnodrop\b','',temp,flags=re.IGNORECASE).strip()
        field_parts=split_by_commas_outside_parens(temp)
        for fp in field_parts:
            fp=fp.strip()
            if fp:
                as_fields.append(fp)
        return ParseOp(pattern, as_fields, from_field, nodrop, noconvert)

    if re.match(r'^where\b', s, re.IGNORECASE):
        rest=s[5:].strip()
        try:
            expr=parse_expression(rest)
        except Exception as e:
            # mimic original error for where invalid syntax
            # Find second word
            parts=rest.split()
            if len(parts)>=2:
                second=parts[1]
                idx=s.find(second)
                if idx==-1:
                    idx=len('where ')
                print(f"error: unrecognized option, only the condition can be specified", file=sys.stderr)
                print(f"  |", file=sys.stderr)
                print(f"1 | {full_query_for_error or s}", file=sys.stderr)
                # Need to find position of second word in full query? Use full_query_for_error if provided
                full=full_query_for_error or s
                idx2=full.find(second)
                if idx2==-1:
                    idx2=0
                print(f"  | {' '*idx2}{'^'*len(second)}", file=sys.stderr)
                print(f"  |", file=sys.stderr)
                print(f"Error: Failed to parse query", file=sys.stderr)
                sys.exit(1)
            print(f"Error: Failed to parse query", file=sys.stderr)
            sys.exit(1)
        return WhereOp(expr)

    m_as=re.search(r'\s+as\s+(\S+)\s*$', s, re.IGNORECASE)
    if m_as:
        as_field=m_as.group(1)
        expr_str=s[:m_as.start()].strip()
        if not re.match(r'^(count|count_distinct|sum|avg|average|min|max|p\d+|total)\s*(\(|$)', expr_str, re.IGNORECASE):
            try:
                expr=parse_expression(expr_str)
                return FieldExprOp(expr, as_field)
            except:
                pass

    # Aggregate
    def find_by_pos(string):
        depth=0
        in_double=False
        in_single=False
        escape=False
        last_by=-1
        i=0
        while i<len(string):
            ch=string[i]
            if escape:
                escape=False; i+=1; continue
            if ch=='\\':
                escape=True; i+=1; continue
            if ch=='"' and not in_single:
                in_double=not in_double; i+=1; continue
            if ch=="'" and not in_double:
                in_single=not in_single; i+=1; continue
            if not in_double and not in_single:
                if ch=='(':
                    depth+=1
                elif ch==')':
                    depth-=1
                elif depth==0:
                    # check for ' by ' at i
                    if string[i:].lower().startswith(' by '):
                        last_by=i
                    elif string[i:].lower().startswith('by ') and (i==0 or string[i-1].isspace()):
                        last_by=i
            i+=1
        return last_by

    by_pos=find_by_pos(s)
    if by_pos!=-1:
        agg_part=s[:by_pos].strip()
        by_part=s[by_pos:].strip()
        m=re.match(r'by\s+(.+)$', by_part, re.IGNORECASE)
        if not m:
            raise ValueError("Invalid by")
        by_fields_str=m.group(1)
        by_parts=split_by_commas_outside_parens(by_fields_str)
        by_fields=[]
        by_fields_raw=[]
        for part in by_parts:
            part=part.strip()
            if not part:
                continue
            expr=parse_expression(part)
            by_fields.append(expr)
            by_fields_raw.append(part)
    else:
        agg_part=s
        by_fields=[]
        by_fields_raw=[]

    agg_funcs=[]
    agg_parts=split_by_commas_outside_parens(agg_part)
    for part in agg_parts:
        part=part.strip()
        if not part:
            continue
        m=re.match(r'^(\w+)(?:\s*\(\s*(.*)\s*\))?(?:\s+as\s+(\S+))?\s*$', part, re.IGNORECASE)
        if not m:
            raise ValueError(f"Invalid aggregate {part}")
        func_name=m.group(1)
        args_str=m.group(2)
        as_field=m.group(3)
        low_func=func_name.lower()
        is_agg=False
        if low_func in ('count','count_distinct','sum','avg','average','min','max','total'):
            is_agg=True
        elif re.match(r'^p\d+$', low_func):
            is_agg=True
        if not is_agg:
            # Try as field expr? Already handled, so error
            print(f"error: Expected an operator", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"1 | {full_query_for_error or s}", file=sys.stderr)
            # Find position of func_name in full query?
            idx=(full_query_for_error or s).find(func_name)
            if idx==-1:
                idx=0
            print(f"  | {' '*idx}{'^'*len(func_name)}", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"  = help: {func_name} is not a valid operator", file=sys.stderr)
            print(f"Error: Failed to parse query", file=sys.stderr)
            sys.exit(1)
        arg_expr=None
        if args_str is not None:
            args_str=args_str.strip()
            if args_str!='':
                arg_expr=parse_expression(args_str)
        else:
            if low_func!='count':
                raise ValueError("Missing args")
        if low_func=='total' and by_fields:
            print(f"error: unrecognized option, only the 'as' option is available", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"1 | {full_query_for_error or s}", file=sys.stderr)
            idx=(full_query_for_error or s).lower().find('by')
            print(f"  | {' '*idx}{'^'*2}", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"Error: Failed to parse query", file=sys.stderr)
            sys.exit(1)
        agg_funcs.append(AggFunc(func_name, arg_expr, as_field))

    if not agg_funcs:
        raise ValueError("No aggregates")

    op=AggregateOp(agg_funcs, by_fields, by_fields_raw)
    return op

# ---------- Output formatting ----------
def convert_for_json(obj):
    if isinstance(obj, dict):
        return {k:convert_for_json(v) for k,v in obj.items()}
    if isinstance(obj, list):
        return [convert_for_json(v) for v in obj]
    if isinstance(obj, datetime.datetime):
        if obj.tzinfo is None:
            obj=obj.replace(tzinfo=datetime.timezone.utc)
        return obj.isoformat()
    if isinstance(obj, datetime.timedelta):
        return obj.total_seconds()
    return obj

def format_output(records, output_format, is_aggregate):
    if output_format is None:
        output_format='legacy'
    # Handle -m flag? Already converted to output format? We'll handle output_format that may be like "{a}" (without format= prefix) – treat as format

    if output_format.startswith('format='):
        fmt_str=output_format[len('format='):]
        lines=[]
        for rec in records:
            # Replace {field} with value
            def repl(m):
                field=m.group(1)
                # field may contain formatting like "a:10" – we need to strip after :
                field_name=field.split(':')[0]
                field_name=field_name.strip()
                # For field_name, it could be expression? But for format output, field is simple?
                # We'll try to get value from rec, if not present, "None"
                if field_name in rec:
                    v=rec[field_name]
                    if isinstance(v, datetime.datetime):
                        v=v.isoformat()
                    return str(v)
                else:
                    # Try to evaluate as field ref? For format, field could be missing -> None
                    # Also handle count etc already in rec
                    return "None"
            # Use regex to find {xxx}
            out_line=re.sub(r'\{([^}]+)\}', repl, fmt_str)
            lines.append(out_line)
        return '\n'.join(lines)

    if output_format=='json':
        if is_aggregate:
            converted=[convert_for_json(r) for r in records]
            return json.dumps(converted)
        else:
            # If records empty, output nothing? For '*' with json, it outputs {} per line? For empty input, no lines.
            lines=[]
