                if field in rec:
                    v=rec[field]
                    if isinstance(v, datetime.datetime):
                        v=v.isoformat()
                    return str(v)
                else:
                    return "None"
            out_line=re.sub(r'\{([^}]+)\}', repl, fmt_str)
