                if v is None:
                    sv="null"
                elif isinstance(v,bool):
                    sv=str(v).lower()
                elif isinstance(v, datetime.datetime):
                    sv=v.isoformat()
                elif isinstance(v,list):
                    sv=json.dumps(v)
                elif isinstance(v,dict):
                    sv=json.dumps(v)
                else:
                    sv=str(v)
                parts.append(f"{k}={sv}")
            lines.append(' '.join(parts))
        return '\n'.join(lines)
    if output_format=='legacy':
        if not records:
            return ""
        if is_aggregate:
            keys=list(records[0].keys())
            col_widths={}
            for k in keys:
                max_len=len(str(k))
