            header='        '.join([k.ljust(col_widths[k]) for k in keys])
            sep_len=sum(col_widths.values()) + 8*len(keys)
            sep='-'*sep_len
            lines=[header, sep]
            for rec in records:
                row='        '.join([str(rec.get(k) if rec.get(k) is not None else "null").ljust(col_widths[k]) for k in keys])
                lines.append(row)
            return '\n'.join(lines)
        else:
            lines=[]
            for rec in records:
                if not rec:
                    lines.append("")
                else:
                    keys=sorted(rec.keys())
                    parts=[f"[{k}={rec[k]}]" for k in keys]
                    lines.append('        '.join(parts))
            return '\n'.join(lines)
    return ""

def format_legacy_non_agg(records_with_raw):
    lines=[]
    for rec, raw in records_with_raw:
        if not rec:
            lines.append(raw)
        else:
            keys=sorted(rec.keys())
            parts=[]
            for k in keys:
                v=rec[k]
                if isinstance(v,list):
                    sv=str(v)
                elif isinstance(v,dict):
                    sv=json.dumps(v)
                elif isinstance(v, datetime.datetime):
                    sv=v.isoformat()
                else:
                    sv=str(v)
                parts.append(f"[{k}={sv}]")
            lines.append('        '.join(parts))
    return '\n'.join(lines)

