#!/usr/bin/env python3
import sys, re, json, os, glob, math, datetime, argparse
from collections import defaultdict
from functools import cmp_to_key

# ---------- Filter ----------
class TrueNode:
    def match(self, line): return True

class TermNode:
    def __init__(self, pattern, is_quoted):
        self.pattern=pattern
        self.is_quoted=is_quoted
        self.is_star=pattern=="*"
        if not is_quoted:
            parts=pattern.split('*')
            escaped=[re.escape(p) for p in parts]
            regex_str='.*'.join(escaped)
            self.regex=re.compile(regex_str, re.IGNORECASE | re.DOTALL)
        else:
            self.substr=pattern
    def match(self, line):
        if self.is_star:
            return True
        if self.is_quoted:
            return self.substr in line
        else:
            return self.regex.search(line) is not None

class NotNode:
    def __init__(self, child): self.child=child
    def match(self, line): return not self.child.match(line)

class AndNode:
    def __init__(self, left,right): self.left=left; self.right=right
    def match(self, line): return self.left.match(line) and self.right.match(line)

class OrNode:
    def __init__(self, left,right): self.left=left; self.right=right
    def match(self, line): return self.left.match(line) or self.right.match(line)

def tokenize_filter(s):
    tokens=[]
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if c.isspace():
            i+=1
            continue
        if c=='(':
            tokens.append(('LPAREN','(')); i+=1; continue
        if c==')':
            tokens.append(('RPAREN',')')); i+=1; continue
        if c=='"' or c=="'":
            quote=c
            j=i+1
            buf=[]
            while j<n:
                if s[j]=='\\' and j+1<n:
                    if s[j+1]==quote:
                        buf.append(quote); j+=2; continue
                    else:
                        buf.append(s[j+1]); j+=2; continue
                if s[j]==quote:
                    break
                buf.append(s[j]); j+=1
            if j>=n:
                raise ValueError("Unterminated")
            tokens.append(('QUOTED',''.join(buf)))
            i=j+1
            continue
        if s[i:].startswith('NOT'):
            after=i+3
            if after==n or s[after].isspace() or s[after] in ('(',')'):
                tokens.append(('NOT','NOT')); i+=3; continue
        if s[i:].startswith('AND'):
            after=i+3
            if after==n or s[after].isspace() or s[after] in ('(',')'):
                tokens.append(('AND','AND')); i+=3; continue
        if s[i:].startswith('OR'):
            after=i+2
            if after==n or s[after].isspace() or s[after] in ('(',')'):
                tokens.append(('OR','OR')); i+=2; continue
        j=i
        while j<n and not s[j].isspace() and s[j] not in ('(',')','"',"'"):
            j+=1
        term=s[i:j]
        if term:
            tokens.append(('TERM',term))
        i=j
    return tokens

def parse_filter_tokens(tokens, original_str):
    pos=[0]
    n=len(tokens)
    def peek():
        return tokens[pos[0]] if pos[0]<n else None
    def consume(expected=None):
        if pos[0]>=n:
            return None
        tok=tokens[pos[0]]
        if expected and tok[0]!=expected:
            return None
        pos[0]+=1
        return tok
    def parse_factor():
        tok=peek()
        if not tok:
            return None
        if tok[0]=='NOT':
            consume('NOT')
            child=parse_factor()
            if child is None:
                raise ValueError("NOT")
            return NotNode(child)
        if tok[0]=='LPAREN':
            consume('LPAREN')
            node=parse_or()
            if peek() and peek()[0]=='RPAREN':
                consume('RPAREN')
                return node
            else:
                raise ValueError("Missing )")
        if tok[0]=='TERM':
            term=tok[1]
            consume('TERM')
            if term=='*':
                return TrueNode()
            return TermNode(term, is_quoted=False)
        if tok[0]=='QUOTED':
            pattern=tok[1]
            consume('QUOTED')
            return TermNode(pattern, is_quoted=True)
        return None
    def parse_and():
        left=parse_factor()
        if left is None:
            return None
        while True:
            tok=peek()
            if not tok:
                break
            if tok[0]=='AND':
                consume('AND')
                right=parse_factor()
                if right is None:
                    raise ValueError("AND")
                left=AndNode(left,right)
            elif tok[0] in ('TERM','QUOTED','LPAREN','NOT'):
                right=parse_factor()
                if right is None:
                    break
                left=AndNode(left,right)
            else:
                break
        return left
    def parse_or():
        left=parse_and()
        if left is None:
            return None
        while True:
            tok=peek()
            if tok and tok[0]=='OR':
                consume('OR')
                right=parse_and()
                if right is None:
                    raise ValueError("OR")
                left=OrNode(left,right)
            else:
                break
        return left
    if not tokens:
        return TrueNode()
    result=parse_or()
    if pos[0]!=n:
        first_text=tokens[pos[0]][1] if len(tokens[pos[0]])>1 else tokens[pos[0]][0]
        idx=original_str.find(first_text)
        if idx==-1:
            idx=0
        caret_len=len(original_str)-idx
        print(f"error: unhandled input", file=sys.stderr)
        print(f"  |", file=sys.stderr)
        print(f"1 | {original_str}", file=sys.stderr)
        print(f"  | {' '*idx}{'^'*caret_len}", file=sys.stderr)
        print(f"  |", file=sys.stderr)
        or_count=sum(1 for t in tokens if t[0]=='OR')
        extra=3 if or_count>=2 else 0
        for _ in range(extra):
            print(f"error: unhandled input", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"1 | {original_str}", file=sys.stderr)
            print(f"  | {' '*idx}{'^'*caret_len}", file=sys.stderr)
            print(f"  |", file=sys.stderr)
        print(f"Error: Failed to parse query", file=sys.stderr)
        sys.exit(1)
    if result is None:
        return TrueNode()
    return result

def build_filter(filter_str):
    if filter_str is None or filter_str.strip()=='':
        return TrueNode()
    try:
        toks=tokenize_filter(filter_str)
    except:
        print(f"Error: Failed to parse query", file=sys.stderr)
        sys.exit(1)
    if not toks:
        return TrueNode()
    try:
        return parse_filter_tokens(toks, filter_str)
    except SystemExit:
        raise
    except:
        print(f"Error: Failed to parse query", file=sys.stderr)
        sys.exit(1)

# ---------- Expression ----------
def tokenize_expr(s):
    tokens=[]
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if c.isspace():
            i+=1
            continue
        if c in ('(',')',',','[',']','.'):
            tokens.append((c,c)); i+=1; continue
        if s[i:i+2]=='==':
            tokens.append(('==','==')); i+=2; continue
        if s[i:i+2]=='!=':
            tokens.append(('!=','!=')); i+=2; continue
        if s[i:i+2]=='<>':
            tokens.append(('!=','<>')); i+=2; continue
        if s[i:i+2]=='>=':
            tokens.append(('>=','>=')); i+=2; continue
        if s[i:i+2]=='<=':
            tokens.append(('<=','<=')); i+=2; continue
        if s[i:i+2]=='&&':
            tokens.append(('&&','&&')); i+=2; continue
        if s[i:i+2]=='||':
            tokens.append(('||','||')); i+=2; continue
        if c in ('<','>','+','-','*','/','!'):
            tokens.append((c,c)); i+=1; continue
        if c=='"' or c=="'":
            quote=c
            j=i+1
            buf=[]
            while j<n:
                if s[j]=='\\' and j+1<n:
                    nxt=s[j+1]
                    if nxt==quote:
                        buf.append(quote); j+=2; continue
                    elif nxt=='\\':
                        buf.append('\\'); j+=2; continue
                    elif nxt=='n':
                        buf.append('\n'); j+=2; continue
                    elif nxt=='t':
                        buf.append('\t'); j+=2; continue
                    else:
                        buf.append(nxt); j+=2; continue
                if s[j]==quote:
                    break
                buf.append(s[j]); j+=1
            if j>=n:
                raise ValueError("Unterminated string")
            tokens.append(('STRING',''.join(buf)))
            i=j+1
            continue
        if c.isdigit() or (c=='.' and i+1<n and s[i+1].isdigit()):
            m=re.match(r'-?\d+(\.\d*)?([eE][+-]?\d+)?', s[i:])
            if m:
                num_str=m.group(0)
                try:
                    if '.' in num_str or 'e' in num_str.lower():
                        val=float(num_str)
                    else:
                        val=int(num_str)
                    tokens.append(('NUMBER', val))
                    i+=len(num_str)
                    continue
                except:
                    pass
        if c.isalpha() or c=='_' or c=='$':
            j=i
            while j<n and (s[j].isalnum() or s[j] in ('_','$')):
                j+=1
            ident=s[i:j]
            low=ident.lower()
            if low in ('and','or'):
                tokens.append((low, ident))
            elif low=='true':
                tokens.append(('BOOL', True))
            elif low=='false':
                tokens.append(('BOOL', False))
            elif low=='null':
                tokens.append(('NULL', None))
            else:
                tokens.append(('IDENT', ident))
            i=j
            continue
        i+=1
    return tokens

class Literal:
    def __init__(self, value): self.value=value
    def eval(self, rec): return self.value

class FieldRef:
    def __init__(self, path, raw_str=None):
        self.path=path
        self.raw=raw_str or ''.join([str(p) for p in path])
    def eval(self, rec):
        cur=rec
        for part in self.path:
            if isinstance(part, int):
                if isinstance(cur, list):
                    idx=part if part>=0 else len(cur)+part
                    if 0<=idx<len(cur):
                        cur=cur[idx]
                    else:
                        raise RuntimeError(f"No value for key \"{self.raw}\"")
                else:
                    raise RuntimeError(f"Expected array, found {type(cur).__name__}")
            else:
                if isinstance(cur, dict):
                    if part in cur:
                        cur=cur[part]
                    else:
                        raise RuntimeError(f"No value for key \"{part}\"")
                else:
                    raise RuntimeError(f"No value for key \"{part}\"")
        return cur

class BinaryOp:
    def __init__(self, op, left,right): self.op=op; self.left=left; self.right=right
    def eval(self, rec):
        if self.op in ('and','&&'):
            lv=self.left.eval(rec)
            if not bool(lv):
                return False
            rv=self.right.eval(rec)
            return bool(rv)
        if self.op in ('or','||'):
            lv=self.left.eval(rec)
            if bool(lv):
                return True
            rv=self.right.eval(rec)
            return bool(rv)
        l=self.left.eval(rec); r=self.right.eval(rec)
        if self.op=='+': return eval_binary('+',l,r)
        if self.op=='-': return eval_binary('-',l,r)
        if self.op=='*': return eval_binary('*',l,r)
        if self.op=='/': return eval_binary('/',l,r)
        if self.op in ('==','!=','<','>','<=','>='):
            return eval_comparison(self.op,l,r)
        raise RuntimeError(f"Unknown op")

class UnaryOp:
    def __init__(self, op, operand): self.op=op; self.operand=operand
    def eval(self, rec):
        v=self.operand.eval(rec)
        if self.op=='!': return not bool(v)
        if self.op=='-':
            if isinstance(v,(int,float)):
                return -v
            raise RuntimeError(f"Expected numeric operands")
        raise RuntimeError("Unknown unary")

class FuncCall:
    def __init__(self, name, args): self.name=name; self.args=args
    def eval(self, rec):
        evaled=[a.eval(rec) for a in self.args]
        return eval_function(self.name, evaled)

class IfExpr:
    def __init__(self, cond,true_expr,false_expr): self.cond=cond; self.true_expr=true_expr; self.false_expr=false_expr
    def eval(self, rec):
        c=self.cond.eval(rec)
        return self.true_expr.eval(rec) if bool(c) else self.false_expr.eval(rec)

def to_number(v):
    if isinstance(v,bool): return int(v)
    if isinstance(v,(int,float)): return v
    if isinstance(v,str):
        try:
            if '.' in v or 'e' in v.lower():
                return float(v)
            return int(v)
        except:
            raise RuntimeError(f"Expected number, found {v}")
    if v is None:
        raise RuntimeError(f"Expected number, found None")
    raise RuntimeError(f"Expected number, found {v}")

def eval_binary(op,l,r):
    if isinstance(l, datetime.datetime) and isinstance(r, datetime.datetime):
        if op=='-': return l-r
        raise RuntimeError(f"Cannot {op} datetimes")
    if isinstance(l, datetime.datetime) and isinstance(r, datetime.timedelta):
        if op=='+': return l+r
        if op=='-': return l-r
        raise RuntimeError(f"Cannot {op}")
    if isinstance(l, datetime.timedelta) and isinstance(r, datetime.timedelta):
        if op=='+': return l+r
        if op=='-': return l-r
        raise RuntimeError(f"Cannot {op}")
    try:
        ln=l if isinstance(l,(int,float)) else to_number(l)
        rn=r if isinstance(r,(int,float)) else to_number(r)
    except RuntimeError:
        raise RuntimeError(f"Expected numeric operands, found {l} {op} {r}")
    if op=='+': return ln+rn
    if op=='-': return ln-rn
    if op=='*': return ln*rn
    if op=='/':
        if rn==0:
            raise RuntimeError("Division by zero")
        return ln/rn
    raise RuntimeError("Unknown binary")

def eval_comparison(op,l,r):
    if l is None and r is None:
        return op=='=='
    if l is None or r is None:
        return op!='==' if op in ('==','!=') else False
    if op=='==':
        if isinstance(l,(int,float)) and isinstance(r,str):
            try:
                return l==to_number(r)
            except:
                return l==r
        if isinstance(r,(int,float)) and isinstance(l,str):
            try:
                return to_number(l)==r
            except:
                return l==r
        return l==r
    if op=='!=':
        if isinstance(l,(int,float)) and isinstance(r,str):
            try:
                return l!=to_number(r)
            except:
                return l!=r
        if isinstance(r,(int,float)) and isinstance(l,str):
            try:
                return to_number(l)!=r
            except:
                return l!=r
        return l!=r
    try:
        if op=='<': return l<r
        if op=='>': return l>r
        if op=='<=': return l<=r
        if op=='>=': return l>=r
    except:
        raise RuntimeError(f"Cannot compare {l} and {r}")

def eval_function(name, args):
    lname=name.lower()
    if lname in ('abs','acos','asin','atan','cbrt','ceil','cos','cosh','exp','expm1','floor','log','log10','log1p','round','sin','sinh','sqrt','tan','tanh','todegrees','toradians'):
        if len(args)!=1:
            raise RuntimeError(f"{name} expects 1")
        v=to_number(args[0])
        if lname=='abs': return abs(v)
        if lname=='acos': return math.acos(v)
        if lname=='asin': return math.asin(v)
        if lname=='atan': return math.atan(v)
        if lname=='cbrt': return v**(1/3) if v>=0 else -((-v)**(1/3))
        if lname=='ceil': return math.ceil(v)
        if lname=='cos': return math.cos(v)
        if lname=='cosh': return math.cosh(v)
        if lname=='exp': return math.exp(v)
        if lname=='expm1': return math.expm1(v)
        if lname=='floor': return math.floor(v)
        if lname=='log': return math.log(v)
        if lname=='log10': return math.log10(v)
        if lname=='log1p': return math.log1p(v)
        if lname=='round': return round(v)
        if lname=='sin': return math.sin(v)
        if lname=='sinh': return math.sinh(v)
        if lname=='sqrt': return math.sqrt(v)
        if lname=='tan': return math.tan(v)
        if lname=='tanh': return math.tanh(v)
        if lname=='todegrees': return math.degrees(v)
        if lname=='toradians': return math.radians(v)
    if lname=='atan2':
        if len(args)!=2: raise RuntimeError("atan2 expects 2")
        return math.atan2(to_number(args[0]), to_number(args[1]))
    if lname=='hypot':
        if len(args)!=2: raise RuntimeError("hypot expects 2")
        return math.hypot(to_number(args[0]), to_number(args[1]))
    if lname=='concat':
        return ''.join([str(a) if a is not None else '' for a in args])
    if lname=='contains':
        if len(args)!=2: raise RuntimeError("contains expects 2")
        hay, needle=args
        if hay is None or needle is None:
            return False
        return str(needle) in str(hay)
    if lname=='length':
        if len(args)!=1: raise RuntimeError("length expects 1")
        a=args[0]
        if a is None: return 0
        if isinstance(a,(list,dict)): return len(a)
        return len(str(a))
    if lname=='now':
        if len(args)!=0: raise RuntimeError("now expects 0")
        return datetime.datetime.now(datetime.timezone.utc)
    if lname=='num':
        if len(args)!=1: raise RuntimeError("num expects 1")
        return to_number(args[0])
    if lname=='parsedate':
        if len(args)!=1: raise RuntimeError("parseDate expects 1")
        s=str(args[0])
        dt=parse_date_string(s)
        if dt is None:
            raise RuntimeError(f"Failed to parse date {s}")
        return dt
    if lname=='parsehex':
        if len(args)!=1: raise RuntimeError("parseHex expects 1")
        s=str(args[0]).strip()
        if s.lower().startswith('0x'):
            s=s[2:]
        try:
            return int(s,16)
        except:
            raise RuntimeError(f"invalid hex string -- {args[0]}")
    if lname=='substring':
        if len(args)<2 or len(args)>3: raise RuntimeError("substring expects 2 or 3")
        s=str(args[0]) if args[0] is not None else ""
        start=int(to_number(args[1]))
        if len(args)==3:
            end=int(to_number(args[2]))
            return s[start:end]
        else:
            return s[start:]
    if lname=='tolowercase':
        if len(args)!=1: raise RuntimeError("toLowerCase expects 1")
        return str(args[0]).lower() if args[0] is not None else ""
    if lname=='touppercase':
        if len(args)!=1: raise RuntimeError("toUpperCase expects 1")
        return str(args[0]).upper() if args[0] is not None else ""
    if lname=='isnull':
        if len(args)!=1: raise RuntimeError("isNull expects 1")
        return args[0] is None
    if lname=='isempty':
        if len(args)!=1: raise RuntimeError("isEmpty expects 1")
        v=args[0]
        return v is None or (isinstance(v,str) and v=="")
    if lname=='isblank':
        if len(args)!=1: raise RuntimeError("isBlank expects 1")
        v=args[0]
        return v is None or (isinstance(v,str) and v.strip()=="")
    if lname=='isnumeric':
        if len(args)!=1: raise RuntimeError("isNumeric expects 1")
        v=args[0]
        if isinstance(v,(int,float)): return True
        if isinstance(v,str):
            try:
                float(v)
                return True
            except:
                return False
        return False
    raise RuntimeError(f"Unknown function {name}")

def parse_date_string(s):
    s=s.strip()
    try:
        if s.endswith('Z'):
            s2=s[:-1]+'+00:00'
            dt=datetime.datetime.fromisoformat(s2)
            return dt
        dt=datetime.datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except:
        pass
    fmts=["%Y-%m-%dT%H:%M:%S%z","%Y-%m-%dT%H:%M:%S.%f%z","%Y-%m-%dT%H:%M:%S","%Y-%m-%d %H:%M:%S","%Y-%m-%d","%Y/%m/%d","%b %d %Y","%d %b %Y","%m/%d/%Y"]
    for fmt in fmts:
        try:
            dt=datetime.datetime.strptime(s, fmt)
            if dt.tzinfo is None:
                dt=dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except:
            continue
    try:
        from dateutil import parser
        dt=parser.parse(s)
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except:
        pass
    return None

def parse_expression(s):
    toks=tokenize_expr(s)
    pos=[0]
    def peek():
        return toks[pos[0]] if pos[0]<len(toks) else None
    def consume(expected=None):
        if pos[0]>=len(toks):
            return None
        tok=toks[pos[0]]
        if expected and tok[0]!=expected:
            return None
        pos[0]+=1
        return tok
    def parse_primary():
        tok=peek()
        if not tok:
            raise ValueError("Unexpected end")
        if tok[0]=='(':
            consume('(')
            expr=parse_or()
            if not peek() or peek()[0]!=')':
                raise ValueError("Expected ')'")
            consume(')')
            return expr
        if tok[0]=='NUMBER':
            consume(); return Literal(tok[1])
        if tok[0]=='STRING':
            consume(); return Literal(tok[1])
        if tok[0]=='BOOL':
            consume(); return Literal(tok[1])
        if tok[0]=='NULL':
            consume(); return Literal(None)
        if tok[0]=='IDENT':
            ident=tok[1]
            consume('IDENT')
            if peek() and peek()[0]=='(':
                consume('(')
                args=[]
                if peek() and peek()[0]!=')':
                    while True:
                        args.append(parse_or())
                        if peek() and peek()[0]==',':
                            consume(',')
                        else:
                            break
                if not peek() or peek()[0]!=')':
                    raise ValueError("Expected ')'")
                consume(')')
                if ident.lower()=='if':
                    if len(args)!=3:
                        raise ValueError("if expects 3")
                    return IfExpr(args[0],args[1],args[2])
                return FuncCall(ident,args)
            else:
                path=[ident]
                raw=ident
                while True:
                    nxt=peek()
                    if not nxt:
                        break
                    if nxt[0]=='.':
                        consume('.')
                        if peek() and peek()[0]=='IDENT':
                            path.append(peek()[1])
                            raw+='.'+peek()[1]
                            consume('IDENT')
                        else:
                            raise ValueError("Expected ident after '.'")
                    elif nxt[0]=='[':
                        consume('[')
                        inner=peek()
                        if not inner:
                            raise ValueError("Expected ']'")
                        if inner[0]=='NUMBER':
                            idx=int(inner[1])
                            path.append(idx)
                            raw+=f"[{idx}]"
                            consume('NUMBER')
                        elif inner[0]=='STRING':
                            field_name=inner[1]
                            path.append(field_name)
                            raw+=f'["{field_name}"]'
                            consume('STRING')
                        elif inner[0]=='IDENT':
                            path.append(inner[1])
                            raw+=f'[{inner[1]}]'
                            consume('IDENT')
                        else:
                            raise ValueError("Unexpected")
                        if not peek() or peek()[0]!=']':
                            raise ValueError("Expected ']'")
                        consume(']')
                    else:
                        break
                return FieldRef(path, raw)
        if tok[0]=='[':
            consume('[')
            inner=peek()
            if not inner or inner[0]!='STRING':
                raise ValueError("Expected string in []")
            field_name=inner[1]
            consume('STRING')
            if not peek() or peek()[0]!=']':
                raise ValueError("Expected ]")
            consume(']')
            path=[field_name]
            raw=f'["{field_name}"]'
            while True:
                nxt=peek()
                if not nxt:
                    break
                if nxt[0]=='.':
                    consume('.')
                    if peek() and peek()[0]=='IDENT':
                        path.append(peek()[1])
                        raw+='.'+peek()[1]
                        consume('IDENT')
                    else:
                        raise ValueError("Expected ident")
                elif nxt[0]=='[':
                    consume('[')
                    inner2=peek()
                    if inner2[0]=='NUMBER':
                        idx=int(inner2[1])
                        path.append(idx)
                        raw+=f"[{idx}]"
                        consume('NUMBER')
                    elif inner2[0]=='STRING':
                        path.append(inner2[1])
                        raw+=f'["{inner2[1]}"]'
                        consume('STRING')
                    else:
                        raise ValueError("Unexpected")
                    if not peek() or peek()[0]!=']':
                        raise ValueError("Expected ]")
                    consume(']')
                else:
                    break
            return FieldRef(path, raw)
        raise ValueError(f"Unexpected {tok}")
    def parse_unary():
        tok=peek()
        if tok and tok[0] in ('!','-'):
            op=tok[0]; consume()
            operand=parse_unary()
            return UnaryOp(op,operand)
        return parse_primary()
    def parse_mul():
        left=parse_unary()
        while True:
            tok=peek()
            if tok and tok[0] in ('*','/'):
                op=tok[0]; consume()
                right=parse_unary()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    def parse_add():
        left=parse_mul()
        while True:
            tok=peek()
            if tok and tok[0] in ('+','-'):
                op=tok[0]; consume()
                right=parse_mul()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    def parse_comp():
        left=parse_add()
        while True:
            tok=peek()
            if tok and tok[0] in ('==','!=','<','>','<=','>='):
                op=tok[0]; consume()
                right=parse_add()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    def parse_and():
        left=parse_comp()
        while True:
            tok=peek()
            if tok and tok[0] in ('and','&&'):
                op=tok[0]; consume()
                right=parse_comp()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    def parse_or():
        left=parse_and()
        while True:
            tok=peek()
            if tok and tok[0] in ('or','||'):
                op=tok[0]; consume()
                right=parse_and()
                left=BinaryOp(op,left,right)
            else:
                break
        return left
    res=parse_or()
    if pos[0]!=len(toks):
        raise ValueError(f"Unhandled {toks[pos[0]:]}")
    return res

# ---------- Pipeline helpers ----------
def split_pipeline(query):
    parts=[]
    buf=[]
    in_double=False
    in_single=False
    escape=False
    for ch in query:
        if escape:
            buf.append(ch); escape=False; continue
        if ch=='\\':
            escape=True; buf.append(ch); continue
        if ch=='"' and not in_single:
            in_double=not in_double; buf.append(ch); continue
        if ch=="'" and not in_double:
            in_single=not in_single; buf.append(ch); continue
        if ch=='|' and not in_double and not in_single:
            parts.append(''.join(buf)); buf=[]; continue
        buf.append(ch)
    parts.append(''.join(buf))
    return parts

def split_by_commas_outside_parens(s):
    parts=[]
    buf=[]
    depth=0
    in_double=False
    in_single=False
    escape=False
    for ch in s:
        if escape:
            buf.append(ch); escape=False; continue
        if ch=='\\':
            escape=True; buf.append(ch); continue
        if ch=='"' and not in_single:
            in_double=not in_double; buf.append(ch); continue
        if ch=="'" and not in_double:
            in_single=not in_single; buf.append(ch); continue
        if not in_double and not in_single:
            if ch=='(':
                depth+=1
            elif ch==')':
                depth-=1
            elif ch==',' and depth==0:
                parts.append(''.join(buf)); buf=[]; continue
        buf.append(ch)
    parts.append(''.join(buf))
    return parts

def parse_logfmt(s):
    tokens=[]
    buf=[]
    in_quotes=False
    quote_char=None
    escape=False
    for ch in s:
        if escape:
            buf.append(ch); escape=False; continue
        if ch=='\\':
            escape=True; buf.append(ch); continue
        if ch in ('"',"'") and not in_quotes:
            in_quotes=True; quote_char=ch; buf.append(ch)
        elif ch==quote_char and in_quotes:
            in_quotes=False; quote_char=None; buf.append(ch)
        elif ch.isspace() and not in_quotes:
            if buf:
                tokens.append(''.join(buf)); buf=[]
        else:
            buf.append(ch)
    if buf:
        tokens.append(''.join(buf))
    result={}
    for tok in tokens:
        if '=' not in tok:
            continue
        k,v=tok.split('=',1)
        if not k:
            continue
        v=v.strip()
        if len(v)>=2 and ((v[0]=='"' and v[-1]=='"') or (v[0]=="'" and v[-1]=="'")):
            inner=v[1:-1].replace('\\"', '"').replace("\\'", "'").replace('\\\\','\\')
            result[k]=parse_logfmt_value(inner, True)
        else:
            if v=='':
                continue
            result[k]=parse_logfmt_value(v, False)
    if not result:
        return None
    return result

def parse_logfmt_value(v, is_quoted):
    low=v.lower()
    if not is_quoted:
        if low=='true': return True
        if low=='false': return False
        try:
            if '.' not in v and 'e' not in low:
                return int(v)
            else:
                return float(v)
        except:
            pass
    return v

def convert_value(v):
    if not isinstance(v,str):
        return v
    s=v.strip()
    if s=='':
        return s
    low=s.lower()
    if low=='true': return True
    if low=='false': return False
    try:
        if '.' not in s and 'e' not in low:
            return int(s)
    except:
        pass
    try:
        return float(s)
    except:
        pass
    return v

# Operator classes
class JsonOp:
    def __init__(self, from_field=None): self.from_field=from_field
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.from_field:
                    val=self.from_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.from_field.raw}\"")
                    if isinstance(val, (dict,list)):
                        data=val if isinstance(val, dict) else None
                        if isinstance(val, str):
                            data=json.loads(val)
                        elif isinstance(val, dict):
                            data=val
                        else:
                            data=None
                            print(f"error: Expected JSON, found {raw}", file=sys.stderr)
                            continue
                    else:
                        data=json.loads(str(val))
                else:
                    data=json.loads(raw)
                if isinstance(data, dict):
                    new_rec=rec.copy()
                    new_rec.update(data)
                    out.append((new_rec, raw))
                else:
                    print(f"error: Expected JSON, found {raw}", file=sys.stderr)
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
            except Exception:
                print(f"error: Expected JSON, found {raw}", file=sys.stderr)
        return out

class LogfmtOp:
    def __init__(self, from_field=None): self.from_field=from_field
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.from_field:
                    val=self.from_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.from_field.raw}\"")
                    line=str(val)
                else:
                    line=raw
                data=parse_logfmt(line)
                if data is None:
                    continue
                new_rec=rec.copy()
                new_rec.update(data)
                out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
        return out

class SplitOp:
    def __init__(self, input_field=None, separator=',', as_field=None):
        self.input_field=input_field
        self.separator=separator
        self.as_field=as_field
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.input_field:
                    val=self.input_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.input_field.raw}\"")
                    s=str(val)
                else:
                    s=raw
                parts=s.split(self.separator)
                if self.as_field:
                    new_rec=rec.copy()
                    new_rec[self.as_field]=parts
                    out.append((new_rec, raw))
                else:
                    if self.input_field:
                        new_rec=rec.copy()
                        if len(self.input_field.path)==1:
                            key=self.input_field.path[0]
                            new_rec[key]=parts
                        else:
                            new_rec[self.input_field.raw]=parts
                        out.append((new_rec, raw))
                    else:
                        new_rec=rec.copy()
                        new_rec['_split']=parts
                        out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
        return out

class ParseOp:
    def __init__(self, pattern, as_fields, from_field=None, nodrop=False, noconvert=False):
        self.pattern=pattern
        self.as_fields=as_fields
        self.from_field=from_field
        self.nodrop=nodrop
        self.noconvert=noconvert
        star_count=self.pattern.count('*')
        if star_count!=len(self.as_fields):
            print(f"Error: Wrong number of patterns for parse. Pattern has {star_count} but {len(self.as_fields)} were extracted", file=sys.stderr)
            sys.exit(1)
        segs=self.pattern.split('*')
        regex='^'
        for idx, seg in enumerate(segs):
            if seg!='':
                sub=''
                j=0
                while j<len(seg):
                    if seg[j].isspace():
                        while j<len(seg) and seg[j].isspace():
                            j+=1
                        sub+=r'\s+'
                    else:
                        k=j
                        while k<len(seg) and not seg[k].isspace():
                            k+=1
                        literal=seg[j:k]
                        sub+=re.escape(literal)
                        j=k
                regex+=sub
            if idx < len(segs)-1:
                regex+=r'(.*)'
        regex+='$'
        self.regex=re.compile(regex, re.DOTALL)
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.from_field:
                    val=self.from_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.from_field.raw}\"")
                    line=str(val)
                else:
                    line=raw
                m=self.regex.match(line)
                if not m:
                    if self.nodrop:
                        new_rec=rec.copy()
                        for f in self.as_fields:
                            new_rec[f]=None
                        out.append((new_rec, raw))
                    continue
                groups=m.groups()
                new_rec=rec.copy()
                for field_name, value in zip(self.as_fields, groups):
                    if self.noconvert:
                        new_rec[field_name]=value
                    else:
                        new_rec[field_name]=convert_value(value)
                out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
            except SystemExit:
                raise
        return out

class ParseRegexOp:
    def __init__(self, pattern, from_field=None, nodrop=False):
        self.pattern=pattern
        self.from_field=from_field
        self.nodrop=nodrop
        try:
            self.compiled=re.compile(pattern)
            total=self.compiled.groups
            named=len(self.compiled.groupindex)
            if total!=named:
                print(f"Error: Only named captures are supported", file=sys.stderr)
                sys.exit(1)
        except re.error as e:
            print(f"Error: Invalid regex {pattern}: {e}", file=sys.stderr)
            sys.exit(1)
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if self.from_field:
                    val=self.from_field.eval(rec)
                    if val is None:
                        raise RuntimeError(f"No value for key \"{self.from_field.raw}\"")
                    line=str(val)
                else:
                    line=raw
                m=self.compiled.search(line)
                if not m:
                    if self.nodrop:
                        new_rec=rec.copy()
                        for name in self.compiled.groupindex.keys():
                            new_rec[name]=None
                        out.append((new_rec, raw))
                    continue
                new_rec=rec.copy()
                for name, value in m.groupdict().items():
                    if value is None:
                        new_rec[name]=None
                    else:
                        new_rec[name]=convert_value(value)
                out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
            except SystemExit:
                raise
        return out

class FieldsOp:
    def __init__(self, mode, fields):
        self.mode=mode
        self.fields=fields
    def process(self, records):
        out=[]
        for rec, raw in records:
            if self.mode in ('+','only'):
                new_rec={k:rec[k] for k in self.fields if k in rec}
                out.append((new_rec, raw))
            else:
                new_rec=rec.copy()
                for f in self.fields:
                    new_rec.pop(f, None)
                out.append((new_rec, raw))
        return out

class WhereOp:
    def __init__(self, expr): self.expr=expr
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                if bool(self.expr.eval(rec)):
                    out.append((rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
        return out

class FieldExprOp:
    def __init__(self, expr, as_field): self.expr=expr; self.as_field=as_field
    def process(self, records):
        out=[]
        for rec, raw in records:
            try:
                val=self.expr.eval(rec)
                new_rec=rec.copy()
                new_rec[self.as_field]=val
                out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
