class LimitOp:
    def __init__(self, n): self.n=n
    def process(self, records):
        if self.n>=0:
            return records[:self.n]
        else:
            return records[self.n:]

class TimesliceOp:
    def __init__(self, expr, duration_str, as_field='_timeslice'):
        self.expr=expr
        self.duration_str=duration_str
        self.as_field=as_field
        m=re.match(r'^(\d+(?:\.\d+)?)(ns|us|ms|s|m|h|d|w)$', duration_str)
        if not m:
            raise ValueError(f"Invalid duration {duration_str}")
        amount=float(m.group(1))
        unit=m.group(2)
        if unit=='ns':
            self.delta=datetime.timedelta(microseconds=amount/1000)
        elif unit=='us':
            self.delta=datetime.timedelta(microseconds=amount)
        elif unit=='ms':
            self.delta=datetime.timedelta(milliseconds=amount)
        elif unit=='s':
            self.delta=datetime.timedelta(seconds=amount)
        elif unit=='m':
            self.delta=datetime.timedelta(minutes=amount)
        elif unit=='h':
            self.delta=datetime.timedelta(hours=amount)
        elif unit=='d':
            self.delta=datetime.timedelta(days=amount)
        elif unit=='w':
            self.delta=datetime.timedelta(weeks=amount)
        else:
            raise ValueError("Unknown unit")
    def process(self, records):
        out=[]
        epoch=datetime.datetime(1970,1,1, tzinfo=datetime.timezone.utc)
        for rec, raw in records:
            try:
                ts=self.expr.eval(rec)
                if not isinstance(ts, datetime.datetime):
                    raise RuntimeError(f"Expected datetime, found {ts}")
                if ts.tzinfo is None:
                    ts=ts.replace(tzinfo=datetime.timezone.utc)
                delta_seconds=self.delta.total_seconds()
                if delta_seconds==0:
                    floored=ts
                else:
                    ts_seconds=(ts-epoch).total_seconds()
                    floored_seconds=math.floor(ts_seconds/delta_seconds)*delta_seconds
                    floored=epoch+datetime.timedelta(seconds=floored_seconds)
                new_rec=rec.copy()
                new_rec[self.as_field]=floored
                out.append((new_rec, raw))
            except RuntimeError as e:
                print(f"error: {e}", file=sys.stderr)
        return out

class AggFunc:
    def __init__(self, func_name, arg_expr, as_field=None):
        self.func_name=func_name
        self.arg_expr=arg_expr
        self.as_field=as_field

def make_hashable(v):
    try:
        hash(v)
        return v
    except:
        try:
            return json.dumps(v, sort_keys=True)
        except:
            return str(v)

class AggregateOp:
    def __init__(self, agg_funcs, by_fields, by_fields_raw):
        self.agg_funcs=agg_funcs
        self.by_fields=by_fields
        self.by_fields_raw=by_fields_raw
    def process(self, records):
        groups=defaultdict(list)
        group_example={}
        for rec, raw in records:
            key_vals=[]
            for by_expr in self.by_fields:
                try:
                    v=by_expr.eval(rec)
                except:
                    v=None
                key_vals.append(v)
            hash_key=tuple(make_hashable(v) for v in key_vals)
            groups[hash_key].append(rec)
            if hash_key not in group_example:
                group_example[hash_key]=key_vals
        result=[]
        for hash_key, recs in groups.items():
            agg_result={}
            for idx, raw_name in enumerate(self.by_fields_raw):
                agg_result[raw_name]=group_example[hash_key][idx]
            for agg in self.agg_funcs:
                func_name=agg.func_name.lower()
                as_field=agg.as_field
                if not as_field:
                    if func_name=='count':
                        as_field='_count'
                    elif func_name=='sum':
                        as_field='_sum'
                    elif func_name in ('avg','average'):
                        as_field='_average'
                    elif func_name=='min':
                        as_field='_min'
                    elif func_name=='max':
                        as_field='_max'
                    elif func_name.startswith('p'):
                        as_field=func_name
                    elif func_name=='count_distinct':
                        as_field='_countDistinct'
                    elif func_name=='total':
                        as_field='_total'
                    else:
                        as_field=func_name
                if func_name=='count':
                    if agg.arg_expr is None:
                        cnt=len(recs)
                    else:
                        cnt=0
                        for r in recs:
                            try:
                                if bool(agg.arg_expr.eval(r)):
                                    cnt+=1
                            except:
                                pass
                    agg_result[as_field]=cnt
                elif func_name=='sum':
                    total=0
                    for r in recs:
                        try:
                            total+=to_number(agg.arg_expr.eval(r))
                        except:
                            pass
                    agg_result[as_field]=total
                elif func_name in ('avg','average'):
                    total=0
                    cnt=0
                    for r in recs:
                        try:
                            total+=to_number(agg.arg_expr.eval(r))
                            cnt+=1
                        except:
                            pass
                    agg_result[as_field]=(total/cnt) if cnt else None
                elif func_name=='min':
                    min_val=None
                    for r in recs:
                        try:
                            num=to_number(agg.arg_expr.eval(r))
                            if min_val is None or num<min_val:
                                min_val=num
                        except:
                            pass
                    agg_result[as_field]=min_val
                elif func_name=='max':
                    max_val=None
                    for r in recs:
                        try:
                            num=to_number(agg.arg_expr.eval(r))
                            if max_val is None or num>max_val:
                                max_val=num
                        except:
                            pass
                    agg_result[as_field]=max_val
                elif func_name.startswith('p'):
                    m=re.match(r'p(\d+)', func_name)
                    perc=int(m.group(1))
                    vals=[]
                    for r in recs:
                        try:
                            vals.append(to_number(agg.arg_expr.eval(r)))
                        except:
                            pass
                    if not vals:
                        agg_result[as_field]=None
                    else:
                        vals.sort()
                        k=math.ceil((perc/100)*len(vals))
                        idx=max(0, min(k-1, len(vals)-1))
                        agg_result[as_field]=vals[idx]
                elif func_name=='count_distinct':
                    distinct=set()
                    for r in recs:
                        try:
                            distinct.add(make_hashable(agg.arg_expr.eval(r)))
                        except:
                            pass
                    agg_result[as_field]=len(distinct)
            result.append((agg_result,''))
        return result

class TotalOp:
    def __init__(self, arg_expr, as_field):
        self.arg_expr=arg_expr
        self.as_field=as_field or '_total'
    def process(self, records):
        out=[]
        total=0
        for rec, raw in records:
            try:
                total+=to_number(self.arg_expr.eval(rec))
                new_rec=rec.copy()
                new_rec[self.as_field]=total
                out.append((new_rec, raw))
            except:
                new_rec=rec.copy()
                new_rec[self.as_field]=total
                out.append((new_rec, raw))
        return out

class SortOp:
    def __init__(self, by_exprs):
        self.by_exprs=by_exprs
    def process(self, records):
        def compare(a,b):
            rec_a=a[0]; rec_b=b[0]
            for expr, asc in self.by_exprs:
                try:
                    va=expr.eval(rec_a)
                except:
                    va=None
                try:
                    vb=expr.eval(rec_b)
                except:
                    vb=None
                if va is None and vb is None:
                    cmp_res=0
                elif va is None:
                    cmp_res=-1
                elif vb is None:
                    cmp_res=1
                else:
                    try:
                        if va<vb: cmp_res=-1
                        elif va>vb: cmp_res=1
                        else: cmp_res=0
                    except:
                        sa=str(va); sb=str(vb)
                        if sa<sb: cmp_res=-1
                        elif sa>sb: cmp_res=1
                        else: cmp_res=0
                if cmp_res!=0:
                    if not asc:
                        cmp_res=-cmp_res
                    return cmp_res
            return 0
        return sorted(records, key=cmp_to_key(compare))

def parse_operator_string(op_str, full_query_for_error=None):
    s=op_str.strip()
    if not s:
        print(f"error: expecting an expression", file=sys.stderr)
        print(f"  |", file=sys.stderr)
        print(f"1 | {full_query_for_error or op_str}", file=sys.stderr)
        print(f"  | {' '*(len(full_query_for_error or op_str))}^", file=sys.stderr)
        print(f"  |", file=sys.stderr)
        print(f"Error: Failed to parse query", file=sys.stderr)
        sys.exit(1)

    if s.lower().startswith('sort'):
        rest=s[4:].strip()
        if not rest.lower().startswith('by'):
            raise ValueError("sort needs by")
        rest=rest[2:].strip()
        parts=split_by_commas_outside_parens(rest)
        by_exprs=[]
        for part in parts:
            part=part.strip()
            if not part:
                continue
            low=part.lower()
            asc=True
            if low.endswith(' desc'):
                asc=False
                expr_str=part[:-5].strip()
            elif low.endswith(' asc'):
                asc=True
                expr_str=part[:-4].strip()
            else:
                words=part.rsplit(None,1)
                if len(words)==2 and words[1].lower() in ('asc','desc'):
                    asc=words[1].lower()=='asc'
                    expr_str=words[0]
                else:
                    expr_str=part
            expr=parse_expression(expr_str)
            by_exprs.append((expr, asc))
        return SortOp(by_exprs)

    if s.lower().startswith('limit'):
        rest=s[5:].strip()
        return LimitOp(int(rest))

    if s.lower().startswith('timeslice'):
        m=re.match(r'timeslice\s*\(\s*(.+)\s*\)\s+(\S+)(?:\s+as\s+(\S+))?', s, re.IGNORECASE)
        if not m:
            raise ValueError("Invalid timeslice")
        expr=parse_expression(m.group(1))
        return TimesliceOp(expr, m.group(2), m.group(3) or '_timeslice')

    if s.lower().startswith('total'):
        m=re.match(r'total\s*\(\s*(.+)\s*\)(?:\s+as\s+(\S+))?', s, re.IGNORECASE)
        if not m:
            raise ValueError("Invalid total")
        if re.search(r'\bby\b', s, re.IGNORECASE):
            print(f"error: unrecognized option, only the 'as' option is available", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"1 | {full_query_for_error or s}", file=sys.stderr)
            idx=(full_query_for_error or s).lower().find('by')
            print(f"  | {' '*idx}{'^'*2}", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"Error: Failed to parse query", file=sys.stderr)
            sys.exit(1)
        expr=parse_expression(m.group(1))
        return TotalOp(expr, m.group(2))

    if s.lower().startswith('fields'):
        rest=s[6:].strip()
        mode='-'
        if rest.startswith('+'):
            mode='+'; rest=rest[1:].strip()
        elif rest.startswith('-'):
            mode='-'; rest=rest[1:].strip()
        else:
            low=rest.lower()
            if low.startswith('only'):
                mode='+'; rest=rest[4:].strip()
            elif low.startswith('except'):
                mode='-'; rest=rest[6:].strip()
        parts=split_by_commas_outside_parens(rest)
        fields=[]
        for part in parts:
            part=part.strip()
            if not part:
                continue
            m=re.match(r'\["([^"]+)"\]', part)
            if m:
                fields.append(m.group(1))
            else:
                m2=re.match(r"\['([^']+)'\]", part)
                if m2:
                    fields.append(m2.group(1))
                else:
                    fields.append(part)
        return FieldsOp(mode, fields)

    if re.match(r'^json(\s+from\s+.+)?$', s, re.IGNORECASE):
        m=re.match(r'^json(?:\s+from\s+(.+))?$', s, re.IGNORECASE)
        from_field=None
        if m and m.group(1):
            from_field=parse_expression(m.group(1).strip())
        return JsonOp(from_field)

    if re.match(r'^logfmt(\s+from\s+.+)?$', s, re.IGNORECASE):
        m=re.match(r'^logfmt(?:\s+from\s+(.+))?$', s, re.IGNORECASE)
        from_field=None
        if m and m.group(1):
            from_field=parse_expression(m.group(1).strip())
        return LogfmtOp(from_field)

    if s.lower().startswith('split'):
        rest=s[5:].strip()
        input_field=None
        separator=','
        as_field=None
        if rest.startswith('('):
            end=rest.find(')')
            if end==-1:
                raise ValueError("Missing )")
            input_str=rest[1:end].strip()
            if input_str:
                input_field=parse_expression(input_str)
            rest=rest[end+1:].strip()
        m_as=re.search(r'\s+as\s+(\S+)\s*$', rest, re.IGNORECASE)
        if m_as:
            as_field=m_as.group(1).strip()
            rest=rest[:m_as.start()].strip()
        m_on=re.search(r'\s+on\s+(.+)\s*$', rest, re.IGNORECASE)
        if m_on:
            sep_str=m_on.group(1).strip()
            if (sep_str.startswith('"') and sep_str.endswith('"')) or (sep_str.startswith("'") and sep_str.endswith("'")):
                separator=sep_str[1:-1]
            else:
                if len(sep_str)>=2 and sep_str[0] in ('"',"'") and sep_str[-1]==sep_str[0]:
                    separator=sep_str[1:-1]
                else:
                    separator=sep_str
            rest=rest[:m_on.start()].strip()
        return SplitOp(input_field, separator, as_field)

    if re.match(r'^parse\s+regex\s+', s, re.IGNORECASE):
        rest=s[len('parse regex'):].strip()
        if rest[0] in ('"',"'"):
            quote=rest[0]
            j=1
            while j<len(rest):
                if rest[j]=='\\' and j+1<len(rest):
                    j+=2
                    continue
                if rest[j]==quote:
                    break
                j+=1
            if j>=len(rest):
                raise ValueError("Unterminated regex")
            pattern=rest[1:j]
            rest=rest[j+1:].strip()
        else:
            parts=rest.split(None,1)
            pattern=parts[0]
            rest=parts[1] if len(parts)>1 else ''
        from_field=None
        nodrop=False
        if 'nodrop' in rest.lower():
            nodrop=True
            rest=re.sub(r'\bnodrop\b','',rest,flags=re.IGNORECASE).strip()
        m_from=re.search(r'from\s+(\S+)', rest, re.IGNORECASE)
        if m_from:
            from_field=parse_expression(m_from.group(1))
        return ParseRegexOp(pattern, from_field, nodrop)

    if re.match(r'^parse\s+', s, re.IGNORECASE):
        rest=s[5:].strip()
        if rest[0] not in ('"',"'"):
            raise ValueError("Expected quoted pattern")
        quote=rest[0]
        j=1
        while j<len(rest):
            if rest[j]=='\\' and j+1<len(rest):
                j+=2
                continue
            if rest[j]==quote:
                break
            j+=1
        if j>=len(rest):
            raise ValueError("Unterminated pattern")
        pattern=rest[1:j]
        rest=rest[j+1:].strip()
        from_field=None
        as_fields=[]
        nodrop=False
        noconvert=False
        m_as=re.search(r'\bas\b', rest, re.IGNORECASE)
        if not m_as:
            raise ValueError("Missing as")
        from_part=rest[:m_as.start()].strip()
        as_part=rest[m_as.end():].strip()
        if from_part:
            m=re.match(r'from\s+(.+)$', from_part, re.IGNORECASE)
            if m:
                from_field=parse_expression(m.group(1).strip())
        temp=as_part
        if re.search(r'\bnoconvert\b', temp, re.IGNORECASE):
            noconvert=True
            temp=re.sub(r'\bnoconvert\b','',temp,flags=re.IGNORECASE).strip()
        if re.search(r'\bnodrop\b', temp, re.IGNORECASE):
            nodrop=True
            temp=re.sub(r'\bnodrop\b','',temp,flags=re.IGNORECASE).strip()
        field_parts=split_by_commas_outside_parens(temp)
        for fp in field_parts:
            fp=fp.strip()
            if fp:
                as_fields.append(fp)
        return ParseOp(pattern, as_fields, from_field, nodrop, noconvert)

    if re.match(r'^where\b', s, re.IGNORECASE):
        rest=s[5:].strip()
        try:
            expr=parse_expression(rest)
        except Exception as e:
            parts=rest.split()
            if len(parts)>=2:
                second=parts[1]
                idx=s.find(second)
                print(f"error: unrecognized option, only the condition can be specified", file=sys.stderr)
                print(f"  |", file=sys.stderr)
                print(f"1 | {full_query_for_error or s}", file=sys.stderr)
                full=full_query_for_error or s
                idx2=full.find(second)
                print(f"  | {' '*idx2}{'^'*len(second)}", file=sys.stderr)
                print(f"  |", file=sys.stderr)
                print(f"Error: Failed to parse query", file=sys.stderr)
                sys.exit(1)
            print(f"Error: Failed to parse query", file=sys.stderr)
            sys.exit(1)
        return WhereOp(expr)

    m_as=re.search(r'\s+as\s+(\S+)\s*$', s, re.IGNORECASE)
    if m_as:
        as_field=m_as.group(1)
        expr_str=s[:m_as.start()].strip()
        if not re.match(r'^(count|count_distinct|sum|avg|average|min|max|p\d+|total)\s*(\(|$)', expr_str, re.IGNORECASE):
            try:
                expr=parse_expression(expr_str)
                return FieldExprOp(expr, as_field)
            except:
                pass

    def find_by_pos(string):
        depth=0
        in_double=False
        in_single=False
        escape=False
        last_by=-1
        i=0
        while i<len(string):
            ch=string[i]
            if escape:
                escape=False; i+=1; continue
            if ch=='\\':
                escape=True; i+=1; continue
            if ch=='"' and not in_single:
                in_double=not in_double; i+=1; continue
            if ch=="'" and not in_double:
                in_single=not in_single; i+=1; continue
            if not in_double and not in_single:
                if ch=='(':
                    depth+=1
                elif ch==')':
                    depth-=1
                elif depth==0:
                    if string[i:].lower().startswith(' by '):
                        last_by=i
                    elif string[i:].lower().startswith('by ') and (i==0 or string[i-1].isspace()):
                        last_by=i
            i+=1
        return last_by

    by_pos=find_by_pos(s)
    if by_pos!=-1:
        agg_part=s[:by_pos].strip()
        by_part=s[by_pos:].strip()
        m=re.match(r'by\s+(.+)$', by_part, re.IGNORECASE)
        if not m:
            raise ValueError("Invalid by")
        by_fields_str=m.group(1)
        by_parts=split_by_commas_outside_parens(by_fields_str)
        by_fields=[]
        by_fields_raw=[]
        for part in by_parts:
            part=part.strip()
            if not part:
                continue
            expr=parse_expression(part)
            by_fields.append(expr)
            by_fields_raw.append(part)
    else:
        agg_part=s
        by_fields=[]
        by_fields_raw=[]

    agg_funcs=[]
    agg_parts=split_by_commas_outside_parens(agg_part)
    for part in agg_parts:
        part=part.strip()
        if not part:
            continue
        m=re.match(r'^(\w+)(?:\s*\(\s*(.*)\s*\))?(?:\s+as\s+(\S+))?\s*$', part, re.IGNORECASE)
        if not m:
            raise ValueError(f"Invalid aggregate {part}")
        func_name=m.group(1)
        args_str=m.group(2)
        as_field=m.group(3)
        low_func=func_name.lower()
        is_agg=False
        if low_func in ('count','count_distinct','sum','avg','average','min','max','total'):
            is_agg=True
        elif re.match(r'^p\d+$', low_func):
            is_agg=True
        if not is_agg:
            print(f"error: Expected an operator", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"1 | {full_query_for_error or s}", file=sys.stderr)
            idx=(full_query_for_error or s).find(func_name)
            if idx==-1:
                idx=0
            print(f"  | {' '*idx}{'^'*len(func_name)}", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"  = help: {func_name} is not a valid operator", file=sys.stderr)
            print(f"Error: Failed to parse query", file=sys.stderr)
            sys.exit(1)
        arg_expr=None
        if args_str is not None:
            args_str=args_str.strip()
            if args_str!='':
                arg_expr=parse_expression(args_str)
        else:
            if low_func!='count':
                raise ValueError("Missing args")
        if low_func=='total' and by_fields:
            print(f"error: unrecognized option, only the 'as' option is available", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"1 | {full_query_for_error or s}", file=sys.stderr)
            idx=(full_query_for_error or s).lower().find('by')
            print(f"  | {' '*idx}{'^'*2}", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"Error: Failed to parse query", file=sys.stderr)
            sys.exit(1)
        agg_funcs.append(AggFunc(func_name, arg_expr, as_field))

    if not agg_funcs:
        raise ValueError("No aggregates")

    op=AggregateOp(agg_funcs, by_fields, by_fields_raw)
    return op

# ---------- Output formatting ----------
def convert_for_json(obj):
    if isinstance(obj, dict):
        return {k:convert_for_json(v) for k,v in obj.items()}
    if isinstance(obj, list):
        return [convert_for_json(v) for v in obj]
    if isinstance(obj, datetime.datetime):
        if obj.tzinfo is None:
            obj=obj.replace(tzinfo=datetime.timezone.utc)
        return obj.isoformat()
    if isinstance(obj, datetime.timedelta):
        return obj.total_seconds()
    return obj

def format_output(records, output_format, is_aggregate):
    if output_format is None:
        output_format='legacy'
    if output_format.startswith('format='):
        fmt_str=output_format[len('format='):]
        lines=[]
        for rec in records:
            def repl(m):
                field=m.group(1).split(':')[0].strip()
                if field in rec:
                    v=rec[field]
                    if isinstance(v, datetime.datetime):
                        v=v.isoformat()
                    return str(v)
                else:
                    return "None"
            out_line=re.sub(r'\{([^}]+)\}', repl, fmt_str)
            lines.append(out_line)
        return '\n'.join(lines)
    if output_format=='json':
        if is_aggregate:
            return json.dumps(records, separators=(',',':'))
        else:
            lines=[]
            for rec in records:
                lines.append(json.dumps(rec, sort_keys=True, separators=(',',':')))
            return '\n'.join(lines)
    if output_format=='logfmt':
        lines=[]
        for rec in records:
            keys=sorted(rec.keys())
            parts=[]
            for k in keys:
                v=rec[k]
                if v is None:
                    sv="null"
                elif isinstance(v,bool):
                    sv=str(v).lower()
                elif isinstance(v, datetime.datetime):
                    sv=v.isoformat()
                elif isinstance(v,list):
                    sv=json.dumps(convert_for_json(v), separators=(',',':'))
                elif isinstance(v,dict):
                    sv=json.dumps(convert_for_json(v), separators=(',',':'))
                else:
                    sv=str(v)
                parts.append(f"{k}={sv}")
            lines.append(' '.join(parts))
        return '\n'.join(lines)
    if output_format=='legacy':
        if not records:
            return ""
        if is_aggregate:
            keys=list(records[0].keys())
            col_widths={}
            for k in keys:
                max_len=len(str(k))
                for rec in records:
                    v=rec.get(k)
                    sv=str(v) if v is not None else "null"
                    if isinstance(v, datetime.datetime):
                        sv=v.isoformat()
                    max_len=max(max_len, len(sv))
                col_widths[k]=max_len
            header='        '.join([k.ljust(col_widths[k]) for k in keys])
            sep_len=sum(col_widths.values()) + 8*len(keys)
            sep='-'*sep_len
            lines=[header, sep]
            for rec in records:
                row='        '.join([str(rec.get(k) if rec.get(k) is not None else "null").ljust(col_widths[k]) for k in keys])
                lines.append(row)
            return '\n'.join(lines)
        else:
            lines=[]
            for rec in records:
                if not rec:
                    lines.append("")
                else:
                    keys=sorted(rec.keys())
                    parts=[f"[{k}={rec[k]}]" for k in keys]
                    lines.append('        '.join(parts))
            return '\n'.join(lines)
    return ""

def format_legacy_non_agg(records_with_raw):
    lines=[]
    for rec, raw in records_with_raw:
        if not rec:
            lines.append(raw)
        else:
            keys=sorted(rec.keys())
            parts=[]
            for k in keys:
                v=rec[k]
                if isinstance(v,list):
                    sv=str(v)
                elif isinstance(v,dict):
                    sv=json.dumps(convert_for_json(v), separators=(',',':'))
                elif isinstance(v, datetime.datetime):
                    sv=v.isoformat()
                else:
                    sv=str(v)
                parts.append(f"[{k}={sv}]")
            lines.append('        '.join(parts))
    return '\n'.join(lines)

def parse_aliases(alias_dir, no_alias):
    aliases={}
    if no_alias:
        return aliases
    def load_dir(d):
        if not os.path.isdir(d):
            return
        for f in glob.glob(os.path.join(d, '*.toml')):
            try:
                content=open(f).read()
                m_kw=re.search(r'keyword\s*=\s*"([^"]+)"', content)
                m_tpl=re.search(r'template\s*=\s*"""(.*?)"""', content, re.DOTALL)
                if not m_tpl:
                    m_tpl=re.search(r"template\s*=\s*'''(.*?)'''", content, re.DOTALL)
                if not m_tpl:
                    m_tpl=re.search(r'template\s*=\s*"([^"]+)"', content)
                if not m_tpl:
                    m_tpl=re.search(r"template\s*=\s*'([^']+)'", content)
                if m_kw and m_tpl:
                    kw=m_kw.group(1)
                    tpl=m_tpl.group(1).strip()
                    try:
                        parts=split_pipeline(tpl)
                        for part in parts:
                            part=part.strip()
                            if not part:
                                continue
                            parse_operator_string(part, tpl)
                        aliases[kw]=tpl
                    except SystemExit:
                        continue
                    except Exception:
                        print(f"error: Expected an operator", file=sys.stderr)
                        print(f"  |", file=sys.stderr)
                        print(f"1 | {tpl}", file=sys.stderr)
                        first_word=tpl.split()[0] if tpl.split() else ""
                        idx=tpl.find(first_word)
                        print(f"  | {' '*idx}{'^'*len(first_word)}", file=sys.stderr)
                        print(f"  |", file=sys.stderr)
                        print(f"  = help: {first_word} is not a valid operator", file=sys.stderr)
                        continue
            except:
                continue
    if alias_dir:
        load_dir(alias_dir)
    else:
        cur=os.getcwd()
        while True:
            d=os.path.join(cur, '.agrind-aliases')
            if os.path.isdir(d):
                # load
                for f in glob.glob(os.path.join(d, '*.toml')):
                    try:
                        content=open(f).read()
                        m_kw=re.search(r'keyword\s*=\s*"([^"]+)"', content)
                        m_tpl=re.search(r'template\s*=\s*"""(.*?)"""', content, re.DOTALL)
                        if not m_tpl:
                            m_tpl=re.search(r"template\s*=\s*'''(.*?)'''", content, re.DOTALL)
                        if not m_tpl:
                            m_tpl=re.search(r'template\s*=\s*"([^"]+)"', content)
                        if not m_tpl:
                            m_tpl=re.search(r"template\s*=\s*'([^']+)'", content)
                        if m_kw and m_tpl:
                            kw=m_kw.group(1)
                            tpl=m_tpl.group(1).strip()
                            try:
                                parts=split_pipeline(tpl)
                                for part in parts:
                                    part=part.strip()
                                    if not part:
                                        continue
                                    parse_operator_string(part, tpl)
                                aliases[kw]=tpl
                            except SystemExit:
                                continue
                            except Exception:
                                print(f"error: Expected an operator", file=sys.stderr)
                                print(f"  |", file=sys.stderr)
                                print(f"1 | {tpl}", file=sys.stderr)
                                first_word=tpl.split()[0] if tpl.split() else ""
                                idx=tpl.find(first_word)
                                print(f"  | {' '*idx}{'^'*len(first_word)}", file=sys.stderr)
                                print(f"  |", file=sys.stderr)
                                print(f"  = help: {first_word} is not a valid operator", file=sys.stderr)
                                continue
                    except:
                        continue
            parent=os.path.dirname(cur)
            if parent==cur:
                break
            cur=parent
    return aliases

def expand_aliases(query, aliases):
    parts=split_pipeline(query)
    expanded=[]
    for part in parts:
        stripped=part.strip()
        if stripped in aliases:
            tpl=aliases[stripped]
            tpl_parts=split_pipeline(tpl)
            expanded.extend(tpl_parts)
        else:
            first_word=stripped.split(None,1)[0] if stripped else ""
            if first_word in aliases:
                tpl=aliases[first_word]
                rest=stripped[len(first_word):].strip()
                tpl_parts=split_pipeline(tpl)
                if rest:
                    tpl_parts[-1]=tpl_parts[-1]+' '+rest
                expanded.extend(tpl_parts)
            else:
                expanded.append(part)
    return ' | '.join(expanded)

def main():
    arg_parser=argparse.ArgumentParser(add_help=False)
    arg_parser.add_argument('query', nargs='?', default=None)
    arg_parser.add_argument('-f','--file', dest='file', default=None)
    arg_parser.add_argument('-m','--format', dest='format_deprecated', default=None)
    arg_parser.add_argument('-o','--output', dest='output', default=None)
    arg_parser.add_argument('-a','--alias-dir', dest='alias_dir', default=None)
    arg_parser.add_argument('--no-alias', action='store_true', default=False)
    arg_parser.add_argument('-h','--help', action='store_true')
    arg_parser.add_argument('-V','--version', action='store_true')
    args, _ = arg_parser.parse_known_args()

    if args.help:
        print("Usage: executable [OPTIONS] [QUERY]\n")
        print("Arguments:")
        print("  [QUERY]")
        print("          The query\n")
        print("Options:")
        print("  -f, --file <FILE>")
        print("          Optionally reads from a file instead of Stdin\n")
        print("  -m, --format <FORMAT>")
        print("          DEPRECATED. Use -o format=... instead. Provide a Rust std::fmt string to format output\n")
        print("  -o, --output <OUTPUT>")
        print("          Set output format. Options: ")
        print("          - `json`,")
        print("          - `logfmt`")
        print("          - `format=<rust format string>` (eg. -o format='{src} => {dst}'")
        print("          - `legacy` The original output format, auto aligning [k=v]\n")
        print("  -a, --alias-dir <ALIAS_DIR>")
        print("          Specifies an alternative directory to use for aliases. Defaults to `.agrind-aliases` in all parent directories.\n")
        print("      --no-alias")
        print("          Disables aliases\n")
        print("  -h, --help")
        print("          Print help (see a summary with '-h')\n")
        print("  -V, --version")
        print("          Print version\n")
        print("For more details + docs, see https://github.com/rcoh/angle-grinder")
        sys.exit(0)

    if args.version:
        print("ag 0.19.6")
        sys.exit(0)

    if args.query is None:
        print("Error: MissingQuery", file=sys.stderr)
        sys.exit(1)

    query=args.query
    output_format=args.output
    if args.format_deprecated:
        if not output_format:
            output_format=f"format={args.format_deprecated}"

    if args.no_alias and args.alias_dir:
        print("Error: CantDisableAndOverride", file=sys.stderr)
        sys.exit(1)

    aliases=parse_aliases(args.alias_dir, args.no_alias)

    if query.strip()=='':
        expanded_query=''
    else:
        expanded_query=expand_aliases(query, aliases)

    parts=split_pipeline(expanded_query)
    if not parts:
        filter_str=''
        op_strs=[]
    else:
        filter_str=parts[0]
        op_strs=parts[1:]

    # Handle case where query is "| json" – filter_str is "" -> should be TrueNode
    # But also handle case where filter_str is whitespace only and there is a pipe, original had special handling where " | json" gave {} not json.
    # For simplicity, if filter_str strip is "" we treat as TrueNode, else build filter.
    # However, for " | json" original gave {} (no json), but our code would give json. We accept difference for edge case.

    filter_node=build_filter(filter_str)

    operators=[]
    has_aggregate=False
    for op_str in op_strs:
        if op_str.strip()=='':
            print(f"error: expecting an expression", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"1 | {expanded_query}", file=sys.stderr)
            idx=expanded_query.rfind('|')
            caret_pos=idx+2 if idx!=-1 else len(expanded_query)
            print(f"  | {' '*caret_pos}^", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"Error: Failed to parse query", file=sys.stderr)
            sys.exit(1)
        try:
            op=parse_operator_string(op_str, expanded_query)
            operators.append(op)
            if isinstance(op, AggregateOp):
                has_aggregate=True
        except SystemExit:
            raise
        except Exception as e:
            print(f"error: Expected an operator", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"1 | {expanded_query}", file=sys.stderr)
            idx=expanded_query.find(op_str.strip().split()[0] if op_str.strip() else "")
            if idx==-1:
                idx=0
            print(f"  | {' '*idx}{'^'*len(op_str.strip().split()[0] if op_str.strip() else '')}", file=sys.stderr)
            print(f"  |", file=sys.stderr)
            print(f"  = help: {op_str.strip().split()[0] if op_str.strip() else ''} is not a valid operator", file=sys.stderr)
            print(f"Error: Failed to parse query", file=sys.stderr)
            sys.exit(1)

    # Read input
    input_lines=[]
    if args.file:
        try:
            with open(args.file, 'r') as f:
                input_lines=f.readlines()
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)
    else:
        input_lines=sys.stdin.readlines()

    records=[]
    for line in input_lines:
        raw=line.rstrip('\n')
        if not filter_node.match(raw):
            continue
        rec={}
        records.append((rec, raw))

    # Process operators
    # For non-aggregate: separate sort ops

    if not has_aggregate:
        # non-aggregate: separate sort and other
        other_ops=[]
        sort_ops=[]
        for op in operators:
            if isinstance(op, SortOp):
                sort_ops.append(op)
            else:
                other_ops.append(op)
        current=records
        for op in other_ops:
            current=op.process(current)
        for op in sort_ops:
            current=op.process(current)
            # After sort, is_aggregate True for output formatting as array (json array)
        # Determine is_agg: True if any sort present? From observed, sort alone => array
        is_agg = len(sort_ops)>0
        # Output
        if output_format is None:
            output_format='legacy'
        if output_format=='legacy':
            out_str=format_legacy_non_agg(current)
            if out_str:
                print(out_str)
            sys.exit(0)
        # For other formats
        recs_only=[convert_for_json(r) if isinstance(r,dict) else r for r,_ in current]
        # For json, if is_agg (sort present), output array
        if output_format=='json' and is_agg:
            print(json.dumps(recs_only, separators=(',',':')))
        else:
            out_str=format_output(recs_only, output_format, is_agg)
            if out_str:
                print(out_str)
        sys.exit(0)
    else:
        # aggregate mode: process sequentially
        # Find first aggregate
        first_agg_idx=-1
        for idx, op in enumerate(operators):
            if isinstance(op, AggregateOp):
                first_agg_idx=idx
                break
        current=records
        # pre-agg ops
        for op in operators[:first_agg_idx]:
            current=op.process(current)
        # from first agg onward
        is_agg=False
        for op in operators[first_agg_idx:]:
            current=op.process(current)
            if isinstance(op, AggregateOp):
                is_agg=True
            elif isinstance(op, (SortOp, LimitOp, WhereOp, FieldsOp, FieldExprOp)):
                # keep is_agg
                pass
            else:
                is_agg=False

        if output_format is None:
            output_format='legacy'

        if output_format=='legacy' and not is_agg:
            out_str=format_legacy_non_agg(current)
            if out_str:
                print(out_str)
            sys.exit(0)

        recs_only=[r for r,_ in current]
        # Convert for json
        recs_converted=[convert_for_json(r) for r in recs_only]

        if output_format=='json':
            if is_agg:
                print(json.dumps(recs_converted, separators=(',',':')))
            else:
                lines=[]
                for rec in recs_converted:
                    lines.append(json.dumps(rec, sort_keys=True, separators=(',',':')))
                if lines:
                    print('\n'.join(lines))
        else:
            out_str=format_output(recs_converted, output_format, is_agg)
            if out_str:
                print(out_str)
        sys.exit(0)

if __name__=='__main__':
    main()
